SELECT 'moj-all-verified-judgments-review-002-chunk-029' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c17ee6c8-91f0-5ac2-b635-718ec5504e89","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -إقامة حظيرة أغنام بجوار سكن املدعية -املطالبة بإزالة احلظيرة -إقرار املدعى عليه -ثبوت حتقق األذى -اإللزام بإزالة احلظيرة .","document_number":"34167752","case_number":"34100652","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"دعوى منع ضرر -إقامة حظيرة أغنام بجوار سكن املدعية -املطالبة بإزالة احلظيرة -إقرار املدعى عليه -ثبوت حتقق األذى -اإللزام بإزالة احلظيرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/22 :‬هـ‬\n                      ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34167752 :‬‬\n                          ‫َر ْق ُم الدعوى‪34100652 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34331237‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n      ‫دعــوى منــع ضــرر ‪ -‬إقامــة حظيــرة أغنــام بجــوار ســكن املدعيــة‪ -‬املطالبة‬\n      ‫بإزالــة احلظيــرة‪ -‬إقــرار املدعــى عليــه‪ -‬ثبــوت حتقــق األذى‪ -‬اإللــزام‬\n                                                                ‫بإزالــة احلظيــرة ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار)‪.‬‬\n                                          ‫‪ -2‬القاعدة الشرعية‪« :‬الضرر يزال»‪.‬‬\n                                                             ‫‪ -3‬ال عذر ملقر ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أقــام زريبــة أغنــام بجــوار منــزل‬\n      ‫موكلتــه وقــد تســبب ذلــك باألذيــة لهــا مــن روائــح الغنــم وأصواتهــا‪،‬‬\n      ‫لــذا طلــب إزالــة هــذه الزريبــة‪ -‬أقــر املدعــي بأنــه شــريك يف الزريبــة وأن‬\n      ‫إقامــة الزريبــة جــاء الحق ـ ًا علــى ســكن املدعيــة‪ -‬ثبــوت حتقــق وقــوع‬\n      ‫األذيــة للمدعيــة مــن زريبــة احليوانــات التــي أقامهــا املدعــى عليــه ‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليــه بإزالــة حظيــرة احليوانــات التــي بجــوار‬\n      ‫منــزل املدعيــة وإبعادهــا مســافة كافيــة ال تقــل عــن ثالثمائــة متــر‪ -‬قنــع‬\n      ‫وكيــل املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n‫‪353‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 34100652‬وتاريــخ ‪ 1434/03/01‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34524070‬وتاريــخ ‪ 1434/03/01‬ه ـ ففــي يــوم‬\n‫االثنــن املوافق‪1434/03/16‬ه ـ افتتحــت اجللســة الســاعة ‪08 :30‬‬\n‫وفيهــا حضــر وكيــل املدعيــة ‪ .....‬وكالــة بالســجل املدنــي رقــم ‪.....‬‬\n‫وكيــا عــن ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل جنــران‬\n‫برقــم ‪ 370503013147‬يف ‪1430/03/18‬ه ـ ووكالــة احلاضــر تخولــه‬\n‫املرافعــة واملدافعــة وإقامــة الدعــاوى ضــد الغيــر وحضــور اجللســات‬\n‫وطلــب وتقــدمي البينــات وســماع الشــهود وطلــب حتليــف اليمــن وســماعها‬\n‫وردهــا وطلــب اســتئناف األحــكام والقناعــة بهــا واالعتــراض عليهــا‬\n‫واالســتالم والتوقيــع كمــا حضــر حلضــوره املدعــى عليــه ‪ ..... /‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ) .....‬فادعــى األول قائ ـاً‪ :‬أن‬\n‫هــذا احلاضــر قــد أقــام زريبــة أغنــام بجــوار منــزل موكلتــي وقــد تســبب‬\n‫ذلــك باألذيــة لهــا مــن روائــح الغنــم وأصواتهــا أطلــب إزالــة هــذه الزريبــة‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه أجــاب‬\n‫قائ ـاً‪ :‬مــا جــاء يف الدعــوى صحيــح ولكــن هــذه الغنــم ليســت لــي‬\n‫وإمنــا لوالدتــي وأخواتــي وأنــا القائــم بشــؤونهم وأنــا وكيــل عــن والدتــي‬\n‫واألرض التــي فيهــا زريبــة الغنــم هــي لنــا مــن اإلرث وأمــا املدعيــة فهــي‬\n‫قــد اشــترت املوقــع ويوجــد لــدى املدعيــة أغنــام يف موقــع آخــر مــن احلــي‬\n‫هكــذا أجــاب وبســؤال املدعــي وكالــة هــل كان ســكن موكلتــه‬\n\n                                                                                       ‫‪354‬‬\n\f      ‫قبــل وضــع الغنــم أم بعــده فقــال بــل قبلــه هكــذا قــال ووافــق علــى ذلــك‬\n      ‫املدعــى عليــه وبنــاء علــى مــا ســلف ضبطــه فقــد قــررت رفــع اجللســة ليــوم‬\n      ‫األحــد املوافــق ‪1434/03/22‬ه ـ كمــا أمــرت املدعــى عليــه أن يحضــر‬\n      ‫وكالتــه عــن والدتــه فاســتعد بذلــك ورفعــت اجللســة ويف يــوم األحــد‬\n      ‫املوافــق ‪1434/03/22‬ه ـ الســاعة ‪08:00‬وبســؤال املدعــى عليــه عــن‬\n      ‫الوكالــة التــي اســتعد بإحضارهــا يف اجللســة املاضيــة أجــاب بقولــه‪ :‬لــم‬\n      ‫أحضرهــا‪ .‬وبســؤاله هــل هــو شــريك يف األرض التــي وضعــت فيهــا زريبــة‬\n      ‫احليوانــات وهــل هــو مــن وضعهــا أجــاب بقولــه‪ :‬نعــم‪ .‬وبنــاء علــى مــا ســلف‬\n      ‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بوضعــه لزريبــة احليوانــات‬\n      ‫بجــوار منــزل املدعيــة أصالــة وال عــذر ملقــر وملــا هــو معلــوم مــا يصــدر عــن‬\n      ‫زرائــب احليوانــات مــن أذى فقــد ثبــت لــدي حتقــق وقــوع األذيــة للمدعيــة‬\n      ‫أصالــة مــن زريبــة احليوانــات التــي أقامهــا املدعــى عليــه ولقولــه عليــه‬\n      ‫الصــاة والســام‪ « :‬ال ضــرر وال ضــرار « وللقاعــدة الشــرعية «الضــرر‬\n      ‫يــزال» فقــد ألزمــت املدعــى عليــه بإزالــة حظيــرة احليوانــات التــي بجــوار‬\n      ‫منــزل املدعيــة أصالــة وإبعادهــا مســافة كافيــة ال تقــل عــن ثالثمائــة‬\n      ‫متــر وبــه حكمــت وبعــرض احلكــم علــى املدعــي وكالــة قــرر القناعــة‬\n      ‫كمــا قــرر املدعــى عليــه اعتراضــه بالئحــة فجــرى تســليمه نســخة مــن‬\n      ‫ـداء‬\n      ‫احلكــم وأفهمتــه بــأن عليــه تقــدمي اعتراضــه خــال ثالثــن يومـ ًا ابتـ ً‬\n      ‫مــن الغــد وإال ســقط حقــه يف طلــب التمييــز واكتســب احلكــم القطعيــة‬\n      ‫وختمــت اجللســة بذلــك وكان ختامهــا الســاعة ‪ 08 : 30‬وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n                                                                    ‫يف ‪1434/3/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n\n\n‫‪355‬‬\n\f‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪ 341171874‬يف‬\n‫‪1434/08/06‬ه ـ واملرفــق بهــا قــرار املالحظــة الصــادر مــن الدائــرة‬\n‫األولــى برقــم ‪ 34276941‬يف ‪1434/07/23‬ه ـ واملتضمــن مــا نــص‬\n‫احلاجــة منــه‪(( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة تقــرر إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‪ :‬أوال‪ :‬حكــم‬\n‫فضيلتــه بوجــود الضــرر مــن غيــر أن يتحقــق مــن ذلــك مــن جهــة مختصــة‬\n‫والبــد مــن ذلــك‪ .‬ثانيــا‪ :‬ذكــر املعتــرض يف الئحتــه أمــور ًا تلفــت النظــر‬\n‫منهــا أن فضيلتــه أصــدر حكمــن متناقضــن يف القضيــة نفســها وأنــه‬\n‫أرفــق صــورة مــن احلكــم اآلخــر إال أننــا لــم جنــده ملالحظــة ذلــك‪ .‬ثالثـاً‪:‬‬\n‫ذكــر املعتــرض أن املوقــع الــذي بــه زريبــة الغنــم يف مخطــط زراعــي‬\n‫وفضيلتــه خيــر مــن يعلــم الفــرق بــن املخطــط الزراعــي واملخطــط‬\n‫الســكني للتأكــد مــن ذلــك ومراجعــة حكمــه علــى ضــوء ذلــك‪ .‬واهلل‬\n‫املوفــق)) واملذيــل بتوقيــع أصحــاب الفضيلــة قضــاة الدائــرة فضيلــة‬\n‫الشــيخ ‪ .....‬وفضيلــة الشــيخ‪ .....‬وفضيلــة رئيــس الدائــرة ‪ .....‬اهــ‪ .‬فإجابــة‬\n‫علــى مــا ذكــره مشــايخي أصحــاب الفضيلــة أجــزل اهلل مثوبتهم ونفعني‬\n‫بتوجيهاتهــم وأدام توفيقهــم أجيــب مســتعين ًا بــاهلل ســائله ســبحانه‬\n‫التوفيــق والســداد‪ :‬فيمــا يخــص امللحوظــة األولــى فــإن الضــرر مــن‬\n‫مالحقــة أحــواش األغنــام للمســاكن معلــوم حس ـ ًا ممــا لهــا مــن روائــح‬\n‫وأعطانهــا ومــع هــذا فألصحــاب الفضيلــة االطــاع علــى الصــور املرفقــة‬\n‫علــى اللفــة رقــم (‪ )5‬ويتضــح فيهــا أن للمدعــى عليــه حــوش غنــم واســع ًا‬\n‫بعيــد ًا عــن ســكن املدعيــة أصالــة فلمــاذا يصــر علــى مالصقــة حــوش‬\n‫األغنــام موضــوع الدعــوى مبنــزل املدعيــة أصالــة إضافــة إلــى أن الدعــوى‬\n‫هــذه قــد رفــع فيهــا دعــوى بحــق عــام وقــد اطلعــت اجلهــة املختصــة علــى‬\n\n\n                                                                                      ‫‪356‬‬\n\f      ‫املوقــع وقــررت إزالتــه وقــد قمــت بإرفــاق صــورة مــن القــرار الشــرعي‬\n      ‫الطــاع أصحــاب الفضيلــة عليــه وأمــا مــا يخــص امللحــظ الثانــي وهــو‬\n      ‫دعــوى التناقــض فهــو غيــر صحيــح وقــد بنيــت ســبب ردي لدعــوى‬\n      ‫املدعــي باحلــق اخلــاص حيــث كان يدعــي عــن نفســه وبيتــه يبعــد عن بيت‬\n      ‫املدعــى عليــه قرابــة مائتــن وخمســن متــر ًا أمــا يف هــذه الدعــوى فهــو‬\n      ‫يدعــي وكالــة عــن والدتــه التــي بيتهــا مالصــق حلــوش األغنــام مباشــرة‪.‬‬\n      ‫وأمــا مــا يخــص املالحظــة الثالثــة فقــد جــرى منــي ســؤال الطرفــن أيهمــا‬\n      ‫املنشــأ أو ًال منــزل املدعيــة أصالــة أو حــوش األغنــام فأقــرا جميع ـ ًا بــأن‬\n      ‫املنشــأ أو ًال منــزل املدعيــة أصالــة وأمــا مســألة أن املخطــط زراعــي فــا‬\n      ‫أثــر لــه واحلــال مــا ذكــر حاصــل قبــل حــوش األغنــام محــل األذى‪ .‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n      ‫قالــه وأمــاه الفقيــر إلــى عفــو مــواله ‪ .....‬القاضــي باحملكمــة اجلزائيــة‬\n                                              ‫بنجــران حــرر يف ‪1434/08/28‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34331237‬وتاريــخ‬\n                                                    ‫‪1434/10/15‬هـ‬\n\n\n\n\n‫‪357‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":353,"source_page_end":357,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"80c60865ee785571d2a01dff2cc2f9e925bd59407203a4d58ad5d1ea1627d862","normalized_text_hash":"89fab013ce6d9a9b5cf4fac3d179803c3d825051bd6023a29220300b39844442","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p353-34167752"},{"id":"452c9e9b-3949-59c6-b1be-8111af404e0e","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -مطالبة مبنع إسكان عزاب يف حي خاص بالعوائل -إقرار -وقوف القاضي على محل النزاع ومعاينته -ثبوت الدعوى واحلكم بطلبات املدعي .","document_number":"33675732","case_number":"34200299","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"دعوى منع ضرر -مطالبة مبنع إسكان عزاب يف حي خاص بالعوائل -إقرار -وقوف القاضي على محل النزاع ومعاينته -ثبوت الدعوى واحلكم بطلبات املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/29‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33675732 :‬‬\n                   ‫َر ْق ُم الدعوى‪34200299 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34316096‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫دعــوى منــع ضــرر ‪ -‬مطالبــة مبنــع إســكان عــزاب يف حي خــاص بالعوائل‬\n‫‪ -‬إقــرار ‪ -‬وقــوف القاضــي علــى محــل النــزاع ومعاينتــه ‪ -‬ثبــوت الدعــوى‬\n                                                 ‫واحلكــم بطلبــات املدعي ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ وقواعــد العدالــة العامــة الــواردة‬\n                                                       ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان بــأن املدعــى عليــه ميلــك عمــارة مجــاورة لســكنهما يف‬\n‫حــي خــاص بالعوائــل وقــد أســكن فيهــا مجموعــة مــن العمــال العــزاب‬\n‫فتضــرروا مــن ذلــك مبــا هــو مذكــور يف دعواهمــا ‪ ،‬ولــذا طلبــا احلكــم‬\n‫علــى املدعــى عليــه بإخــراج العــزاب الذيــن أســكنهم يف العمــارة وعــدم‬\n‫إســكان أمثالهــم يف املســتقبل‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‬\n‫ودفــع بأنــه عــرض العمــارة إلســكان العوائــل فيهــا فلــم تســتأجر كمــا‬\n‫أن ال يوجــد ضــرر علــى املجاوريــن لوجــود عــزاب يســكنون يف عمــارة‬\n‫مالصقــة مللكــه ‪ -‬قــررت احملكمــة الوقــوف على محل النــزاع ومعاينته‬\n‫فاتضــح أن عمــارة املدعــى عليــه لهــا أبــواب تقابــل مباشــرة منــزل املدعــي‬\n‫وأنــه ال يوجــد ســوى تلــك العمــارة داخــل احلــي أســكن فيهــا املدعــى‬\n\n                                                                                    ‫‪358‬‬\n\f      ‫عليــه عمــاال عزابــا والضــرر متحقــق مــن ذلــك علــى ســكان احلــي مــن‬\n      ‫العوائــل‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بإخــاء العمــارة مــن‬\n      ‫العمــال العــزاب فــور ًا وعــدم إســكان أمثالهــم مســتقبال ‪ -‬قنــع املدعيــان‬\n      ‫باحلكــم وعــارض املدعــى عليــه ‪ -‬قــررت محكمة االســتئناف املصادقة‬\n                                                                      ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬و ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــو‬\n      ‫ضــد احلاضــر معهــم ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ .....‬بقولهمــا اننــا نســكن يف حــي ‪ .....‬داخــل ســكني خــاص بالعوائــل‬\n      ‫وجميــع مــن فيــه مــن الســكان مــن العوائــل وتوجــد عمــارة للمدعــى عليــه‬\n      ‫حتدنــي انــا ‪ .....‬مــن جهــة الشــمال مباشــرة وحتدنــي انــا ‪ .....‬مــن جهــة‬\n      ‫الشــرق قــد اســكن يف هــذه العمــارة مجموعــة مــن العمــال العــزاب مــن‬\n      ‫الباكســتانيني واملصريــن وابــواب العمــارة مــن جهــة اجلنــوب مفتوحــه‬\n      ‫وهــي مقابلــة بيوتنــا مباشــرة والعمــال يدخلــون ويخرجــون مــن هــذه‬\n      ‫األبــواب ويحضــر عندهــم زمــاء لهــم ويحصــل هنــاك اجتماعــات‬\n      ‫خصوص ـ ًا يف الليــل حيــث يشــربون الدخــان ويخرجــون الكراســي‬\n      ‫للجلــوس امــام بيوتنــا وقــد تضررنــا مــن ذلــك كثيــرا باإلضافــة الــى فتــح‬\n      ‫النوافــذ لهــذه العمــارة مــن جهــة اجلنــوب وقــد كلمناهــم وقــام بأغالقهــا‬\n      ‫نطلــب منكــم احلكــم علــى املدعــى عليــه بإخــراج هــؤالء العــزاب‬\n      ‫مــن هــذه العمــارة وعــدم اســكان امثالهــم يف املســتقبل هــذه دعوانــا‬\n\n‫‪359‬‬\n\f‫وبعــرض الدعــوى علــى املدعــى عليــه اجــاب بقولــه مــا ذكــره املدعيــان‬\n‫يف دعواهمــا أن هــذه العمــارة لــي واننــي قمــت بإســكان العمــال العــزاب‬\n‫صحيــح وذلــك ألننــي اردت اســكان العوائــل فيهــا وعرضتهــا لذلــك‬\n‫ولكنهــا لــم تســكن مــن العوائــل وهــؤالء العمــال بقــي لهــم فتــرة ســتة‬\n‫اشــهر الــى انتهــاء عقدهــم وال يوجــد ضــرر علــى املجاوريــن منهــم ويوجــد‬\n‫عمــارة عــزاب مالصقــة لعمارتــي مــن جهــة الشــمال هــذه اجابتــي بعــد‬\n‫ذلــك قــررت اخلــروج علــى موقــع النــزاع ويف هــذا اليــوم األثنــن املوافــق‬\n‫‪1434/4/22‬ه ـ جــرى خروجــي انــا القاضــي بهــذه احملكمــة برفقــة‬\n‫مديــر ادارة احملكمــة ‪ .....‬واملوظــف بــاإلدارة ‪ .....‬علــى موقــع النــزاع‬\n‫اخلــاص بدعــوى ‪ .....‬و ‪ .....‬ضــد ‪ .....‬حــي ‪ .....‬وبعــد مشــاهدة املوقــع اتضــح‬\n‫بحضــور األطــراف جميعــا وجــود عمــارة املدعــى عليــه وفيهــا مجموعــة‬\n‫مــن العمــال العــزاب مــن املصريــن والباكســتانيني حســب كالم‬\n‫املدعــى عليــه ولهــا ثالثــة ابــواب مــن جهــة اجلنــوب ويقابلهــا مباشــرة منــزل‬\n‫‪ .....‬وقــد ســألت املدعــى عليــه فقــال ان العمــال يدخلــون ويخرجــون مــن‬\n‫هــذه األبــواب باإلضافــة الــى النوافــذ املطلــة مــن جهــة اجلنــوب وهــي‬\n‫مغلقــة واملدعــي ‪ .....‬يحــد املدعــى عليــه مبنزلــه مــن جهــة الشــرق وقــد‬\n‫كان الشــارع خاليــا مــن العمالــة حــن الوقــوف الســاعة احلاديــة عشــر‬\n‫والنصــف ضحــى وقــد ذكــر املدعــى عليــه أنهــم يحضــرون الظهــر‬\n‫ويوجــد بيــوت حتــد ‪ .....‬مــن جهــة الشــرق كلهــا بيــوت عوائــل ل‪ .....‬و يليــه‬\n‫‪ .....‬ثــم ‪ .....‬وال يوجــد ســوى هــذه العمــارة داخــل احلــي بأبوابهــا املطلــة‬\n‫علــى املجاوريــن هــذا مــا جــرى االطــاع عليــه ولــذا أعــد هــذا احملضــر‬\n‫وعليــه حصــل التوقيــع فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى اقــرار املدعــى عليــه بكــون هــذه العمــارة لــه وأنــه اســكن فيهــا‬\n\n\n                                                                                        ‫‪360‬‬\n\f      ‫عمــال عــزاب وبنــاء علــى احملضــر املعــد مــن قبلنــا وبنــاء علــى حصــول‬\n      ‫الضــرر املتحقــق مــن هــذه العمــارة علــى ســكان احلــي مــن العوائــل وهــم‬\n      ‫عمــال مــن جنســيات مختلفــة ولهــذه العمــارة عــدة ابــواب مــن جهــة احلــي‬\n      ‫وســاكنيه وبنــاء علــى مــا نصــت عليــه االنظمــة والتعليمــات بخصــوص‬\n      ‫منــع العــزاب مــن الســكن داخــل األحيــاء التــي يقطنهــا عوائــل وبنــاء‬\n      ‫علــى مــا نــص عليــه اهــل العلــم مــن عــدم اســكان العــزاب عنــد العوائــل‬\n      ‫واخراجهــم بنــاء علــى ذلــك كلــه فقــد حكمــت علــى املدعــى عليــه‬\n      ‫بأخــاء هــذه العمــارة مــن العمــال العــزاب فــور ًا وعــدم اســكان امثالهــم‬\n      ‫مســتقال وبعــرض ذلــك علــى املدعــى عليــه قــرر عــدم قناعتــه وطلــب‬\n      ‫االســتئناف فأجبتــه لطلبــة وأفهمتــه باملراجعــة يــوم الثالثــاء املوافــق‬\n      ‫‪1434/04/23‬ه ـ الســتالم نســخة مــن صــك احلكــم لالعتــراض عليــه‬\n      ‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم حــرر يف ‪1434/04/22‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34316096‬وتاريــخ‬\n                                                        ‫‪ 1434/9/9‬هـ‬\n\n\n\n\n‫‪361‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":358,"source_page_end":361,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"92495015a94244b2f0c431c3aca671b9c2b4c5e1652fbea0077bf0d43c988699","normalized_text_hash":"002d4581180705091b4cacece14c5f0b70ccc103cfb35f186a55463525b32768","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p358-33675732"},{"id":"75ddbac8-19cd-5e28-a91d-082b62aff461","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -تضرر املدعي من إيقاف املدعى عليه لسياراته أمام منزله وورشته -إقرار املدعى عليه -إيجابية تقرير اخلبراء للمدعي -ثبوت الدعوى -احلكم مبنع املدعى عليه من إيقاف سياراته مبحاذاة منزل املدعي .","document_number":"34304332","case_number":"3427193","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"دعوى منع ضرر -تضرر املدعي من إيقاف املدعى عليه لسياراته أمام منزله وورشته -إقرار املدعى عليه -إيجابية تقرير اخلبراء للمدعي -ثبوت الدعوى -احلكم مبنع املدعى عليه من إيقاف سياراته مبحاذاة منزل املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/23 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34304332 :‬‬\n                    ‫َر ْق ُم الدعوى‪3427193 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34328819‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n‫دعــوى منــع ضــرر ‪ -‬تضــرر املدعــي مــن إيقــاف املدعــى عليــه لســياراته‬\n‫أمــام منزلــه وورشــته ‪ -‬إقــرار املدعــى عليــه ‪ -‬إيجابيــة تقريــر اخلبــراء‬\n‫للمدعــي ‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم مبنــع املدعــى عليــه مــن إيقــاف‬\n                                        ‫ســياراته مبحــاذاة منــزل املدعــي ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار)‪.‬‬\n                                   ‫‪ -2‬القاعدة الشرعية‪« :‬الضرر يزال»‪.‬‬\n\n\n\n‫ادعــى املدعــي بأنــه ميتلــك منــز ًال وورشــة ومغســلة ســيارات مالصقــن لــه‬\n‫وأن املدعــى عليــه لــه منــزل مجــاور ملنزلــه وقــد تضــرر مــن إيقــاف املدعــى‬\n‫عليــه لســياراته مبحــاذاة منزلــه باألضــرار املذكــورة يف دعــواه‪ ،‬ولــذا‬\n‫طلــب إلزامــه بعــدم إيقــاف ســياراته مبحــاذاة منزلــه‪ -‬أقــر املدعــى عليــه‬\n‫مبــا جــاء يف الدعــوى ودفــع بأنــه محتــاج إليقافهــا يف ذلــك املــكان وال‬\n‫يوجــد ضــرر علــى املدعــي مــن ذلــك‪ -‬قــررت احملكمــة تكليــف قســم‬\n‫اخلبــراء مبعاينــة محــل النــزاع فأفــادوا بــأن العــرف إيقــاف الســيارات‬\n‫محاذيــة للمنــزل دون جتــاوز حلــدوده بالوقــوف‪ -‬مــن املقــرر شــرع ًا أنــه‬\n‫ال ضــرر وال ضــرار وأن الضــرر يــزال‪ -‬قضــت احملكمــة مبنــع املدعــى‬\n\n                                                                                      ‫‪362‬‬\n\f      ‫عليــه مــن إيقــاف ســياراته مبحــاذاة منــزل املدعــي‪ -‬قنــع املدعــي باحلكــم‬\n      ‫وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                    ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل برقــم ‪ 3427193‬وتاريــخ ‪1434/01/17‬ه ـ املقيــدة‬          ‫ّ‬\n      ‫باحملكمــة برقــم ‪ 34129255‬وتاريــخ ‪ 1434/01/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1434/08/23‬ه ـ افتتحــت اجللســة الســاعة ‪01 :30‬‬\n      ‫وفيهــا حضــر املدعــي ‪ ..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬وحضــر حلضــوره املدعــى عليــه ‪ .......... /‬ســعودي اجلنســية‬\n      ‫ا إننــي أمتلــك‬‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬ثــم ادعــى املدعــي قائـ ً‬\n      ‫ورشــة ومغســلة ســيارات ومنــزل مالصــق لهــا بحــي العزيزيــة والورشــة‬\n      ‫تفتــح علــى شــارع غربــي ويحدهــا مــن الشــمال شــارع واملدعــى عليــه لــه‬\n      ‫منــزل يفتــح علــى الشــارع املذكــور وهــو الفاصــل بينــي وبينــه ويفتــح‬\n      ‫أيضـ ًا علــى شــارع غربــي وحيــث أن بــاب منزلــي يفتــح علــى هــذا الشــارع‬\n      ‫وتوجــد بيــارة املغســلة وطبلــون الكهربــاء علــى هــذا الشــارع فقــد‬\n      ‫تضــررت مــن إيقــاف املدعــى عليــه لســياراته مبحــاذاة ورشــتي واملنــزل‬\n      ‫ممــا يعيقنــي مــن ســحب البيــارة التــي تلزمنــي البلديــة بســحبها باســتمرار‬\n      ‫وقــد تقــدم املدعــى عليــه بشــكوى ضــدي للشــرطة والبلديــة يطالبنــي‬\n      ‫بهــا بســحب البيــارة وعنــد حضــور الوايــت لــم يتمكــن مــن ســحبها‬\n\n\n‫‪363‬‬\n\f‫لوقــوف ســيارته فــوق البيــارة وتضــررت أيض ـ ًا مــن عــدم وصــول فواتيــر‬\n‫الكهربــاء للعــداد لعــدم متكــن موظــف الكهربــاء مــن وضعهــا فيــه‬\n‫وتضــررت أيضـ ًا مــن إغالقــه لبــاب املنــزل بســياراته أطلــب إلزامــه بعــدم‬\n‫إيقــاف ســياراته مبحــاذاة ورشــتي ومنزلــي هــذه دعــواي وبســؤال املدعــى‬\n‫ا مــا ذكــره املدعــي مــن مــكان الورشــة واملنــزل وبابــه‬    ‫عليــه أجــاب قائـ ً‬\n‫املذكــور ومــكان البيــارة والطبلــون وأننــي قد اشــتكيته لدى الشــرطة‬\n‫وطلبــت منــه ســحب البيــارة وأن ســيارتي كانــت واقفــة علــى البيــارة‬\n‫حــن حضــور الشــرطة فهــذا كلــه صحيــح وال ضــرر عليــه مــن إيقــاف‬\n‫ســياراتي يف هــذا املــكان حيــث أن الشــارع الغربــي ملنزلــي توجــد فيــه‬\n‫ســياراتي األخــرى والشــارع ملــك للدولــة وأنــا محتــاج لوقــوف ســياراتي‬\n‫يف هــذا املــكان بهــذا أجــاب فبعــد الدعــوى واإلجابــة واالطــاع علــى‬\n‫أوراق املعاملــة ومنهــا قــرار هيئــة اخلبــراء باحملكمــة العامــة بحائــل رقــم‬\n‫(‪ )33194188‬وتاريــخ ‪1434/05/14‬ه ـ املتضمــن [نفيدكــم أنــه مت‬\n‫وقوفنــا نحــن عضــوي هيئــة اخلبــراء كل مــن ‪ .....‬و‪ .....‬ومعاينــة املوقــع‬\n‫علــى الطبيعــة وحاولنــا اإلصــاح بينهمــا ولــم يتيســر ذلــك وشــاهدنا‬\n‫ســيارات املدعــى عليــه مالصقــة لبنشــر املدعــي مــن اجلهــة الشــمالية‬\n‫والتــي بهــا بيــارة وطبلــون كهربــاء املدعــي والــذي نــرى أن يجعــل وقــوف‬\n‫ســياراته (نعنــي املدعــى عليــه) أن تكــون محاذيــة لبيتــه وال يتجــاوز‬\n‫بالوقــوف حــدود منزلــه حســب العــرف هــذا مــا نــراه واهلل املوفــق] ولقولــه‬\n‫صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) وملــا قــرره أهــل العلــم مــن أن‬\n‫الضــرر يــزال لذلــك كلــه فقــد حكمــت مبنــع املدعــى عليــه مــن إيقــاف‬\n‫ســياراته مبحــاذاة ورشــة ومغســلة ومنــزل املدعــي هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت واهلل أعلــم وأحكــم وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n\n\n                                                                                        ‫‪364‬‬\n\f      ‫االعتــراض وأنــه ســيتقدم بالئحــة اعتراضيــة فجــرى تســليمه صــورة مــن‬\n      ‫صــك احلكــم لتقــدمي اعتراضــه خــال ثالثــن يومـ ًا مــن هــذا اليــوم وإذا‬\n      ‫لــم يقــدم اعتراضــه خــال هــذه املهلــة فــإن حقــه يف االعتــراض يســقط‬\n      ‫ويكتســب احلكــم القطعيــة دون رفعــه حملكمــة االســتئناف ومت قفــل‬\n      ‫اجللســة الســاعة (‪ )02.00‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/8/23‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34328819‬وتاريــخ‬\n                                                   ‫‪ 1434/10/12‬هـ‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":362,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0b252f52b604109215c1ae58e6e70a504579e00449834d48115863d9891f55f","normalized_text_hash":"63959757d4c03223eaa87490a55aec47942a7b69fc3797a8043d81a5503e65c7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p362-34304332"},{"id":"68720165-b687-57c8-998b-b31001733aae","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -مطالبة املدعى عليه عدم تأجير العقار على عزاب للضرر -مصادقة املدعى عليه على الدعوى عدا الضرر -املدعى عليه وسيط بن املدعي (املؤجر) واملستأجرين -دعوى ضرر من املنتفع من العقار تسمع يف مواجهة املستأجر -حكم بصرف النظر لعدم االختصاص النوعي -إفهام بإقامة الدعوى على املستأجر - احلكم بصرف النظر لعدم االختصاص النوعي .","document_number":"34346127","case_number":"34463063","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة بقعاء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/2","year":"1434","subject":"دعوى منع ضرر -مطالبة املدعى عليه عدم تأجير العقار على عزاب للضرر -مصادقة املدعى عليه على الدعوى عدا الضرر -املدعى عليه وسيط بن املدعي (املؤجر) واملستأجرين -دعوى ضرر من املنتفع من العقار تسمع يف مواجهة املستأجر -حكم بصرف النظر لعدم االختصاص النوعي -إفهام بإقامة الدعوى على املستأجر - احلكم بصرف النظر لعدم االختصاص النوعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/2 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34346127 :‬‬\n                    ‫َر ْق ُم الدعوى‪34463063 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34356295‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n ‫دعــوى منــع ضــرر‪ -‬مطالبــة املدعــى عليــه عــدم تأجيــر العقــار على عزاب‬\n ‫للضــرر‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى عــدا الضــرر‪ -‬املدعــى‬\n ‫عليــه وســيط بــن املدعــي (املؤجــر) واملســتأجرين‪ -‬دعــوى ضــرر مــن‬\n ‫املنتفــع مــن العقــار تســمع يف مواجهــة املســتأجر ‪ -‬حكــم بصــرف النظــر‬\n ‫لعــدم االختصــاص النوعــي‪ -‬إفهــام بإقامــة الدعــوى علــى املســتأجر ‪-‬‬\n                    ‫احلكــم بصــرف النظــر لعــدم االختصــاص النوعــي ‪.‬‬\n\n\n\n\n ‫املــادة ‪ 13/31‬مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة والتــي‬\n ‫تنــص علــى أن دعــاوى الضــرر مــن املنتفعــن بالعقار ســواء كانــوا عزاب ًا‬\n ‫أو غيرهــم مــن اختصــاص احملاكــم اجلزائيــة وتســمع يف مواجهــة‬\n ‫ال علــى وحــدات ســكنية مؤجــرة‬    ‫املســتأجر إال إذا كان العقــار مشــتم ً‬\n ‫علــى عــزاب وتكــون الدعــوى علــى املالــك ملنعــه مــن تأجيــر العــزاب اهــ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه أن املدعــى عليــه قــام بتأجيــر الفيــا‬\n ‫الواقعــة يف حــي ‪ ....‬ملــدة ســنة علــى مجموعــة مــن العــزاب وهــي تقــع جــوار‬\n ‫فلــة املدعــي وملــا فيــه مــن الضــرر مــن وجودهــم ومضايقتهــم فقــد طلــب‬\n ‫املدعــي إلــزام املدعــى عليــه بعــدم تأجيــر هــذه الفيــا للمســتأجرين وقرر‬\n\n                                                                                       ‫‪366‬‬\n\f      ‫أن الفيــا ليســت وحــدات ســكنية ‪ -‬أجــاب املدعــى عليــه باملصادقــة‬\n      ‫علــى الدعــوى مــا عــدا الضــرر فذكــر عــدم علمــه بــه وانــه بإمــكان‬\n      ‫املدعــي إقامــة الدعــوى علــى املســتأجرين وقــرر أنــه ال ميلــك الفيــا‬\n      ‫املؤجــرة وإمنــا كان وســيط ًا يف تأجيرهــا ‪ -‬قــرر ناظــر القضيــة وبنــاء‬\n      ‫علــى املــادة ‪ 13/31‬مــن نظــام املرافعــات الشــرعية والتــي تنــص علــى أن‬\n      ‫دعــاوى الضــرر مــن املنتفعــن مــن العقــار تســمع يف مواجهــة املســتأجر‬\n      ‫إال إذا كان العقــار يحــوي علــى وحــدات ســكنية فتســمع يف مواجهــة‬\n      ‫املالــك ملنعــه مــن تأجيــر العــزاب لذلــك فقــد صــدر احلكم بصــرف النظر‬\n      ‫عــن الدعــوى ضــد املدعــى عليــه وافهمــه بــان لــه احلــق يف إقامــة الدعــوى‬\n      ‫ضــد املســتأجرين وقــرر ناظــر القضيــة انــه لــم يتــم طلــب أصــل التملــك‬\n      ‫وال االستفســار عــن ســجل الصــك ألن الدعــوى ليســت يف منازعــة يف‬\n      ‫متلــك يف عقــار وإمنــا يف عقــد إجــارة تصــادق طــريف القضيــة عليــه ‪ -‬صــدر‬\n      ‫قــرار محكمــة االســتئناف يف منطقــة حائــل باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف‬\n      ‫يــوم األحــد املوافــق ‪1434/11/2‬ه ـ لــدي أنــا رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة التاســعة صباحــا للنظــر‬\n      ‫يف الدعــوى املقدمــة مــن ضــد مكتــب ‪........‬العقــاري واملقيــدة بهــذه‬\n      ‫احملكمــة برقــم ‪ 342366602‬يف ‪1434/10/20‬ه ـ واحملالــة لــي برقــم‬\n      ‫‪ 34463063‬يف ‪1434/10/20‬ه ـ وقــد حضــر يف هــذه اجللســة ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى احلاضــر يف هــذه‬\n      ‫اجللســة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائــا يف حتريــر‬\n‫‪367‬‬\n\f‫دعــواه لقــد قــام املدعــى عليــه بتأجيــر الفلــة الواقعــة يف حــي ‪........‬يف‬\n‫بقعــاء مبوجــب عقــد اإليجــار رقــم ‪........‬يف ‪1434/10/18‬ه ـ ملــدة ســنة‬\n‫واحــدة علــى مجموعــة مــن العمالــة الغيــر ســعوديني وهــم عــزاب وألن‬\n‫هــذه الفلــة تقــع بجــوار فلتــي وملــا فيــه مــن الضــرر مــن وجودهــم بهــذه‬\n‫الفلــة ومضايقتهــم لــي أطلــب إلــزام املدعــى عليــه بعــدم تأجيــره هــذه‬\n‫الفلــة للمســتأجرين املذكوريــن هــذه دعــواي ثــم ســألت املدعــي هــل‬\n‫هــذه الفلــة تشــتمل علــى عــدة وحــدات ســكنية أم أنــه مت تأجيــر هــذه‬\n‫الفلــة مــن قبــل املدعــى عليــه علــى العمالــة املذكوريــن كاملــة فقــال إن‬\n‫املدعــى عليــه قــد قــام بتأجيرهــا كاملــة علــى العمالــة املذكوريــن وهــي‬\n‫ليســت وحــدات ســكنية هكــذا قــرر وبســؤال املدعــى عليــه عــن دعــوى‬\n‫ا مــا ذكــره املدعــي كلــه صحيــح مــا عــدا وجــود‬      ‫املدعــي أجــاب قائ ـ ً‬\n‫الضــرر مــن العمالــة املذكوريــن فهــذا ال أعلــم عنــه وبإمــكان املدعــي‬\n‫رفــع دعــواه ضــد املســتأجرين وأنــا ال أملــك هــذه الفلــة وال أســكنها وإمنــا‬\n‫أنــا كنــت وســيط يف اســتئجار العمالــة هذه الفلــة ألنني صاحب مكتب‬\n‫‪........‬العقــاري هكــذا أجــاب فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n‫وألن املدعــي قــرر أن هــذه الفلــة قــام املدعــى عليــه بتأجيرهــا كاملــة‬\n‫علــى العمالــة املذكوريــن وأنهــا ليســت وحــدات ســكنية ونظــر ًا ملــا جــاء‬\n‫يف املــادة (‪ )13/31‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‬\n‫والتــي تنــص علــى أن دعــاوى الضــرر مــن املنتفعــن بالعقار ســواء أكانوا‬\n‫عزابـ ًا أم غيرهــم مــن اختصــاص احملاكــم اجلزئيــة وتســمع يف مواجهــة‬\n‫املســتأجر إال إذا كان العقــار مشــتمال علــى عــدة وحــدات ســكنية‬\n‫مؤجــرة علــى عــزاب فتكــون الدعــوى علــى املالــك ملنعــه مــن تأجيــر‬\n‫العــزاب اهــ‪ .‬لذلــك كلــه فقــد رددت هــذه الدعــوى وأفهمــت املدعــي بــأن‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫عليــه تقــدمي دعــوى ضــد املســتأجرين وبذلــك حكمــت ولــم يتــم طلــب‬\n      ‫أصــل صــك التملــك وال االستفســار عــن ســريان مفعولــه ألن الدعــوى‬\n      ‫ليســت منازعــة يف متلــك هــذا العقــار وإمنــا يف تأجيــر تصــادق املدعيــن‬\n      ‫عليــه وبعــرض احلكــم علــى املدعــي قــرر عــدم القناعــة بــه وطلــب رفــع‬\n      ‫احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة وعليــه جــرى‬\n      ‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1434/11/2‬ه ـ‬\n      ‫احلمــد هلل وحده ـ والصــاة والســام علــى مــن ال نبــي بعــده فلــدي أنــا‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف يــوم‬\n      ‫األحــد املوافــق ‪1434/11/23‬ه ـ الســاعة الواحــدة ظهــرا بنــاء علــى‬\n      ‫ورود املعاملــة مــن محكمــة االســتئناف بحائــل برقــم ‪342366602‬‬\n      ‫يف ‪1434/11/11‬ه ـ ومرفقــا بهــا قــرار الدائــرة حلقوقيــة األولــى رقــم‬\n      ‫‪ 34356295‬يف ‪1434/11/10‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫مــا حكــم بــه فضيلتــه وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/11/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــه‬\n      ‫بقعــاء برقــم ‪ 342366602‬وتاريــخ ‪1434/11/2‬ه ـ واملقيــدة لدينا بتاريخ‬\n      ‫‪1434/11/6‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34346127‬يف ‪1434/11/2‬هـ‬\n      ‫الصــادر مــن فضيلــة القاضــي‪ ...... /‬اخلــاص بدعــوى ضــد بشــأن دعــوى‬\n      ‫إخــاء عقــار علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك‬\n\n\n‫‪369‬‬\n\f‫حكــم فضيلتــه كمــا هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه‬\n                         ‫واهلل املوفــق وصلــى وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                               ‫‪370‬‬\n\f371\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫املطالبة بنفقة الطفل من والدته وصرف النظر‬\n  ‫‪5‬‬                                                          ‫نفقة‬    ‫‪1‬‬\n         ‫عن ذلك كون األم لم تنو الرجوع بالنفقة عليه‬\n\n\n         ‫اشتراط نية الرجوع ملن قام بالنفقة الواجبة على‬\n  ‫‪11‬‬      ‫غيره واشتراط الوكالة للمطالبة عن األبناء‬           ‫نفقة‬    ‫‪2‬‬\n                            ‫البالغني‬\n\n\n         ‫مطالبة زوجة ناشز بالنفقة املاضية واملستقبلية‬\n  ‫‪20‬‬       ‫لها وألبنائها وتقدير النفقة من قسم اخلبراء‬        ‫نفقة‬    ‫‪3‬‬\n         ‫وحلفها اليمني بنية الرجوع على الزوج بالنفقة‬\n\n\n         ‫مطالبة الزوجة بنفقة ملدة محددة مع نفقة البنت‬\n  ‫‪30‬‬                                                         ‫نفقة‬    ‫‪4‬‬\n                      ‫املاضية واملستقبلية‬\n\n\n          ‫صرف النظر عن طلب الزوجة نفقتها املاضية‬\n         ‫كونها ناشز ًا وتقدير النفقة املاضية واملستقبلية‬\n  ‫‪38‬‬          ‫للبنت عن طريق قسم اخلبراء واحلكم‬               ‫نفقة‬    ‫‪5‬‬\n           ‫باستخراج تبليغ والدة وشهادة ميالد وإضافة‬\n                      ‫املولودة يف دفتر العائلة‬\n\n\n           ‫املطالبة بالنفقة املاضية واملستقبلية لألوالد‬\n          ‫وتسليم األم األوراق الثبوتية ألوالدها الذين يف‬\n  ‫‪45‬‬     ‫حضانتها واحلكم بالنفقة وإخراج شهادة امليالد‬         ‫نفقة‬    ‫‪6‬‬\n          ‫وإسقاط املدعية من سجل أسرة املدعى عليها‬\n                         ‫بالتنفيذ املعجل‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n           ‫مطالبة الزوجة بالنفقة املاضية واملستقبلية‬\n         ‫وعدم استحقاقها لنشوزها وعدم التمكني من‬\n  ‫‪58‬‬                                                        ‫نفقة‬    ‫‪7‬‬\n         ‫االستمتاع واحلكم بنفقة الولد وحتديدها عن‬\n                         ‫طريق اخلبراء‬\n\n\n           ‫احلكم بتسليم النفقة املاضية واملستقبلية‬\n  ‫‪66‬‬                                                        ‫نفقة‬    ‫‪8‬‬\n                         ‫للزوجة وابنها‬\n\n\n         ‫فسخ نكاح الزوجة لتضررها من غياب الزوج‬\n          ‫وعدم نفقته واألخذ بشهادة الشهود وإعالم‬\n  ‫‪71‬‬                                                        ‫نفقة‬    ‫‪9‬‬\n          ‫الزوج عن طريق اإلعالن يف اجلريدة واجلهات‬\n                           ‫الرسمية‬\n\n\n             ‫مطالبة الزوجة بنفقتها املاضية واملستقبلية‬\n  ‫‪78‬‬     ‫ونفقة العدة وعدم سقوط حقها وعدها ناشز ًا‬           ‫نفقة‬    ‫‪10‬‬\n                 ‫حيث لم يوفر الزوج البيت الشرعي‬\n\n\n         ‫احلكم على األب بدفع نفقة األوالد املستقبلية‬\n  ‫‪88‬‬       ‫وتسليم النفقة للحاضنة ‪ ،‬وعدم استحقاق‬             ‫نفقة‬    ‫‪11‬‬\n             ‫الزوج للنفقة المتناعها عن حلف اليمني‬\n\n\n           ‫احلكم بنفقة االبن املستقبلية وعدم األخذ‬\n ‫‪102‬‬                                                        ‫نفقة‬    ‫‪12‬‬\n                    ‫بتقدير قسم اخلبراء‬\n\n\n         ‫املطالبة بنفقة األوالد املاضية وميني االستظهار‬\n ‫‪107‬‬     ‫يف النفقة عن نية الرجوع واألخذ بقول األوالد‬        ‫نفقة‬    ‫‪13‬‬\n          ‫فيمن أنفق عليهم حال اخلالف بني الزوجني‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫احلكم بنفقة ماضية ومستقبلية لألوالد وتقدير‬\n ‫‪118‬‬     ‫النفقة عن طريق قسم اخلبراء واحلكم للمطلقة‬          ‫نفقة‬    ‫‪14‬‬\n                          ‫بنفقة عدتها‬\n\n\n           ‫احلكم على املدعى عليها بدفع نفقة احلمل‬\n ‫‪123‬‬     ‫والنفقة الشهرية املاضية واملستقبلية والكسوة‬        ‫نفقة‬    ‫‪15‬‬\n                          ‫املستقبلية‬\n\n\n         ‫احلكم بإلزام الزوج بنفقة االبن املاضية إلقراره‬\n ‫‪131‬‬      ‫بعدم النفقة وتقدير النفقة املاضية عن طريق‬         ‫نفقة‬    ‫‪16‬‬\n                          ‫قسم اخلبراء‬\n\n\n         ‫مطالبة الزوجة بنفقتها املاضية وشروع اليمني‬\n ‫‪137‬‬                                                        ‫نفقة‬    ‫‪17‬‬\n                  ‫يف جانب أقوى املتداعيني‬\n\n\n          ‫طلب زيادة النفقة لكبر األوالد وزيادة راتب‬\n ‫‪145‬‬     ‫األب وطلب تسديد رسوم الدراسة وتوفير سائق‬           ‫نفقة‬    ‫‪18‬‬\n                        ‫وسيارة لألوالد‬\n\n\n            ‫احلكم بالنفقة املاضية واملستقبلية لالبن‬\n ‫‪155‬‬        ‫واألخذ بيمني األم على ماأنفقته أنه بنية‬         ‫نفقة‬    ‫‪19‬‬\n                        ‫الرجوع على األب‬\n\n\n          ‫احلكم بنفقة الزوجة املاضية ونفقة األوالد‬\n ‫‪160‬‬      ‫املاضية واملستقبلية وتقدير النفقة عن طريق‬         ‫نفقة‬    ‫‪20‬‬\n                          ‫قسم اخلبراء‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة الزوجة بالنفقة املاضية وقيمة الذهب‬\n ‫‪170‬‬       ‫وفاتورة الهاتف الثابت ودفع الزوج بنشوز‬          ‫نفقة‬    ‫‪21‬‬\n                          ‫الزوجة‬\n\n\n         ‫احلكم بنفقة الزوجة واألوالد القصر والبالغني‪،‬‬\n ‫‪175‬‬      ‫عد الزوجة ناشز ًا بعد قذف زوجها لها‬\n                                            ‫وعدم ٌ‬         ‫نفقة‬    ‫‪22‬‬\n                      ‫وخروجها من بيتها‬\n\n\n         ‫مطالبة أم بنفقة ابنتها وتقدير النفقة عن طريق‬\n ‫‪181‬‬                                                       ‫نفقة‬    ‫‪23‬‬\n                        ‫قسم اخلبراء‬\n\n\n          ‫مطالبة والد بنفقته من ابنته وهي يف ذمة زوج‬\n ‫‪186‬‬                                                       ‫نفقة‬    ‫‪24‬‬\n                   ‫وصرف النظر عن الدعوى‬\n\n\n          ‫إلزام األب بنفقة ولديه مع أجرة سكنهما‪،‬‬\n ‫‪190‬‬      ‫وتسليمهما للمدعية‪ ،‬عند إخالء شقة املدعى‬          ‫نفقة‬    ‫‪25‬‬\n                            ‫عليه‬\n\n\n ‫‪197‬‬        ‫إلزام األب بنفقة ابنته املاضية واملستقبلية‬     ‫نفقة‬    ‫‪26‬‬\n\n\n         ‫احلكم بنفقة شهرين لألوالد قبل تقديرها من‬\n ‫‪204‬‬                                                       ‫نفقة‬    ‫‪27‬‬\n             ‫قسم اخلبراء وشموله بالنفاذ املعجل‬\n\n\n          ‫مطالبة طليق مسجون بنفقة أوالدها السابقة‬\n ‫‪208‬‬                                                       ‫نفقة‬    ‫‪28‬‬\n            ‫واملستقبلية وبقية عملية الوالدة ونفقة لها‬\n\n\n         ‫صرف النظر عن مطالبة أم لنفقة ابنتها املاضية‬\n ‫‪212‬‬                                                       ‫نفقة‬    ‫‪29‬‬\n             ‫ألنها لم تنو الرجوع على األب بالنفقة‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫احلكم مبا اصطلح عليه الطرفان يف نفقة العدة‬\n ‫‪219‬‬      ‫واحلكم على األب بنفقة ابنته وتضمني احلكم‬          ‫نفقة‬    ‫‪30‬‬\n                         ‫بالنفاد املعجل‬\n\n\n         ‫للمرأة نظاما إقامة دعواها يف املسائل الزوجية‬\n ‫‪224‬‬       ‫مبقر إقامتها وامتناع الزوج عن احلضور يعد‬         ‫نفقة‬    ‫‪31‬‬\n                            ‫نكو ًال‬\n\n\n           ‫احلكم على األوالد بدفع نفقة شهرية لألم‬\n ‫‪230‬‬     ‫وأجرة املواصالت وخدمة والدهم بأنفسهم فإن‬           ‫نفقة‬    ‫‪32‬‬\n            ‫تعذر فعليهم أن يوفروا من يقوم بخدمتها‬\n\n\n         ‫احلكم بالنفقة املاضية واملستقبلية لالبن البالغ‬\n ‫‪237‬‬                                                        ‫نفقة‬    ‫‪33‬‬\n                    ‫وتقديرها من قسم اخلبراء‬\n\n\n          ‫إلزام املدعى عليه بدفع نفقة الطفل املاضية‬\n ‫‪245‬‬     ‫واملستقبلية ونفقة احلمل ‪ ،‬نفقة احلمل ال تسقط‬       ‫نفقة‬    ‫‪34‬‬\n                          ‫بالنشوز‬\n\n\n          ‫احلكم على األب بدفع نفقة األبناء املستقبلية‬\n ‫‪252‬‬                                                        ‫نفقة‬    ‫‪35‬‬\n                        ‫حيث تقدير اخلبراء‬\n\n\n          ‫احلكم على املدعى عليه بتسليم نفقة ماضية‬\n ‫‪259‬‬       ‫للزوجة ونفقة ماضية ومستقبلية لالبن ورد‬           ‫نفقة‬    ‫‪36‬‬\n             ‫دعوى املدعية مبطالبتها مبتعة الطالق‬\n\n\n          ‫احلكم على املدعى عليه بدفع النفقة املاضية‬\n ‫‪264‬‬     ‫واملستقبلية ودخول نفقة احلمل يف تقدير النفقة‬       ‫نفقة‬    ‫‪37‬‬\n                            ‫املاضية‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬       ‫م‬\n\n\n           ‫إلزام األوالد بالنفقة على والدتهم وإحضار‬\n ‫‪272‬‬      ‫سائق وخادمة وتقدير النفقة عن طريق قسم‬              ‫نفقة‬       ‫‪38‬‬\n                          ‫اخلبراء‬\n\n\n          ‫احلكم على الزوج بدفع نفقة الزوجة املاضية‬\n ‫‪280‬‬                                                         ‫نفقة‬       ‫‪39‬‬\n             ‫وتقدير النفقة عن طريق قسم اخلبراء‬\n\n\n         ‫إلزام املدعى عليه بدفع نفقة فترة احلمل ونفقة‬\n ‫‪287‬‬                                                         ‫نفقة‬       ‫‪40‬‬\n         ‫الطفل املاضية وحتديد نفقة مستقبلية للطفل‬\n\n\n         ‫املطالبة مبصاريف الدراسة والعالج ودفع فرق‬\n         ‫النفقة بني ما دفعه وبني ما مت تقديره من قسم‬\n ‫‪293‬‬                                                         ‫نفقة‬       ‫‪41‬‬\n          ‫اخلبراء‪ ،‬واحلكم بدفع فرق النفقة املاضية‬\n                    ‫ودفع النفقة املستقبلية‬\n\n\n            ‫احلكم بدفع نفقة احلمل والنفقة املاضية‬\n ‫‪299‬‬                                                         ‫نفقة‬       ‫‪42‬‬\n                            ‫للمولود‬\n\n\n            ‫املطالبة بقيمة إيجار السكن ومصاريف‬\n ‫‪312‬‬        ‫الدراسة وإعالة وتقديرها عن طريق قسم‬              ‫نفقة‬       ‫‪43‬‬\n          ‫اخلبراء والصلح بني الطرفني على مبالغ معينة‬\n\n\n          ‫مطالبة األم بنفقة أوالدها املاضية واملستقبلية‬\n ‫‪320‬‬        ‫واحلكم بالنفقة املستقبلية مشمول بالنفاذ‬          ‫نفقة‬       ‫‪44‬‬\n                             ‫املعجل‬\n\n\n         ‫مطالبة زوج والد زوجته بكف تدخله بينه وبني‬\n                                                          ‫كف تدخل‬\n ‫‪329‬‬     ‫زوجته وإلزام والد الزوجة (املدعى عليه) بكف‬                     ‫‪45‬‬\n                                                          ‫والد الزوجة‬\n                      ‫يده عن زوجة املدعي‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬       ‫م‬\n\n\n         ‫إلزام املدعى عليه برد اخلادمة‪ ،‬حيث إن تخلفه‬\n                                                          ‫طلب‬\n ‫‪337‬‬     ‫عن احلضور يعد نكو ًال ورد اليمني إلى املدعي‬                 ‫‪46‬‬\n                                                       ‫إعادة خادمة‬\n                        ‫بصحة دعواه‬\n\n\n         ‫إلزام املدعى عليه بإزالة حظيرة أغنامه لتضرر‬      ‫دعوى‬\n ‫‪345‬‬                                                                 ‫‪47‬‬\n                       ‫املدعية من ذلك‬                   ‫منع ضرر‬\n\n\n         ‫احلكم مبنع سكن العزاب يف خاص بالعوائل‬           ‫دعوى‬\n ‫‪353‬‬                                                                 ‫‪48‬‬\n           ‫ووقوف القاضي على محل النزاع ومعاينته‬         ‫منع ضرر‬\n\n\n           ‫احلكم على املدعى عليها باملنع من إيقاف‬        ‫دعوى‬\n ‫‪358‬‬                                                                 ‫‪49‬‬\n                ‫سيارته مبحاذاة منزل املدعي‬              ‫منع ضرر‬\n\n\n         ‫احلكم بصرف النظر عن دعوى املدعي لعدم‬\n                                                         ‫دعوى‬\n ‫‪362‬‬      ‫االختصاص النوعي ‪ ،‬وإفهام املدعي بإقامة‬                     ‫‪50‬‬\n                                                        ‫منع ضرر‬\n                   ‫الدعوى على املستأجر‬\n\n\n ‫‪366‬‬                                                                 ‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":366,"source_page_end":378,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"69a2ef9267232818d1086aa2b9508a37e65dcd3617e59d13a5277aa6a17167fe","normalized_text_hash":"f9bb67b2ebdefbcd82f9280a05fe883b28583d1330e1c80ec7c97f448fb7ce6f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p366-34346127"},{"id":"c0a09f50-c8ca-5654-8f78-faee20f30d09","document_type":"judgment","category":"judicial","subcategory":"general","title":"وإقامة حد الغيلة عليه -حيث تلقت الشرطة بالغا عن قيام املدعى عليه بطعن أحد الساكنني معه يف سكن العمال عدة طعنات تويف على إثرها يف املستشفى -وقد جرى استجواب بقية العمال فأفاد مجموعة منهم مبشاهدتهم له وهو يطعن املجني عليه ،قرر املدعى عليه يف بداية المحاكمة بأنه مريض ويعاني من ضعف يف الذاكرة وال يذكر ما حصل معه وتنتابه حاالت جنون وأن املجني","document_number":"33280585","case_number":"4944","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/3","year":"1434","subject":"وإقامة حد الغيلة عليه -حيث تلقت الشرطة بالغا عن قيام املدعى عليه بطعن أحد الساكنني معه يف سكن العمال عدة طعنات تويف على إثرها يف املستشفى -وقد جرى استجواب بقية العمال فأفاد مجموعة منهم مبشاهدتهم له وهو يطعن املجني عليه ،قرر املدعى عليه يف بداية المحاكمة بأنه مريض ويعاني من ضعف يف الذاكرة وال يذكر ما حصل معه وتنتابه حاالت جنون وأن املجني","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪ 33280585 :‬تاريخه‪1433/6/3 :‬هـ‬\n                            ‫رقم الدعوى‪4944:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34188914‬تاريخه‪1434/4/15 :‬هـ‬\n\n\n    ‫قتــل ‪ ،‬قتــل عمــد ‪ ،‬قتــل بإســتخدام ســكني ‪ ،‬طلــب االدعــاء العــام إقامــة‬\n    ‫حــد الغيلــة ‪ ،‬دفــع املدعــى عليــه باملــرض النفســي (فصــام) ‪ ،‬تقريــر طبــي‬\n    ‫نفســي ‪ ،‬عــدم مراجعــة احلــق اخلــاص ‪ ،‬القاتــل واملقتــول مــن جنســية‬\n    ‫واحــدة ‪ ،‬درء حــد احلرابــة لعــدم اكتمــال أهليــة ‪ ،‬التعزيــر بالســجن‬\n    ‫واجللــد وتســليم املدعــى عليــه لســلطات بــاده لتمكــن أوليــاء الــدم مــن‬\n                                                                        ‫مطالبتــه‪.‬‬\n\n\n\n                                        ‫ما أشارت له احملكمة يف تسبيب احلكم‪.‬‬\n\n\n\n\n    ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بقتــل آخــر غيلــة‬\n    ‫بطعنــه بســكني عــدة طعنــات وهــو نائــم وطلــب إثبــات مــا أســند إليــه‬\n    ‫وإقامــة حــد الغيلــة عليــه ‪ -‬حيــث تلقــت الشــرطة بالغــا عــن قيــام املدعــى‬\n    ‫عليــه بطعــن أحــد الســاكنني معــه يف ســكن العمــال عــدة طعنــات‬\n    ‫تــويف علــى إثرهــا يف املستشــفى ‪ -‬وقــد جــرى اســتجواب بقيــة العمــال‬\n    ‫فأفــاد مجموعــة منهــم مبشــاهدتهم لــه وهــو يطعــن املجنــي عليــه ‪ ،‬قــرر‬\n    ‫املدعــى عليــه يف بدايــة احملاكمــة بأنــه مريــض ويعانــي مــن ضعــف يف‬\n    ‫الذاكــرة وال يذكــر مــا حصــل معــه وتنتابــه حــاالت جنــون وأن املجنــي‬\n\n‫‪5‬‬\n\f‫عليــه صديقــه وليــس بينهمــا عــداوة وال يعلــم لــم قبضــت عليــه الشــرطة‬\n‫وإمنــا أخبــر بأنــه متهــم يف قتــل شــخص وأفــادت التقاريــر الطبيــة إصابــة‬\n‫املدعــى عليــه مبــرض عقلــي هــو الفصــام مــع أعــراض جانبيــة وأنــه يعاني‬\n‫مــن مرضــه قبــل وقــوع اجلرميــة كمــا أوصــت اللجنــة الطبيــة تخفيــف‬\n‫املســؤولية اجلنائيــة عنــه ولتعلــق املطالبــة باحلــق العــام ‪ ،‬وألن القاتــل‬\n‫واملقتــول مــن جنســية واحــدة وافــدة مــن بلــدة واحــد ولعدم مراجعــة أولياء‬\n‫الــدم طيلــة الفتــرة املاضيــة ولئــا يتأخــر نظــر هــذه القضيــة وأطرافهــا‬\n‫مــن غيــر الســعوديني ومراعــاة حلــال املدعــى عليــه الصحيــة ومــا ينتــج عــن‬\n‫طــول ســجنه مــن أضــرار بالغــه وفيــه تأخيــر للحقــوق اخلاصــة ال ســيما‬\n‫وأن أوليــاء الــدم أجانــب ويقيمــون خــارج البــاد ‪ ،‬وألن املدعــى عليــه‬\n‫ناقــص األهليــة وفقــا ملــا جــاء يف التقاريــر الطبيــة قــررت احملكمــة مــا‬\n‫يلــي ‪ :‬أوال ‪ :‬درء حــد احلرابــة عــن املدعــى عليــه لعــدم كمــال أهليتــه ‪.‬‬\n‫ثانيــا ‪ :‬تعزيــره لقــاء مــا نســب إليــه للحــق العــام بســجنه خمــس ســنوات‬\n‫وجلــده أربعمئــة وخمســن جلــدة مفرقــة علــى ســت دفعــات متســاوية قــدر‬\n‫كل دفعــة خمســة وســبعون جلــدة وبــن كل دفعــة والتــي تليهــا خمســة‬\n‫عشــر يومــا ‪ .‬ثالثــا ‪ :‬تســليم املدعــى عليــه بعــد إنفــاذ احلكــم الســابق‬\n‫لســلطات بــاده يف باكســتان لتمكــن أوليــاء الــدم مــن مخاصمتــه يف‬\n‫احلــق اخلــاص ومبــا ذكــر كلــه حكمنــا وبعــرض احلكــم علــى الطرفني‬\n‫أعتــرض عليــه املدعــي العــام وطلــب عــرض احلكــم علــى محكمــة‬\n‫اإلســتئناف لتدقيــق احلكــم مكتفيــا مبــا يف أوراق املعاملــة أمــا املدعــى‬\n‫عليــه فهــز رأســه وابتســم فكــرر املترجــم الســؤال عــن رأيــه يف احلكــم‬\n         ‫فقــال موافــق عليــه ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                     ‫‪6‬‬\n\f    ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن ‪1429/11/26‬ه ـ لدينــا نحــن‬\n    ‫القضــاة يف احملكمــة العامــة بالدمــام ‪...........‬و ‪........... ...........‬و ‪...........‬‬\n    ‫بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم وتاريــخ ‪1429/7/25‬ه ـ‬\n    ‫بخصــوص دعــوى املدعــي العــام ضــد ‪ ...........‬وهــذا نصهــا بصفتــي‬\n    ‫مدعيــا عامــا يف دائــرة اإلدعــاء العــام مبدينــة الدمام أدعي علــى ‪........... :‬‬\n    ‫البالــغ مــن العمــر ( ‪ ) 26‬عامــا مســلم الديانــه غيــر محصــن باكســتاني‬\n    ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ( ‪ )...........‬قبــض عليــه بتاريــخ‬\n    ‫‪1428/9/20‬ه ـ وأحيــل إلــى شــعبة إصالحيــة الدمــام مبوجــب مذكــرة‬\n    ‫التوقيــف رقــم ( ‪ )...........‬وتاريــخ ‪1428/10/16‬ه ـ وباإلطــاع علــى‬\n    ‫احملضــر املعــد مــن قبــل رجــال الضبــط اجلنائــي بشــرطة محافظــة‬\n    ‫اخلفجــي تبــن أنــه يف يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ يف متــام‬\n    ‫الســاعة الثالثــة والثلــث عصــرا تبلغــت غرفــة العمليــات بشــرطة محافظــة‬\n    ‫اخلفجي عن قيام املدعى عليه بطعن زميله املدعو ‪........... /‬باكســتاني‬\n    ‫اجلنســية عــدة طعنــات بســكني كانــت بحوزتــه وذلــك أثنــاء تواجدهمــا‬\n    ‫مبقــر ســكنهما الواقــع بحــي ‪...........‬وأن املصــاب مت نقلــه ملستشــفى‬\n    ‫‪......................‬لعالجــه وباإلنتقــال ملســرح اجلرميــة واملعاينــة اتضــح أنــه يقــع‬\n    ‫بحــي ‪...........‬وبالتحديــد خلــف مجمــع ‪...........‬للمــواد الغذائيــة مــن اجلهــة‬\n    ‫الشــرقية وهــو عبــارة عــن كامــب ســكني لعمــال شــركة ‪...........‬وهــذا‬\n    ‫الكامــب مكــون مــن مجموعــة مــن الغــرف واتضــح أن مســرح احلــادث‬\n    ‫يقــع بالغرفــة رقــم ‪...........‬وهــذه الغرفــة يســكن بهــا ثمانيــة أشــخاص‬\n    ‫جميعهــم مــن اجلنســية الباكســتانية ومــن ضمنهــم اجلانــي واملجنــي عليــه‬\n\n‫‪7‬‬\n\f‫وبالدخــول داخــل الغرفــة اتضــح أن مســاحتها ( ‪ ) 4 , 5‬متــر وحتتــوي‬\n‫علــى عــدد أربعــة أســره ( ذات الدوريــن ) واتضــح أن الســرير اخلــاص‬\n‫باجلانــي هــو الســرير الثانــي باجلهــة الشــمالية بالســرير األســفل وســرير‬\n‫املجنــي عليــه هــو باجلهــة الغربيــة بالســرير األســفل وقــد شــوهد علــى‬\n‫أرضيــة الغرفــة املفروشــة بقــع دمويــة كبيــرة متناثــرة مــن ســرير املجنــي‬\n‫عليــه حتــى بــاب الغرفــة مــن الداخــل كمــا شــوهد آثــار دم علــى املرتبــه‬\n‫اخلاصــة بســرير املجنــي عليــه وبإجــراء التفتيــش الدقيــق للغرفــة كاملــة‬\n‫عثرنــا علــى ســكني حتمــل نفــس الشــعار ( ‪ ( ) Solinqen‬جــرى‬\n‫حتريزهــا ) وباإلنتقــال ملستشــفى ‪...........‬ملعاينــة اجلثــة شــوهدت جثــة‬\n‫لرجــل يف العقــد الرابــع مــن العمــر يدعــى ‪.........../‬باكســتاني اجلنســية‬\n‫وتبــن مــن خــال املعاينــة وجــود إحــدى عشــرة طعنــة يف أماكــن متفرقــة‬\n‫مــن محيــط الصــدر مــن األمــام واخللــف والذراعــن أحجامهــا مختلفــة‬\n‫ومنهــا مــا هــو نافــذ ومنهــا مــا هــو ســطحي كمــا شــوهد طعنــة أســفل‬\n‫القفــص الصــدري مــن األمــام وبالتحديــد يف اجلهــة اليمنــى أســفل الثــدي‬\n‫األميــن نافــذة وطولهــا حوالــي ‪13‬ســم وعــرض ‪ 5‬ســم كمــا متــت معاينــة‬\n‫املالبــس التــي كان يرتديهــا املجنــي عليــه وشــوهد عليهــا آثــار دمــاء‬\n‫وقــد جــرى تعميــم البحــث والتحــري عــن اجلانــي ‪........... /‬بنــاء علــى‬\n‫األوصــاف التــي أدلــى بهــا زمــاؤه وشــهود الواقعــة وبعــون اهلل مت القبــض‬\n‫علــى املذكــور مــن قبــل دوريــات البحــث اجلنائــي أثنــاء محاولتــه اخلــروج‬\n‫مــن حي‪...........‬حلــي ‪ ...........‬وكان يرتــدي نفــس املالبــس التــي كان‬\n‫يرتديهــا أثنــاء تنفيــذ اجلرميــة حيــث شــوهد آثــار دم علــى قميصــه وكان‬\n‫يف حالــة ارتبــاك وبضبــط إفــادات املشــمولني بالتحقيــق ‪ -1 :‬بضبــط‬\n‫أقــوال املبلــغ ‪........... /‬باكســتاني اجلنســية أفــاد أنــه بحوالــي الســاعة‬\n\n\n                                                                                    ‫‪8‬‬\n\f    ‫الثالثــة مــن عصــر يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وأثنــاء وجــوده‬\n    ‫داخــل غرفتــه اخلاصــة ســمع صــوت صيــاح داخــل إحــدى الغــرف‬\n    ‫بالكامــب الــذي يوجــد فيــه أكثــر مــن غرفــة فخــرج وشــاهد زميلــه‬\n    ‫املدعــو ‪........... /‬يطلــب منــه املســاعدة وذلــك لكــون املدعــو ‪........... /‬‬\n    ‫قــام باإلعتــداء علــى زميلهــم املدعــو ‪........... /‬وبالفعــل ذهــب معــه وشــاهد‬\n    ‫املتهــم ‪........... /‬داخــل الغرفــة ويقــوم بطعــن املجنــي عليــه بســكني‬\n    ‫كانــت بحوزتــه حيــث طعنــه مرتــن أمامــه وبعــد أن شــاهده املتهــم حاول‬\n    ‫طعنــه فقــام بالهــروب إلــى كامــب تابــع لشــركة ‪...........‬يقــع بنفــس‬\n    ‫احلــي وأبلــغ رجــال الدوريــات األمنيــة املوجوديــن هنــاك حلراســة املوقــع‬\n    ‫وبعــد حضــوره مــع الدوريــة اتضــح أن زميلــه املتهــم هــرب مــن املوقــع وقــد‬\n    ‫قــام بإســعاف زميلــه ‪ ...........‬ملستشــفى ‪ -2 ............‬بضبــط أقــوال ‪/‬‬\n    ‫‪......................‬باكســتاني اجلنســية أفــاد أنــه يف يــوم الواقعــة حضــر بعــد‬\n    ‫خــروج املتهــم خــارج الغرفــة وكانــت الســكني بيــده وقــد قــام مجموعــة‬\n    ‫مــن زمالئــه بالقبــض علــى املتهــم مــن اخللــف وقــام هــو بــدوره بطلــب‬\n    ‫الســكني منــه فأعطــاه إياهــا حيــث قــام بلمســها بيــده وحذفهــا وحــاول‬\n    ‫القبض عليه إال أنه هرب ‪ -3 .‬بضبط إفادة املقيم ‪........... /‬باكستاني‬\n    ‫اجلنســية أفــاد أنــه عنــد عودتــه مــن عملــه هو وزمــاؤه كل مــن ‪........... :‬و‬\n    ‫‪...........‬و ‪...........‬و ‪...........‬وكانــت الســاعة الثانيــة والنصــف بعــد الظهــر‬\n    ‫وقــد خلــد إلــى النــوم هــو وجميــع زمالئــه عــدا ‪...........‬الــذي لــم ينم وكان‬\n    ‫جالســا علــى ســريره وبعــد نومهــم بدقائــق ســمع صــوت صيــاح داخــل‬\n    ‫الغرفــة وعندمــا اســتيقظ اتضــح لــه بــأن الــذي يصيــح زميلــه ‪...........‬‬\n    ‫حيــث شــاهد ‪...........‬وبيــده ســكني ويقــوم بطعــن ‪...........‬وهــو مســتلق‬\n    ‫علــى ســريره وقــد شــاهد املتهــم يقــوم بطعنــه أربــع طعنــات جميعهــا يف‬\n\n\n‫‪9‬‬\n\f‫صــدره وذراعيــه ‪ -4 .‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية‬\n‫أفــاد بأنــه يف يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وبعــد عودتــه مــن‬\n‫عملــه هــو وزمــاؤه كل مــن ‪...........‬و ‪...........‬و ‪...........‬و ‪...........‬وبعــد‬\n‫دخولهــم لغرفتهــم التــي يســكنون بهــا خلــدوا جميعــا للنــوم على أســرتهم‬\n‫عــدا ‪...........‬الــذي كان جالســا علــى ســريره وبعــد دقائــق مــن نومــه‬\n‫اســتيقظ علــى صــوت صيــاح وشــاهد ‪...........‬يقــوم بطعــن زميلهــم ‪...........‬‬\n‫وهــو مســتلق علــى ســريره عــدة طعنــات بصــدره وعلــى ذراعــه األيســر‬\n‫وقــد هــرب خــارج الغرفــة خوفــا علــى حياتــه ثــم بعــد ذلــك خــرج ‪...........‬‬\n‫والســكني بيــده ومت القبــض عليــه مــن قبــل زمالئهــم بالكامــب الذيــن‬\n‫قامــوا بأخــذ الســكني مــن يــده ‪ -5 .‬بضبــط إفــادة املقيــم ‪........... /‬‬\n‫باكســتاني اجلنســية أفــاد بأنــه حوالــي الســاعة الثانيــة والنصــف مــن‬\n‫يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وعنــد عودته مــن عمله هو وزمالئه‬\n‫كل مــن ‪........... :‬و ‪ ...........‬و ‪...........‬و ‪...........‬وعنــد دخولهــم الغرفــة‬\n‫خلــدوا للنــوم جميعــا عــدا ‪...........‬حيــث كان جالســا وبعــد أن اســتغرق‬\n‫يف النــوم ســمع صــوت صيــاح داخــل الغرفــة واســتيقظ وشــاهد ‪...........‬‬\n‫يقــوم بطعــن ‪...........‬وهــو مســتلق علــى ســريره حيــث شــاهده وهــو يقــوم‬\n‫بطعنــه عــدة طعنــات متفرقــة جميعهــا بصــدره وبطنــه وقــد خــرج مــن‬\n‫الغرفــة خوفــا علــى حياتــه ‪ -6 .‬بضبــط إفادة املقيم ‪........... /‬باكســتاني‬\n‫اجلنســية أفــاد بأنــه أثنــاء وجــوده بغرفتــه ســمع صــوت زمالئــه بالكامــب‬\n‫وخــرج وشــاهد مجموعــة كبيــرة مــن العمــال أمــام غرفــة ‪...........‬وكان‬\n‫‪...........‬أمــام الغرفــة وبيــده ســكينا وقــد قــام مبســكه مــن اخللــف‬\n‫وتثبيتــه ثــم حضــر أحــد العمــال وســحب الســكني مــن يــده ورماهــا‬\n‫داخــل الغرفــة وبعــد ذلــك شــاهد ‪...........‬ســاقطا داخــل الغرفــة وينــزف‬\n\n\n                                                                                        ‫‪10‬‬\n\f     ‫دمــا ‪ -7 .‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية أفــاد بأنــه‬\n     ‫يســكن بالغرفــة التــي يســكن بهــا املتهــم واملجنــي عليــه وخمســة مــن‬\n     ‫زمالئــه جميعهــم مــن نفــس اجلنســية وإجمالــي عددهــم ثمانيــة وانــه عنــد‬\n     ‫عودتــه مــن عملــه ذلــك اليــوم كانــت الســاعة الثانيــة وخمســا وأربعــن‬\n     ‫دقيقــة مســاء وعنــد دخولــه للغرفــة شــاهد زمالئــه كال مــن ‪...........‬و‬\n     ‫‪...........‬و ‪...........‬و ‪...........‬جميعهــم نائمــن علــى أســرتهم أمــا ‪...........‬‬\n     ‫فــكان مســتلقيا علــى ســريره ولكنــه ليــس نائمــا فقــام بالذهاب لقصد‬\n     ‫اإلســتحمام وبعــد عودتــه شــاهد جميــع زمالئــه خــارج الغرفــة و‪...........‬‬\n     ‫ســاقط داخــل الغرفــة وينــزف دمــا وأنــه ســألهم عــن املتســبب يف ذلــك‬\n     ‫فأفــادوه بــأن ‪...........‬هــو مــن قــام بطعنــه وأنــه الذ بالفــرار ‪ -8‬بضبــط‬\n     ‫إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية أفــاد بأنــه حضــر مــن دوامــه‬\n     ‫ذلــك اليــوم حوالــي الســاعة الثالثــة إال عشــر دقائــق مســاء ووجــد زمــاءه‬\n     ‫ال مــن ‪...........‬و ‪...........‬و ‪...........‬و‪.............‬و ‪...........‬داخــل الغرفــة‬\n                                                                                          ‫ك َ‬\n     ‫وكانــوا جميع ـ َا نائمــن عــدا ‪...........‬الــذي كان مســتلقي َا علــى ســريره‬\n     ‫ويقــوم بشــرب الدخــان كونــه غيــر صائــم وقــام بنــزع مالبســه والذهــاب‬\n     ‫لــدورات امليــاه لقصــد اإلســتحمام وبعــد عودتــه شــاهد زميلــه ‪...........‬‬\n     ‫ســاقط َا داخــل الغرفــة وينــزف دم ـ َا وشــاهد املتهــم وهــو يهــرب خــارج‬\n     ‫الكامــب وقــد أخبــره زمــاؤه املوجوديــن بــأن ‪...........‬هــو مــن قــام‬\n     ‫باإلعتــداء عليــه ‪ -9‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية‬\n     ‫أفــاد أنــه يف يــوم احلادثــة رجــع مــن عملــه قرابــة الســاعة الثانيــة والنصــف‬\n     ‫ال مــن ‪...........‬و‪...........‬و‪...........‬وقــد‬\n                                                   ‫مســاء ًا ووجــد بالغرفــة زمــاءه ك َ‬\n     ‫قــام بتبديــل مالبســه ثــم خــرج فــور َا إلــى املســجد وعنــد عودتــه مــن‬\n     ‫الصــاة شــاهد مجموعــة كبيــرة مــن العمــال أمــام الغرفــة التي يســكن‬\n\n\n‫‪11‬‬\n\f‫بهــا هــو وزمــاؤه وهنــاك دم داخــل الغرفــة وقــد أخبــره زمــاؤه بــأن‬\n‫‪...........‬قــام بطعــن ‪...........‬وأنهــم قامــوا بإســعافه قبــل حضــوره وأن‬\n‫‪...........‬هــرب مــن املوقــع وأضــاف بــأن ‪...........‬خــال شــهر رمضــان ال‬\n‫يصــوم ويقــوم بشــرب الدخــان بشــكل مســتمر وبإســتجواب املتهــم ‪/‬‬\n‫‪ .....‬أقــر بأنــه يســكن مــع ‪...........‬يف غرفــة واحــدة ومعــه ســتة آخــرون‬\n‫وأنــه بعــد عودتــه مــن عملــه حوالــي الســاعة الثانيــة والنصــف ظهــر َا برفق‬\n‫زمالئــه كل مــن ‪........... /‬و‪...........‬و‪...........‬و‪...........‬وبعــد دخولهــم‬\n‫لغرفهــم التــي يســكنون بهــا خلــد جميــع زمالئــه للنــوم علــى أســرتهم‬\n‫وهــو لــم ينــم حيــث كان جالس ـ َا علــى ســريره وقــد فكــر أن يقــوم‬\n‫باإلعتــداء علــى ‪...........‬كــون املذكــور دائمـ َا يســتهتر بــه ويتلفــظ عليــه‬\n‫بألفــاظ بذيئــة منهــا ‪ :‬يتهمــه بأنــه (‪ )......‬وأنــه شــخص مجنــون ولذلــك‬\n‫قــام بفتــح شــنطته اخلاصــة بــه والتــي كانــت حتــت ســريره ثــم أخــرج منهــا‬\n‫ســكين ًا كانــت بحوزتــه وبعــد ذلــك قــام باإلعتــداء علــى ‪...........‬أثنــاء‬\n‫نومــه حيــث قــام بطعنــه عــدة طعنــات جميعهــا يف منطقــة الصــدر والبطن‬\n‫والذراعــن حتــى ســقط علــى األرض وأن جميــع زمالئــه اســتيقظوا مــن‬\n‫نومهــم ثــم هربــوا خــارج الغرفــة وبعــد تنفيــذ جرميتــه قــام باخلــروج خــارج‬\n‫الغرفــة والســكني بيــده وقــد قــام زمــاؤه املوجودون بالســكن بالقبض‬\n‫عليــه وســحب الســكني منــه وأن مــن قــام بأخذهــا منه هو زميلــه ‪...........‬‬\n‫الــذي يســكن بالغرفــة رقــم ‪...........‬بنفــس الكامــب ثــم بعــد ذلــك هــرب‬\n‫مــن املوقــع خوفـ ًا مــن العقوبــة حتــى مت القبــض عليــه داخــل حــي ‪...........‬‬\n‫وأنــه معتــرف بقتــل املذكــور والتســبب يف وفاتــه ويتحمــل مســئولية‬\n‫جميــع مــا حــدث وأنــه ليــس لــه شــريك مــن قريــب أو بعيــد يف تنفيــذ‬\n‫اجلرميــة ولــم يحرضــه أحــد علــى ذلــك وأن الســبب الــذي أدلــى بــه هــو مــا‬\n\n\n                                                                                       ‫‪12‬‬\n\f     ‫دفعــه لقتــل املذكــور وال يوجــد أي ســبب آخــر كمــا أنــه ال يعانــي مــن‬\n     ‫أي مــرض نفســي أو صحــي ولــم يكــن حتــت تأثيــر أي ممنوعــات بــل‬\n     ‫كان بكامــل قــواه العقليــة وأنــه نــادم كل النــدم علــى ما فعله ومســتعد‬\n     ‫لتمثيــل اجلرميــة وصــادق علــى أقوالــه شــرع ًا وانتهــى التحقيــق علــى اتهــام‬\n     ‫املقيــم ‪........... /‬بقتــل املدعــو ‪...................... /‬قتــل غيلــة وذلــك بطعنــه‬\n     ‫بســكني عــدة طعنــات وهــو نائــم وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬‬\n     ‫إقــراره املصــدق شــرع ًا واملــدون علــى الصفحــة رقــم (‪ )3-2‬مــن ملــف‬\n     ‫التحقيــق رقــم (‪ )3‬علــى اللفــة رقــم (‪ -2 )3‬مــا ورد يف أقــوال الشــهود‬\n     ‫املدونــة علــى الصفحــات رقــم (‪ )4-2‬مــن ملــف التحقيــق رقــم (‪-3 )4‬‬\n     ‫محضــر االنتقــال والقبــض املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪-2‬‬\n     ‫‪ )6‬مــن ملــف التحقيــق رقــم (‪ )5‬واملرفــق علــى اللفــة رقــم (‪ -4 )5‬التقريــر‬\n     ‫الطبــي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )65‬و (‪ )66‬و (‪-69‬‬\n     ‫‪ -5 )75‬تقريــر األدلــة اجلنائيــة املنــوه عنهــا واملرفقــة علــى اللفــة رقــم‬\n     ‫(‪ -6 )6( )59( )57( )54-53‬محضــر متثيــل اجلرميــة مــن قبــل املتهــم مــع‬\n     ‫شــريط الفيديــو واملــدون علــى الصفحــة رقــم (‪ )8‬مــن ملــف التحقيــق رقــم‬\n     ‫(‪ )5‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه على ســوابق مســجلة‬\n     ‫وحيــث أن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫مــن قتــل نفــس معصومــة غيلــة فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد الغيلــة وفقـ ًا للمــادة األولــى مــن‬\n     ‫قــرار هيئــة كبــار العلمــاء رقــم (‪ )38‬وتاريــخ ‪1395/8/11‬ه ـ الــوارد‬\n     ‫باألمــر الســامي رقــم (‪ )27467‬يف ‪1395/9/20‬ه ـ ( احلــق اخلــاص ما زال‬\n     ‫قائم ـ ًا ) ثــم يف جلســة أخــرى حضــر املدعــى عليــه وتليــت عليــه الدعــوى‬\n     ‫عــن طريــق مترجــم احملكمــة ‪...........‬فقــال أنــا مريــض ومتعــب وقــد‬\n\n\n‫‪13‬‬\n\f‫حضــرت للتــو مــن املستشــفى فرفعــت اجللســة ثــم يف جلســة أخــرى وردت‬\n‫إفــادة أن املدعــى عليــه منــوم يف املستشــفى ثــم يف جلســة أخــرى حضــر‬\n‫املدعــى عليــه ومت ســؤاله عــن الدعــوى فأجــاب عــن طريــق املترجــم‬\n‫املذكــور إننــي أعمــل يف شــركة يف محافظــة اخلفجــي وأســكن يف‬\n‫غرفــة فيهــا ثمانيــة أشــخاص ومــن ضمنهــم ‪ ...........‬الباكســتاني وهــو‬\n‫صديــق لــي وليــس بينــي وبينــه إال اخليــر وال أذكــر أي شــيء عمــا ورد يف‬\n‫الدعــوى بخصــوص قتــل ‪...........‬حيــث أننــي مصــاب مبــرض عقلــي‬\n‫وكنــت أراجــع املستشــفى واســتخدم العــاج وعنــدي ضعــف يف‬\n‫الذاكــرة وحتصــل لــي فتــرات جنــون ال أعلــم مــاذا أعمــل فيهــا وأن‬\n‫الشــرطة قبضــت علـ ّـي وأخبرونــي بأنــي متهــم يف قضيــة قتــل وال أعلــم‬\n‫مــاذا يقصــدون ثــم حصــل بعــد ذلــك حتقيــق معــي وال أذكــر مــاذا حصــل‬\n‫يف التحقيــق هــذا مــا ذكــره املدعــى عليــه ولــذا رأينــا إحالــة املدعــى‬\n‫عليــه إلــى مستشــفى نفســي للكشــف عليــه وتزويدنــا بتقريــر طبــي عــن‬\n‫حالتــه العقليــة ورفعــت اجللســة حتــى رجــوع اجلــواب ثــم وردنــا التقريــر‬\n‫الطبــي الصــادر مــن مستشــفى الصحــة النفســية بالطائــف رقــم‪...........‬يف‬\n‫‪1431/4/27‬ه ـ ونــص املقصــود منــه أمــا مــا يخــص املســؤولية اجلنائيــة‬\n‫وبعــد اإلطــاع علــى ملــف التحقيــق وتفاصيــل القضيــة فتــرى اللجنــة‬\n‫الطبيــة النفســية اجلنائيــة أنــه نظــر ًا لوجــود املــرض العقلــي الفصــام ومــا‬\n‫يصاحبــه مــن أفــكار ومعتقــدات مرضيــة خاطئــة والتــي تؤثــر يف‬\n‫الســلوك واحلكــم علــى األمــور بشــكل ســليم وعــدم تقديــر النتائــج‬\n‫وعواقــب األفعــال ونتيجــة إلضطــراب حالــة املذكــور العقليــة قبــل وأثناء‬\n‫ارتكابــه اجلرميــة فــإن ذلــك يخفــف مــن املســؤولية اجلنائيــة حيــال مــا‬\n‫أقــدم عليــه يف القضيــة احلاليــة ويجعلهــا مســؤولية جزئيــة أي يتحــول‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫القتــل العمــد إلــى القتــل اخلطــأ أعضــاء اللجنــة الطبيــة النفســية اجلنائيــة‬\n     ‫ثــم يف جلســة أخــرى حضــر املدعــى عليــه وأفــاد عــن طريــق مترجــم‬\n     ‫ا احلمــد هلل حتســنت حالتــي وقــد قمــت بقتــل املجنــي‬       ‫احملكمــة قائ ـ ً‬\n     ‫عليــه ‪...........‬وال أذكــر بــأي شــيء قتلتــه بســكني أو عصــا ال أذكــر‬\n     ‫وكان املجنــي عليــه يســكن معــي وصديقــي وكان ميــزح معــي وميــد‬\n     ‫يــده علــى مؤخرتــي وأنــا أقــول إننــي رجــل وال يصلــح هــذا العمــل وتأثــرت‬\n     ‫بســبب هــذا الفعــل منــه وأصبحــت أفكــر فيــه ثــم تكــرر منــه هــذا‬\n     ‫الفعــل وكذلــك الســب والشــتم ملــدة تقــارب ســتة أشــهر وقــد صبــرت‬\n     ‫عليــه لكونــه ســاعدني عنــد قدومــي مــن باكســتان وقبــل حادثــة القتــل‬\n     ‫حضــر إلـ ّـي املجنــي عليــه يف غرفتــي وملــس مؤخرتــي وغضبــت غضب ـ ًا‬\n     ‫شــديد ًا وكان الوقــت قبيــل العصــر يف نهــار رمضــان وأنــا لــدي مــرض‬\n     ‫احتــاج إلــى شــرب املــاء ولــم أكــن صائم ـ ًا أمــا هــو فــا أعلــم وقمــت‬\n     ‫باإلعتــداء عليــه ال أذكــر بــأي آلــة وبعدهــا علمــت أنــه تــويف وتأســفت‬\n     ‫علــى موتــه وقــد نصحنــي أحــد العمــال وقــت اجلرميــة بالهــروب فهربــت‬\n     ‫داخــل مدينــة اخلفجــي يف إحــدى العمائــر حتــت اإلنشــاء ثــم احتجــت إلــى‬\n     ‫املــاء وخرجــت ويف أثنــاء شــربي حضــرت الهيئــة فقبضــت علـ ّـي ثــم حولــت‬\n     ‫إلــى الشــرطة وحقــق معــي وقــد ســمعت أن ورثــة املجنــي عليــه قــد تنازلــوا‬\n     ‫هــذه إجابتــي فجــرى ســؤال املدعــي العــام البينــة علــى الدعــوى فقــال مــا‬\n     ‫جــاء يف الئحــة الدعــوى ومــن ذلــك اعتــراف املدعــى عليــه والشــهود‬\n     ‫ورفعــت اجللســة لإلطــاع علــى املعاملــة ثــم يف جلســة أخــرى فتحــت يــوم‬\n     ‫اإلثنــن ‪1433/5/24‬ه ـ لدينــا نحــن القضــاة يف احملكمــة العامــة‬\n     ‫بالدمــام ‪...........‬خلــف القاضــي ‪......................‬و ‪...........‬خلــف القاضــي‬\n     ‫‪...........‬و ‪......................‬خلــف القاضــي‪ ...........‬حضــر املدعــي العــام‬\n\n\n‫‪15‬‬\n\f‫‪......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬‬\n‫وحضــر حلضــوره املدعــى عليــه ‪...........‬وقــد مت دراســة مــا ســبق ضبطــه‬\n‫وبعرضــه علــى املدعــى عليــه عــن طريــق مترجــم احملكمــة ‪...........‬‬\n‫باكســتاني اجلنســية ومصــرح لــه باإلقامــة رقــم ‪...........‬وســؤاله عمــا‬\n‫ســبق ضبطــه عــن طريــق املترجــم ضحــك ولــم يجــب بشــيء ســوى بذكــر‬\n‫اســمه وكان قــد طلــب إعــادة فحــص املدعــى عليــه عن طريق مستشــفى‬\n‫الصحــة النفســية بالطائــف مــن قبــل جلنــه مختصــه واإلفــادة عمــا يلــي ‪( :‬‬\n‫أوال ‪ :‬هــل ميكــن معرفــة حالــة الســجني العقليــة وقــت وقــوع اجلرميــة‬\n‫ومبعنــى آخــر هــل كان وقــت اجلرميــة حتــت تأثيــر املــرض املذكــور ‪.‬‬\n‫ثانيــا ‪ :‬هــل يعتبــر الســجني املذكــور واحلــال مــا ذكــر مســؤول عــن‬\n‫تصرفاتــه ‪ .‬ثالثــا ‪ :‬هــل املــرض املذكــور وقتــي بحيــث يتــردد علــى‬\n‫صاحبــه مــن وقــت آلخــر أو هــو دائــم ‪ .‬رابعــا ‪ :‬متــى تاريــخ هــذا املــرض‬\n‫كمــا قررنــا أن نظــر هــذه الدعــوى واحلكــم فيهــا متوقــف علــى اإلجابــة‬\n‫علــى تلــك األســئلة بــراءة للذمــة ) فوردنــا التقريــر الطبــي الصــادر مــن‬\n‫مستشــفى الصحــة النفســية بالطائــف برقــم‪...........‬يف ‪1432/2/2‬ه ـ‬\n‫ونــص احلاجــة منــه مــا يلــي ‪ ( :‬إحلاقــا لتقريرنــا الطبــي النفســي اجلنائــي‬\n‫رقم‪...........‬بتاريــخ ‪1431/4/27‬ه ـ والــذي أوضحنــا فيــه التالــي ‪ -1 :‬مت‬\n‫دخولــه اجلنــاح اجلنائــي لدينــا بتاريــخ ‪1430/5/17‬ه ـ يف قضيــة قتــل وقــد‬\n‫شــخصت حالتــه ( فصــام مــع أعــراض مزاجيــه ) وقــد بوشــر بالعــاج‬\n‫واســتقرت حالتــه وخــرج بتاريــخ ‪1430/7/26‬ه ـ ‪ -2 .‬عــرض املذكــور‬\n‫علــى اللجنــة الطبيــة النفســية اجلنائيــة لدينــا بتاريــخ ‪1432/2/11‬ه ـ‬\n‫وكانــت حالتــه مســتقرة علــى العــاج وشــخصت حالتــه ( فصــام مــع‬\n‫أعــراض مزاجيــه ) ‪ .‬القــرار والتوصيــات ‪ -1 .‬يعــود ملرجعــه مــع عــاج‬\n\n\n                                                                                     ‫‪16‬‬\n\f     ‫نفســي ملــدة أســبوعني عبــارة عــن ( ســيرنيز ‪ 5‬ملغ أقــراص بواقع قرصان‬\n     ‫صباحــا وقرصــان مســاء ‪ +‬ديباكــن ‪ 200‬ملــغ قــرص ثــاث مــرات‬\n     ‫يوميــا ‪ +‬كوجنتــن ‪ 2‬ملــغ قــرص صباحــا وقــرص مســاء ) علــى أن‬\n     ‫يراجــع أقــرب عيــادة نفســية ملرجعــه قبــل انتهــاء العــاج ‪ -2 .‬ردا علــى‬\n     ‫استفســار ناظــر القضيــة عــن إمكانيــة معرفــة حالــة الســجني وقــت‬\n     ‫وقــوع اجلرميــة يفيدكــم أن املذكــور عــرض علــى اللجنــة يف‬\n     ‫‪1430/5/17‬ه ـ وكانــت القضيــة حدثــت يف ‪1428/9/20‬ه ـ وقد رأت‬\n     ‫اللجنــة أن املذكــور عنــد عرضــه كان يعانــي مــن أعــراض واضحــة‬\n     ‫للمــرض العقلــي الذهانــي ( الفصــام ) وأعطــي العــاج الــازم وحتســنت‬\n     ‫حالتــه ‪ ،‬وذكــر الدوافــع وراء جرميتــه واألعــراض التــي كان يعانــي‬\n     ‫منهــا وقــت ارتــكاب اجلرميــة ‪ .‬وعنــد إطــاع اللجنــة علــى أقوالــه يف‬\n     ‫التحقيــق كانــت أقوالــه مطابقــة ألقوالــه احلاليــة ومبنيــة علــى توهمــات‬\n     ‫مرضيــة ال أســاس لهــا مــن الصحــة ( حســب مــا يتضــح مــن أقــوال زمالئــه‬\n     ‫يف الغرفــة ) حيــث كان يعتقــد أن املجنــي عليــه يفعــل الفاحشــة بــه وهــو‬\n     ‫نائــم وذكــر يف التحقيــق أن املجنــي عليــه يســبه أنــه ( ‪ ) .....‬وقــد حــذره‬\n     ‫أكثــر مــن مــره ثــم قــام بقتلــه ‪ ،‬وأفــاد أنــه يف تلــك الفتــرة كان يســمع‬\n     ‫أصــوات ال وجــود لهــا يف الواقــع تســبه وتشــتمه ( أي أنــه كان يعانــي مــن‬\n     ‫أعــراض مرضيــة قبــل وأثنــاء وبعــد جرميتــه وكان لتلــك األعــراض دورا‬\n     ‫فاعــا يف حــدوث اجلرميــة ) ممــا جعــل اللجنــة توصــي بتخفيــف املســئولية‬\n     ‫اجلنائيــة عنــه ‪ -3 .‬أمــا عــن مــرض الفصــام الــذي يعانــي منــه فهــو مــرض‬\n     ‫مزمــن ومســتمر يتحســن مــع العــاج وهــو قابــل لإلنتكاســه يف أي وقــت‬\n     ‫‪ ،‬وال تســتطيع اللجنــة الطبيــة النفســية اجلنائيــة حتديــد تاريــخ إصابتــه‬\n     ‫باملــرض العقلــي ولكــن يتضــح لهــا أن املذكــور كان يعانــي مــن مرضه‬\n\n\n‫‪17‬‬\n\f‫قبــل وقــوع اجلرميــة بنــاء علــى مــا رأتــه اللجنــة عنــد الكشــف احلالــي علــى‬\n‫املذكــور مــن أعــراض واضحــة للمــرض ومــا مت اإلطــاع عليــه مــن‬\n‫أقوالــه أثنــاء التحقيــق معــه يف قضيتــه احلاليــة ) وبتأمــل مــا ســبق ضبطــه‬\n‫تبــن أن اإلدعــاء العــام يطالــب بإقامــة حــد الغيلــه علــى املدعــى عليــه‬\n‫‪ ...........‬لقاء قتله ‪...........‬باكســتاني اجلنســية وأن املدعى عليه مســجون‬\n‫بســبب هــذه القضيــة منــذ تاريــخ ‪1428/10/16‬ه ـ وألن التقاريــر الطبية‬\n‫أثبتــت إصابــة املدعــى عليــه مبــرض عقلــي هــو الفصــام مــع أعــراض‬\n‫جانبيــة كمــا جــاء يف التقاريــر الطبيــة أن املدعــى عليــه كان يعانــي مــن‬\n‫مرضــه قبــل وقــوع اجلرميــة كمــا أوصــت اللجنــة الطبيــة تخفيــف‬\n‫املســؤولية اجلنائيــة عنــه وألن مــا يطالــب بــه املدعــي العــام إمنــا هــو للحــق‬\n‫العــام وألن القاتــل واملقتــول مــن جنســية واحــده وافــدة وألنــه لــم يراجــع‬\n‫طــوال املــدة الســابقة والتــي بلغــت نحــو خمــس ســنني مــن يطالــب باحلــق‬\n‫اخلــاص ولئــا يتأخــر نظــر هــذه القضيــة وأطرافهــا مــن غيــر الســعوديني‬\n‫ومراعــاة حلــال املدعــى عليــه الصحيــة ومــا ينتــج عــن طــول ســجنه مــن‬\n‫أضــرار بالغــه وفيــه تأخيــر للحقــوق اخلاصــة ال ســيما وأن أوليــاء الــدم‬\n‫أجانــب ويقيمــون خــارج البــاد لــكل ذلــك وألن املدعــى عليــه ناقــص‬\n‫األهليــة وفقــا ملــا جــاء يف التقاريــر الطبيــة قررنــا مــا يلــي ‪ :‬أوال ‪ :‬درأنــا‬\n‫حــد احلرابــة عــن املدعــى عليــه لعــدم كمــال أهليتــه ‪ .‬ثانيــا ‪ :‬تعزيــره لقــاء‬\n‫مــا نســب إليــه للحــق العــام بســجنه مــدة خمــس ســنوات وجلــده أربعمائــه‬\n‫وخمســن جلــده مفرقــه علــى ســت دفعــات متســاوية قــدر كل دفعــه‬\n‫خمســه وســبعون جلــده وبــن كل دفعــه والتــي تليهــا خمســة عشــر يومــا‬\n‫‪ .‬ثالثــا ‪ :‬تســليم املدعــى عليــه بعــد انفــاذ احلكــم الســابق لســلطات بــاده‬\n‫يف باكســتان لتمكــن أوليــاء الــدم مــن مخاصمتــه يف احلــق اخلــاص‬\n\n\n                                                                                          ‫‪18‬‬\n\f     ‫ومبــا ذكــر كلــه حكمنــا وبعــرض احلكــم علــى الطرفــن أعتــرض‬\n     ‫عليــه املدعــي العــام وطلــب عــرض احلكــم علــى محكمــة اإلســتئناف‬\n     ‫لتدقيــق احلكــم مكتفيــا مبــا يف أوراق املعاملــة أمــا املدعــى عليــه فهــز‬\n     ‫رأســه وابتســم فكــرر املترجــم الســؤال عــن رأيــه يف احلكــم فقــال‬\n     ‫موافــق عليــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبه وسلم ‪ .‬حرر يف ‪1433/5/24‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد ثــم انــه يف هــذا اليــوم الثالثــاء املوافــق ‪/14‬‬\n     ‫‪1434/5‬ه ـ وبعــد ورود املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n     ‫الشــرقية ومشــفوعها القــرار رقــم ‪ 34188914‬وتاريــخ ‪/1434 /4 /15‬‬\n     ‫ه ـ ومضمونــه املصادقــة علــى احلكــم وعليــه توقيــع اصحــاب الفضيلــة‬\n     ‫قضــاة االســتئناف ‪......................‬التوقيــع قاضــي اســتئناف ‪...........‬‬\n     ‫التوقيــع قاضــي اســتئناف ‪...........‬التوقيــع رئيس اســتئناف ‪......................‬‬\n     ‫التوقيــع رئيــس الدائــرة ‪...........‬التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434 /5 /14‬ه ـ‬\n\n\n\n\n‫‪19‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":5,"source_page_end":19,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"905df45af7ba73749b191c12fd4c6602a58a468e4e5bffbcddbce165de024106","normalized_text_hash":"d0b2b81a13fb054fd487083181f8e149ab764300652ac87b207c8f740fc6a592","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p5-33280585"},{"id":"d864f2a3-665d-5654-8d8d-cffc19e9e60c","document_type":"judgment","category":"judicial","subcategory":"general","title":"-املدعى عليه -خلاف بينهما وتهديده السابق ،أنكر املدعى عليه الدعوى ودفع بأنه كان حينها خارج مدينة الرياض ،بفحص الساح الذي ضبط مع املدعى عليه ومقارنته مع أظرف الطلقات الفارغة املرفوعة من موقع اجلرمية وقد ظهر بأن األظرف األربعة مطلقة من","document_number":"32203464","case_number":"36881","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/8/12","year":"1434","subject":"-املدعى عليه -خلاف بينهما وتهديده السابق ،أنكر املدعى عليه الدعوى ودفع بأنه كان حينها خارج مدينة الرياض ،بفحص الساح الذي ضبط مع املدعى عليه ومقارنته مع أظرف الطلقات الفارغة املرفوعة من موقع اجلرمية وقد ظهر بأن األظرف األربعة مطلقة من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 32203464 :‬تاريخه‪1432/8/12 :‬هـ‬\n                       ‫رقم الدعوى‪36881:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 349716‬تاريخه‪1433/1/12 :‬هـ‬\n\n\n‫قتــل ‪ ،‬شــروع يف قتــل ‪ ،‬حيــازة ســاح بــدون ترخيــص ‪ ،‬اســتخدام ســاح‬\n‫نــاري ‪ ،‬دعــوى عامــة وخاصــة ‪ ،‬حكــم بــرد الدعــوى ثــم الرجــوع عنــه ‪،‬‬\n‫مشــروعية االعتمــاد علــى قــرار أهــل اخلبــرة ‪ ،‬مشــروعية التعزيــر يف‬\n‫احلــق اخلــاص ‪ ،‬وجــود ســوابق قضائيــة‪ ،‬ثبــوت إدانــة ‪ ،‬تعزيــر بالســجن‬\n                                                                   ‫وجلــد‪.‬‬\n\n\n\n                                     ‫ما أشار له القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العام بقيــام املدعى عليه بالشــروع‬\n‫يف قتــل أخيــه بإطــاق عــدة طلقــات ناريــة عليــه وطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة حيــث تلقــت الشــرطة بالغــا مــن‬\n‫أحــد املواطنــن بســماعه ثــاث طلقــات ناريــة وباســتطالعه وجــد املجنــي‬\n‫عليــه علــى الرصيــف وباســتجواب املجنــي عليــه ألقــى التهمــة علــى أخيــه‬\n‫‪ -‬املدعــى عليــه ‪ -‬خلــاف بينهمــا وتهديــده الســابق‪ ،‬أنكــر املدعــى عليــه‬\n‫الدعــوى ودفــع بأنــه كان حينهــا خــارج مدينة الرياض‪ ،‬بفحص الســاح‬\n‫الــذي ضبــط مــع املدعــى عليــه ومقارنتــه مــع أظــرف الطلقــات الفارغــة‬\n‫املرفوعــة مــن موقــع اجلرميــة وقــد ظهــر بــأن األظــرف األربعــة مطلقــة مــن‬\n\n                                                                                     ‫‪20‬‬\n\f     ‫املســدس احملــرز املضبــوط بحــوزة املدعــى عليــه أمــا الظرفــان الفارغــان‬\n     ‫فهــي مطلقــة مــن ســاح نــاري واحــد ويطلــق عــادة مــن األســلحة مــن ذات‬\n     ‫العيــار‪ ،‬مت القبــض علــى املدعــى عليــه ومعــه ســيارة مســتأجرة والعثــور‬\n     ‫معــه يف ســيارته علــى املســدس املشــار لــه يف تقريــر األدلــة اجلنائيــة ‪،‬‬\n     ‫أنكــر املدعــى عليــه بــأن املســدس يعــود لــه ‪ ،‬وإلنــكار املدعــى عليــه‬\n     ‫دعــوى املدعــي العــام واخلــاص وملــا تضمنتــه شــهادة الشــاهدين ومحضــر‬\n     ‫االنتقــال مــن العثــور علــى ظــروف فارغــة ومــا تضمنــه خطــاب مديــر‬\n     ‫شــرطة احلــدود الشــمالية مــن العثــور علــى املســدس الــذي انطلقــت منــه‬\n     ‫األظــرف الفارغــة حســب قــرار األدلــة اجلنائيــة وكل مــا تقــدم يــورث‬\n     ‫الشــبهة القويــة نحــو املدعــى عليــه يف احلــق العــام إال أنــه ال ميكــن معهــا‬\n     ‫إثبــات احلــق اخلــاص ‪ ،‬لــذا فقــد قــررت احملكمــة مــا يلــي‪:‬أوال‪ /‬رد دعــوى‬\n     ‫املدعــي اخلــاص لعــدم كفايــة األدلــة‪ .‬ثانيــا‪ /‬توجيــه الشــبهة القويــة علــى‬\n     ‫قيــام املدعــى عليــه بإطــاق النــار علــى املجنــي عليــه وتعزيــره ألجلــه‬\n     ‫بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده ثالثمئــة جلــدة مفرفــة‬\n     ‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا‬\n     ‫عشــرة أيــام ‪ ،‬بعــرض احلكــم علــى املدعــي العــام قــرر عــدم القناعــة‬\n     ‫مكتفيــا بالئحــة الدعــوى كمــا قــرر املدعــي اخلــاص واملدعــى عليــه‬\n     ‫عــدم القناعــة وطلبــا متكينهمــا مــن تقــدمي الئحــة فأفهمــا بالتعليمــات ‪،‬‬\n     ‫عــادت القضيــة مــن محكمــة االســتئناف بــأن رد دعــوى املدعــي اخلــاص‬\n     ‫محــل نظــر لقــوة الشــبهة وطلبــت إمــا تقريــر عقوبــة يف احلــق اخلــاص أو‬\n     ‫زيــادة العقوبــة الصــادرة يف احلــق العــام وإيضــاح مــا للحــق العــام واخلــاص‪،‬‬\n     ‫لــم يحضــر املجنــي عليــه لعالجــه خــارج اململكــة ‪ ،‬وملــا جــاء يف أســباب‬\n     ‫احلكــم يقــوي جانــب املدعــي اخلــاص واليمــن تشــرع يف جانــب األقــوى‬\n\n\n‫‪21‬‬\n\f‫مــن املتداعيــن وألن املدعــي اخلــاص خــارج اململكــة ممــا يتعــذر معــه‬\n‫احلضــور ألداء اليمــن وألن احلــق اخلــاص ال يثبــت مبجــرد الشــبهة لــذا‬\n‫فقــد قــررت احملكمــة عــدم عدولهــا عمــا حكمــت بــه ســلفا ‪ ،‬عــادت‬\n‫القضيــة مــرة أخــرى مــن محكمــة االســتئناف بطلــب إعــادة النظــر مــرة‬\n‫أخــرى يف احلكــم ‪ ،‬قــرر القاضــي رجوعــه عــن الفقــرة األولــى والثانيــة‬\n‫مــن احلكــم ‪ ،‬وقــررت احملكمــة ثبــوت قيــام املدعــى عليــه بإطــاق النــار‬\n‫علــى املدعــي اخلــاص عــدة طلقــات أدت إلــى إصابتــه باإلصابــات املشــار‬\n‫لهــا يف التقريــر الطبــي املرفــق بــاألوراق وقــررت تعزيــره ألجلــه مبــا يلــي‪:‬‬\n‫أوال‪ /‬ســجن املدعــى عليــه ثــاث ســنوات وجلــده ثالثمئــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــرة أيــام وذلــك‬\n‫للحــق اخلــاص ‪ .‬ثاني ـاً‪ :‬ســجن املدعــى عليــه ســنتني مــن تاريــخ إيقافــه‬\n‫وجلــده مئتــي جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة‬\n‫بــن كل دفعــة واألخــرى عشــرة أيــام وبــن هــذا اجللــد واجللــد الــذي يف‬\n‫كمــت ‪ ،‬وعرضــه علــى‬       ‫األولــى مــن احلكــم عشــرة أيــام وبجميــع ذلــك َح َ‬\n‫املدعــى العــام قــرر بأنــه ال زال معترضـ ًا ‪ ،‬أمــا املدعــي اخلــاص واملدعــى‬\n‫عليــه فقــد قــررا عــدم القناعــة ورغبــا رفــع املعاملــة حملكمــة االســتئناف‬\n   ‫بــدون الئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزئيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالريــاض برقــم وتاريــخ ‪ 1431/12/22‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪ 1431/12/22‬هـ ففي يوم الثالثاء املوافق‪1432/03/12‬‬\n\n                                                                                       ‫‪22‬‬\n\f     ‫ه ـ أفتتحــت اجللســة الســاعة ‪ 1 : 30‬وفيهــا قــدم املدعــي العــام ‪.....‬دعــواه‬\n     ‫ضــد ‪..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقـ ـ ــم (‪ ).....‬قائــا‬\n     ‫يف دعــواه عليــه إنــه بتاريــخ ‪1431/9/29‬ه ـ تســلم مركــز شــرطة‬\n     ‫‪.....‬و‪ .....‬تقريــر إحــدى فــرق الدوريــات األمنيــة رقــم (‪ ).....‬املتضمــن أنــه‬\n     ‫أثنــاء قيــام الفرقــة بعملهــا تلقــت بالغــا عــن شــخص مصــاب بحــي ‪.....‬‬\n     ‫علــى شــارع ‪.....‬وعنــد انتقــال الفرقــة للموقــع افــاد املبلــغ ‪.....‬أنــه ســمع‬\n     ‫صــوت ثــاث طلقــات ناريــة وهــو بداخــل املســجد وبعــد خروجــه شــاهد‬\n     ‫الشــخص املصــاب علــى الرصيــف الــذي نقــل ملستشــفى امللــك فهــد‬\n     ‫للحــرس الوطنــي وعنــد انتقــال فرقــة األدلــة اجلنائيــة للموقــع وجــدت آثــار‬\n     ‫دمــاء وعــدد اربعــة مقذوفــات فارغــة ملســدس مــن نــوع ربــع وعــدد طلقتني‬\n     ‫فارغــة لســاح مــن نــوع رشــاش ‪.‬وبضبــط إفــادة املجنــى عليــه ‪..... /‬أفــاد‬\n     ‫بوجــود خــاف مــع أخيــه املتهــم منــذ فتــرة طويلــه ممــا دعــاه إلــى منــع‬\n     ‫اخــاه مــن دخــول منزلــه فقــام املتهــم باالتصــال عليه مرات عــدة وتهديده‬\n     ‫بقولــه لعبــارة( واهلل الفــري بطنــك والفقــع راســك ) وانقطــع عنــه منــذ‬\n     ‫ســنوات ولــم يشــاهده ويف مســاء يــوم ‪1431/9/29‬ه ـ وأثنــاء توجهــه مــن‬\n     ‫املنــزل إلــى املســجد إلداء صــاة العشــاء تفاجــأ بطلقــة فــوق راســه ومــن‬\n     ‫ثــم طلقــة أخــرى أصابتــه يف الفخــذ وســقط علــى األرض ثــم توالــت‬\n     ‫الطلقــات وهــو يتحاشــاها بيــده فأصابتــه عــدة طلقــات وشــاهد ســيارة‬\n     ‫صغيــرة ال يعــرف نوعهــا ولونهــا ســماوي ولــم يشــاهد مــن بداخلهــا‬\n     ‫ولكنــه ســمع مــن النســاء حولــه أن الســيارة بهــا اثنــان وصــدر بحقــه‬\n     ‫التقريــر الطبــي رقــم (‪ ).....‬وتاريــخ ‪1431/9/29‬ه ـ الصــادر مــن الشــئون‬\n     ‫الصحيــة باحلــرس الوطنــي املتضمــن إصابتــه بعشــرة جــروح قطعيــة اثنــان‬\n     ‫منهــا يف العضــد األميــن وأثنــان يف الصــدر مــن االمــام واخللــف وأثنــان يف‬\n\n\n‫‪23‬‬\n\f‫الفخــذ مــن األمــام واخللــف وإصابتــه بكســر يف منتصــف عظمــة الفخــذ‬\n‫وجــروح متعــددة يف األطــراف العلويــة والطــرف األميــن الســفلي واليــد‬\n‫اليســرى والصــدر ومــدة الشــفاء أكثــر مــن خمســة عشــريوما ‪.‬ويف متــام‬\n‫الســاعة السادســة وعشــرون دقيقــه مــن مســاء يــوم اخلميــس‬\n‫‪1431/9/30‬ه ـ قبــض علــى املتهــم مــن قبــل دوريــات حــرس احلــدود‬\n‫مبنطقــة احلــدود الشــمالية مبوقــع خفــي عــن األنظــار وبقيادتــه ســيارة‬\n‫مــن نــوع ‪ ....‬لونهــا فضــي وبتفتيــش الســيارة وجــد بهــا مســدس بــدون‬\n‫ترخيــص ملفــوف بعقــد اســتئجار الســيارة ومخبــأ أســفل مقــود الســيارة‬\n‫ومخــزن ســاح مســدس فــارغ وجــواز سفر‪.‬وبســماع شــهادة ‪..... /‬أفــاد‬\n‫أن عمــه املتهــم اتصــل عليــه يف مغــرب يــوم احلادثــة وســأله عــن منــزل عمــه‬\n‫املجنــى عليــه لكونــه انتقــل مــن بيتــه حديثــا وعندمــا ســأله عــن ســبب‬\n‫ذلــك قــال إن هنــاك رجــا يســأل عنــه وعنــد ســؤاله عــن هــذا الرجــل لــم‬\n‫يجبــه ثــم اتصــل عليــه بعــد ثلــث ســاعة وســأله هــل امــام منزلهــم ســيارة‬\n‫‪ ....‬وهــل لــون منزلهــم احمــر فقــال لــه ال ادري النــه يعلــم أنــه صاحــب‬\n‫ســوابق فقــال هــل هــم موجوديــن فأجابــه بأنــه ال يعلــم واغلــق اجلــوال ثــم‬\n‫ســمع بحادثــة اإلطــاق يف الســاعة الواحــدة ليــا ‪ .‬ومبضاهــاة األظــرف‬\n‫الفارغــة املضبوطــة يف مســرح اجلرميــة مــع الســاح املســدس املضبــوط‬\n‫مــع املتهــم تبــن مطابقــة ظرفــن فارغــن للســاح‪ .‬وبإســتجواب املتهــم ‪/‬‬\n‫أفــاد بعــدم وجــود خــاف مــع اخيــه املجنــى عليــه وأنــه لــم يشــاهده منــذ‬\n‫ســنتني وأنــه يف وقــت اإلطــاق كان يف القصيــم لكونــه خــرج مــن‬\n‫مدينــة الريــاض عصــر ذلــك اليــوم وانــه ذهــب بالقــرب مــن احلــدود‬\n‫العراقيــة لكــون هنــاك رجــل يريــد منــه مبلــغ مــن املــال ونفــى قيامــه‬\n‫بإطــاق النــار علــى أخيــه املجنــى عليــه وانــه ال يعلــم عــن احلادثــة شــيئا‬\n\n\n                                                                                      ‫‪24‬‬\n\f     ‫ونفــى عائديــه الســاح الــذي عثــر بســيارته لــه ‪.‬ومبواجهتــه بشــهادة ‪..... /‬‬\n     ‫أفــاد أنــه ال يعلــم هــل اتصــل عليــه يف ذلــك الوقــت ام ال ولكنــه لــم‬\n     ‫يتذكــر أنــه ســأله عــن منــزل أخيــه املجنــى عليــه لكونــه يعرفــه مــن‬\n     ‫قبــل وبالبحــث عــن ســوابقه ‪ /‬عثــر لــه علــى ســابقتني االولــى ســرقة‬\n     ‫حيوانــات واالخــرى مخالفــة لنظــام حــرس احلــدود ‪.‬ملــا أشــير إليــه أقــرر‬\n     ‫توجيــه اإل تهــام ل ـ ‪.....‬بالشــروع يف قتــل اخيــه املجنــى عليــه‪..... /‬وذلــك‬\n     ‫بإطــاق النــار عليــه عــدة طلقــات ممــا أدى إلــى إصابتــه باإلصابــات‬\n     ‫املوصوفــة بالتقريــر الطبــي املرفــق وحيازتــه للســاح املســدس املضبــوط‬\n     ‫الــذي يحمــل الرقــم‪ ) .....‬والســاح الرشــاش بــدون ترخيــص اجلهــة‬\n     ‫املختصــة وإخفائه‪.‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬ماجــاء يف أقــوال‬\n     ‫املجنــى عليــه املدونــة علــى الصفحــة رقم(‪)9-8-7‬مــن دفتــر التحقيــق‬\n     ‫رقم(‪-2)6‬مــا جــاء يف شــهادة الشــاهد املدونــة علــى الصفحــة رقــم (‬\n     ‫‪ )11-10‬مــن دفتــر التحقيــق رقــم (‪-3)6‬ماجــاء يف محضــر االنتقــال‬\n     ‫واملعاينــة املــدون علــى الصفحــة رقــم (‪ . )1‬مــن دفتــر التحقيــق رقــم‬\n     ‫(‪-4)2‬ماجــاء يف محضــر القبــض املتهــم لفــة رقــم (‪-5. )19‬ماجــاء يف‬\n     ‫التقريــر الطبــي املرفــق رقــم (‪-6 )14‬ماجــاء يف تقريــر األدلــة احلنائيــة‬\n     ‫لفــه رقــم(‪ )52‬وحيــث أن مــا أقــدم عليــه املذكــور فعــل معاقــب عليــه‬\n     ‫شــرع ًا ونظامــا ‪ .‬ممــا يتعــن معــه إحالتــه إلــى احملكمــة اجلزئيــة اســتنادا‬\n     ‫لنــص املــادة (‪ )126‬مــن نظــام اإلجــراءات اجلزائيــة للحكــم عليــه بعقوبــة‬\n     ‫تعزيريــة لقــاء ماأســند إليــه‪ ,‬وإحالــة مايتعلــق بحيــازة الســاح بــدون‬\n     ‫ترخيــص للمحكمــة اإلداريــة وفقــا للمادتــن(‪ )50-40‬مــن نظــام‬\n     ‫األســلحة والذخائــر الصــادر باملرســوم امللكــي رقــم م‪ 45/‬وتاريــخ‬\n     ‫‪1426/7/25‬ه ـ علمــا بــأن احلــق اخلاص مازال قائمــا هذه دعواي وبتالوة‬\n\n\n‫‪25‬‬\n\f‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف دعــوى‬\n‫املدعــي العــام كلــه غيــر صحيــح فأنــا لــم أطلــق النــار علــى أخــي ‪.....‬‬\n‫مطلقــا وأنــا ال يوجــد بينــي وبــن أخــي ‪.....‬أي عــداوة مطلقـ ًا وأنــا ال يوجــد‬\n‫لــدي أي ســاح وأنــا وقــت احلادثــة كنــت خــارج مدينــة الريــاض هــذا‬\n‫أجــاب ورفعــت اجللســة النتهــاء وقــت الــدوام الرســمي ولطلــب صاحــب‬\n‫احلــق اخلــاص وذلــك يــوم الثالثــاء املوافــق ‪1432/3/19‬ه ـ الســاعة احلادية‬\n‫عشــر واهلل املوفــق ‪ .‬ويف يــوم الثالثــاء ‪1432/3/19‬ه ـ أفتتحــت اجللســة‬\n‫الثانيــة الســاعة الثانيــة عشــر وفيهــا حضــر املدعي العــام وحضر حلضوره‬\n‫املدعــى عليــه ولــم يحضــر املدعــي باحلــق اخلــاص لــذا طلبــت مــن املدعــي‬\n‫العــام البينــة فطلــب مهلــة إلحضارهــا ورفعــت اجللســة لذلــك واهلل املوفــق‬\n‫‪ .‬ويف يــوم االثنــن املوافــق ‪1432/4/9‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 11‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد طلبــت مــن املدعــي‬\n‫العــام بينتــه فأجــاب بأنــه ولــم يتمكــن مــن إحضارهــا يف هــذا اليــوم لــذا‬\n‫فقــد رفعــت اجللســة إلحضارهــا وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫ويف يــوم الثالثــاء ‪1432/7/26‬ه ـ أفتتحــت اجللســة الســاعة العاشــرة‬\n‫والنصــف وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه‬\n‫الســجني وبســؤال املدعــي العــام عــن بينتــه أجــاب بقولــه أحضــرت أحــد‬\n‫الشــهود وأطلــب ســماع مــا لديــه حيــث حضــر ‪.....‬ســعودي بالبطاقــة رقــم‬\n‫‪.....‬مــن مواليــد ‪1403/12/21‬ه ـ يعمــل مبهنــة عســكري يف القــوات‬\n‫البريــة وبســؤاله أجــاب بقولــه أشــهد بــاهلل إن املدعــى عليــه عمــي أخ‬\n‫لوالــدي مــن األب وقــد اتصــل بــي يف يــوم حادثــة أطــاق النــار بعــد املغــرب‬\n‫يف شــهر رمضــان املاضــي وطلــب وصــف منــزل عمــي املجنــي عليــه ‪....‬‬\n‫فقلــت لــه مــاذا تريــد بالوصــف فقــال لــي يريــده رجــال ثــم وصــف لــي‬\n\n\n                                                                                        ‫‪26‬‬\n\f     ‫طريــق البيــت فقلــت لــه أنــت اآلن تعــرف طريــق بيتــه فلمــاذا تتصــل بــي‬\n     ‫فقــام بإنهــاء االتصــال ثــم اتصــل بــي بعــد خمــس دقائــق فقــال لــي أنــا اآلن‬\n     ‫عنــد البيــت ولونــه بيــج وعنــده ‪ .....‬بيضــاء ثــم قــال لــي هــل اجلماعــة‬\n     ‫ا اتصلــت بــي‬   ‫موجوديــن أم ال فقلــت ال أدري ويف الســاعة الواحــدة لي ـ ً‬\n     ‫الشــرطة وأخبرتنــي بالواقعــة وأن آخــر اتصــال يف جــوال املدعــى عليــه‬\n     ‫كان لــي وحضــرت للشــرطة وأدليــت مبثــل هــذه الشــهادة واهلل علــى مــا‬\n     ‫أقــول شــهيد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه أجــاب بقولــه‬\n     ‫ال صحــة ملــا جــاء يف شــهادة الشــاهد فأنــا لــم اتصــل بالشــاهد ألخــذ‬\n     ‫وصــف منــزل املجنــي عليــه وأنــا أعــرف وصــف منــزل املجنــي عليــه حيــث‬\n     ‫ســبق وأن ذهبــت أنــا والشــاهد وأخــي ‪ ...‬ملنــزل أخــي ‪ ....‬ولــم جنــده فأنــا‬\n     ‫ال أحتــاج ملعرفــة وصــف منزلــه أمــا مــا يتعلــق باالتصــال بــه فأنــا أتصــل‬\n     ‫علــى الشــاهد باســتمرار لكونــه مــن أقاربــي والشــاهد أبــن أخــي وليــس‬\n     ‫بينــي وبينــه أي عــداوة مســبقه إال إن كان يضمــر لــي احلقــد والبغضــاء‬\n     ‫فهــذا ال أعلمــه هكــذا أجــاب ثــم حضــر املدعــي باحلــق اخلــاص‪.....‬‬\n     ‫ســعودي بالبطاقــة رقــم ‪.....‬وبســؤاله أجــاب بقولــه إننــي أدعــي علــى‬\n     ‫املدعــى عليــه حيــث قــام بإطــاق عــدد عشــر طلقــات ناريــه مــن مســدس‬\n     ‫أصابتنــي يف الركبــه ويف الظهــر ويف الصــدر ويف اليــد اليمنــى ويف اليــد‬\n     ‫اليســرى ومواضــع أخــرى وقــد نتــج عــن ذلــك إصابتــي بشــلل يف رجلــي‬\n     ‫اليمنــى وبعــض اإلصابــات وقــد شــاهدته بنفســي أثنــاء إطالقــه النــار‬\n     ‫علــي وأطلــب تعزيــره لقــاء ذلــك تعزيــرا بليغــا هــذه دعــواي وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف دعــوى املدعــي‬\n     ‫باحلــق اخلــاص فأنــا لــم أطلــق النــار عليــه مطلقــا هكــذا أجــاب وبعــرض‬\n     ‫ذلــك علــى املدعــي باحلــق اخلــاص أجــاب بقولــه الصحيــح مــا جــاء يف‬\n\n\n‫‪27‬‬\n\f‫دعــواي واملدعــى عليــه ســبق أن هددنــي ولــدي البينــة علــى ذلــك ثــم‬\n‫أحضــر ‪.....‬ســعودي بالبطاقــة رقــم ‪.....‬مــن مواليــد ‪1404/4/15‬هـ ويعمل‬\n‫عســكري يف وزارة الدفــاع وبســؤاله أجــاب بقولــه إن املدعــي باحلــق‬\n‫اخلــاص واملدعــى عليــه همــا أعمامــي وأشــهد بــاهلل إنــي ســمعت بــأن‬\n‫املدعــى عليــه هــدد عمــي ‪.....‬فذهبــت إليــه فقــال لــي إنــي ال أريــده وليــس‬\n‫بينــي وبينــه أي عــداوه إال إننــي كنــت ســكرانا فاتصلــت وهــددت أخــي‬\n‫‪.....‬واهلل علــى مــا ٌأقــول شــهيد وبعــرض الشــاهد وشــهادته علــى املدعــى‬\n‫عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف شــهادة الشــاهد والشــاهد أبــن‬\n‫أخــي وليــس بينــي وبينــه أي عــداوة هكــذا أجــاب فســألت املدعــي باحلــق‬\n‫اخلــاص ألديــك زيــادة بينــه فأجــاب بقولــه ال بينــة لــدي ســوى مــا أحضــرت‬\n‫هكــذا أجــاب ثــم ســألت املدعــي العــام هــل لديــه زيــادة بينــه بخصــوص‬\n‫الدعــوى العامــة فأجــاب بقولــه أطلــب الرجــوع للمعاملــة واالطــاع علــى‬\n‫مــا فيهــا مــن أدلــة وقرائــن هكــذا أجــاب ورفعــت اجللســة لتزكيــة‬\n‫الشــاهدين ‪ .‬ويف يــوم الثالثــاء ‪1432/8/4‬ه ـ افتتحــت اجللســة اخلامســة‬\n‫الســاعة الواحــدة ظهــرا وقــد حضــر لتزكيــة الشــاهدين ‪..........‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪..........‬و‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n‫وبســؤالهما أجابــا بقولهمــا نشــهد بــاهلل إن الشــاهدين ‪ ..........‬و‪..........‬‬\n‫ثقتــان ذوا عــدل مرضيــا الشــهادة لنــا وعلينــا هكــذا شــهدا ورفعــت‬\n‫اجللســة إلــى يــوم الســبت ‪1432/8/8‬ه ـ واهلل املوفــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد ‪ .‬ويف يــوم الســبت ‪1432/8/8‬ه ـ أفتتحــت اجللســة‬\n‫السادســة الســاعة احلاديــة عشــرة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه وقــد حضــر عــن املدعــي باحلــق اخلــاص ‪..........‬‬\n‫ســعودي بالبطاقــة رقــم ‪..........‬بالوكالــة عــن أبيــه مبوجــب الوكالــة‬\n\n\n                                                                                      ‫‪28‬‬\n\f     ‫الصــادرة مــن كتابــة عــدل الثانيــة يف شــرق الريــاض برقــم ‪..........‬يف‬\n     ‫‪1432/1/5‬ه ـ اجللــد ‪..........‬والتــي تخولــه حــق املرافعــة واملدافعــة‬\n     ‫والقناعــة واالعتــراض وبالرجــوع للمعاملــة وجــد فيهــا لفــة رقــم ‪51-50‬‬\n     ‫تقريــر األدلــة اجلنائيــة حيــال األظــرف الفارغــة برقــم ‪..........‬ونــوع الســاح‬\n     ‫‪ ....‬الصنــع عيــار ‪ ....‬ملــم رقــم ‪..........‬مــع مخــزن ‪4 +‬ظــروف فارغــه عيــار‬\n     ‫‪ ....‬ملــم ‪2+‬ظــرف فــارغ والنتيجــة أن الظــروف الفارغــة والتــي عددهــا‬\n     ‫اربعــة ظــروف مطلقــه مــن املســدس املذكــور وهــو نــوع ‪ ....‬عيــار ‪.....‬أمــا‬\n     ‫الظرفــان الفارغــان املشــار عنهمــا عيــار‪.... ....‬ملــم مطلقــه مــن ســاح‬\n     ‫نــاري واحــد وتطلــق عــادة مــن األســلحة ذات العيــار نفســه ا ه ـ ‪ .‬وكــذا‬\n     ‫وجــد فيهــا خطــاب مديــر شــرطة منطقــة احلــدود الشــمالية رقــم ‪..........‬يف‬\n     ‫‪1431/10/3‬ه ـ املوجــه ملديــر شــرطة منطقــة الريــاض واملتضمن القبض‬\n     ‫علــى املدعــى عليــه وبرفقتــه ســيارة مســتأجرة ووجــد يف أســفل مقــود‬\n     ‫الســيارة وملفــوف بورقــة عقــد الســيارة مســدس ‪ .....‬الصنــع يحمــل الرقــم‬\n     ‫‪..........‬كمــا وجــد يف دفتــر التحقيــق لفــة رقــم ‪ 2‬محضــر االنتقــال‬\n     ‫واملعاينــه واملتضمــن العثــور علــى عــدد أربــع مقذوفــات مســدس ربــع‬\n     ‫وطلقــات رشــاش عــدد اثنــن فــوارغ ا ه ـ ‪ .‬وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف خطــاب مديــر شــرطة منطقــة‬\n     ‫احلدود الشــمالية من العثور معي على ســاح مســدس ‪ .....‬وهذا الســاح‬\n     ‫ال يعــود لــي وال يخصنــي هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعوى‬\n     ‫واإلجابــة وحيــث أنكــر املدعــى عليــه دعــوى املدعــي العــام واملدعــي‬\n     ‫باحلــق اخلــاص وحيــث إن مــا جــاء يف شــهادة الشــاهدين املعدلــن طبــق‬\n     ‫األصــول الشــرعية ومــا جــاء يف محضــر االنتقــال مــن العثــور علــى‬\n     ‫األظــرف الفارغــة وكــذا مــا جــاء يف خطــاب مديــر شــرطة احلــدود‬\n\n\n‫‪29‬‬\n\f‫الشــمالية مــن العثــور علــى املســدس الــذي انطلقــت منــه أربعــة مقذوفــا‬\n‫حســب قــرار األدلــة اجلنائيــة تــورث الشــبهة القويــة جتــاه املدعــى عليــه يف‬\n‫احلــق العــام وحيــث إن هــذه األمــور ال يثبــت بهــا احلــق اخلــاص فعليــه فقــد‬\n‫تقــرر مــا يلــي أوال ‪ :‬رددت دعــوى املدعــي باحلــق اخلــاص لعــدم كفايــة‬\n‫األدلــة يف إثباتــه ‪ .‬ثانيـ ًا ‪ :‬توجــه الشــبهة القويــة علــى قيــام املدعــى عليــه‬\n‫بإطــاق النــار علــى املجنــي عليــه وقــررت تعزيــره لقــاء ذلــك وذلــك‬\n‫بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده ثالثمائــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى‬\n‫عشــرة أيــام وبعرضــه علــى املدعــي العــام قــرر االعتــراض مكتفي ـ ًا‬\n‫بالئحــة الدعــوى أمــا املدعــي باحلــق اخلــاص فقــد قــرر عــدم القناعــة‬\n‫ويطلــب التمييــز بالئحــة أعتراضيــة وكــذا قــرر املدعــى عليــه عــدم‬\n‫القناعــة ويطلــب التمييــز بالئحــة اعتراضيــة وأفهمــا بــأن عليهمــا‬\n‫املراجعــة يــوم الســبت ‪1432/8/15‬ه ـ الســتالم نســخة مــن احلكــم‬\n‫لالعتــراض عليــه ملــدة ثالثــن يوم ـ ًا وإال ســقط حقهمــا يف االعتــراض‬\n‫ففهمــا ذلــك واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬ويف يــوم‬\n‫الثالثــاء ‪1433/3/8‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة مــن‬\n‫محكمة االستئناف وبرفقها القرار رقم ‪3337778‬يف ‪1433/1/22‬هـ‬\n‫ونص احلاجة منه وبدراســة القرار وصورة ضبطه والالئحة االعتراضية‬\n‫وأوراق املعاملــة لوحــظ أن رد دعــوى املدعــي باحلــق اخلــاص علــى هــذه‬\n‫الصفــة محــل نظــر واملتعــن تقريــر عقوبــة تعزيريــة للحــق اخلــاص ملــا حلــق‬\n‫باملدعــى عليــه مــن شــبهة قويــة فيمــا نســب لــه أو زيــادة العقوبــة الصــادرة‬\n‫يف احلــق العــام وإيضــاح مــا هــو حــق عــام ومــا هــو حــق خــاص منهمــا واهلل‬\n‫املوفــق ‪.‬أه ـ ‪ .‬فعليــه أجيــب أصحــاب الفضيلــة بأنــه يف هــذه اجللســة وفيهــا‬\n\n\n                                                                                          ‫‪30‬‬\n\f     ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه الســجني كمــا‬\n     ‫حضــر وكيــل املدعــي باحلــق اخلــاص ‪..........‬وجــرى ســؤال املدعــي باحلــق‬\n     ‫اخلــاص وكالــة عــن موكلــه فأجــاب بأنــه يتعالــج خــارج اململكــة ولــن‬\n     ‫يحضــر إال بعــد شــهرين هكــذا أجــاب فعليــه وألن مــا جــاء يف حيثيــات‬\n     ‫احلكــم يقــوي جانــب املدعــي باحلــق اخلــاص واليمــن تشــرع يف جانــب‬\n     ‫أقــوى املتداعــن وحيــث إن املدعــي باحلــق اخلــاص يف خــارج اململكــة ممــا‬\n     ‫يتعــذر معــه حضــوره وأداء اليمــن فعليــه وألن احلــق اخلــاص ال يثبــت‬\n     ‫بالشــبهة فإنــي الزلــت علــى مــا حكمــت بــه مــن رد دعــوى املدعــي باحلــق‬\n     ‫اخلــاص فأمــرت بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة‬\n     ‫االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬ويف يــوم الثالثــاء‬\n     ‫‪1433/6/17‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n     ‫حلضــوره املدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫وبرفقها القرار رقم يف ‪1433/3/26‬هـ ونص احلاجة منه « وباالطالع‬\n     ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n     ‫علــى قرارنــا رقــم ‪/3337778‬ج‪/3‬ب وتاريــخ ‪1433/1/22‬ه ـ لوحــظ أن‬\n     ‫مــا اجــاب بــه فضيلتــه غيــر مقنــع إلعــادة النظــر وإجــراء مــا يلــزم علــى‬\n     ‫ضــوء قرارنــا املشــار إليــه أعــاه» أ‪.‬ه ـ فعليــه أجيــب أصحــاب الفضيلــة‬\n     ‫أنــه بتأمــل القضيــة وبعــد االســتخارة واستشــارة بعض أصحــاب الفضيلة‬\n     ‫القضــاة فقــد رجعــت عــن حكمــي الســابق يف الفقرتــن أو ًال وثاني ـ ًا‬\n     ‫وحيث إن ما جاء يف شــهادة الشــاهدين املعدليه طبق األصول الشــرعية‬\n     ‫وكــذا مــا جــاء يف محضــر االنتقــال مــن العثــور علــى األظــرف الفارعــة‬\n     ‫وخطــاب مديــر شــرطة احلــدود الشــمالية مــن العثــور علــى املســدس الــذي‬\n\n\n‫‪31‬‬\n\f‫انطلقــت منــه املقذوفــات يف الســيارة التــي يســتعملها املدعــى عليــه‬\n‫ومطابقــة ظرفــن فارغــن للســاح وحيــث إن هذيــن األمريــن كافيــان‬\n‫يف إثبــات دعــوى املدعــي اخلــاص والعــام فعليــه فقــد ثبــت لــدي قيــام‬\n‫املدعــى عليــه بإطــاق النــار علــى املدعــي باحلــق اخلــاص عــدة طلقــات‬\n‫ممــا أدى إلــى إصابتــه باإلصابــات املوصوفــة بالتقاريــر الطبيــة املرفقــة‬\n‫باملعاملــة وقــررت مايلــي ‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ثــاث ســنوات‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون‬\n‫جلــدة بينهمــا عشــرة وذلــك للحــق اخلــاص ‪ .‬ثانياً‪:‬ســجن املدعــى عليــه‬\n‫ســنتان مــن تاريــخ إيقافــه وجلــده مائتــي جلــده مفرقــه علــى أربــع دفعــات‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وبــن هــذا‬\n‫اجللــد واجللــد الــذي يف أو ًال عشــرة أيــام وبجميــع ذلــك حكمــت ‪ .‬وبعرضه‬\n‫علــى املدعــى العــام قــرر بأنــه ال زال معترضـ ًا أمــا املدعــى عليــه فقــد قــرر‬\n‫عــدم القناعــة ويرغــب رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة‬\n‫اعتراضيــة أمــا املدعــى باحلــق اخلــاص فلــم يحضــر وســيتم عــرض احلكــم‬\n‫عليــه حــال حضــوره واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه أجمعــن ‪ .‬ويف يــوم الســبت ‪1433/7/12‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضر‪..........‬ســعودي اجلنســية بالهويــة رقــم (‪)..........‬‬\n‫بالوكالــة عــن والــده مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫الثانيــة بشــرق الريــاض برقــم ‪..........‬يف ‪1432/1/5‬ه ـ اجللــد ‪..........‬والتي‬\n‫تخولــه حــق اإلقــرار واملرافعــة واملدافعــة وطلــب اســتئناف األحــكام‬\n‫ومتييزهــا والقناعــة بهــا واالعتــراض عليهــا وقــرر قائــا إن موكلــي‬\n‫والــدي غيــر مقتنــع باحلكــم األخيــر ونطلــب رفــع املعاملــة حملكمــة‬\n‫االســتئناف مكتفــن بالئحتنــا الســابقة هكــذا قــرر فعليــه فقــد أمــرت‬\n\n\n                                                                                         ‫‪32‬‬\n\f     ‫بضبطــه وإحلــاق ذلــك يف القــرار ورفــع املعاملــة حملكمــة االســتئناف‬\n     ‫لتدقيــق اإلجــراء حســب املتبــع واهلل املوفــق ‪ .‬احلمــد هلل وحــده وبعــد فقــد‬\n     ‫اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة لتمييــز القضايــا اجلزائيــة‬\n     ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n     ‫احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1433/12/1‬ه ـ املرفــق‬\n     ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.......... /‬‬\n     ‫املســجل برقــم وتاريــخ ‪1433/8/12‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n     ‫ضــد ‪.......... /‬يف قضيــة إطــاق نــار علــى النحو املوضــح بالقرار املتضمن‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه و بدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n     ‫وأحلقــه بالقــرار وصــورة ضبطــه وبنــاء علــى القــرار رقــم ‪331527704 /‬‬\n     ‫وتاريــخ ‪ 1433/3/26‬ه ـ لــم يظهــر لألكثريــة مــا يوجــب نقــض احلكــم‬\n     ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫اله وصحبه وسلم‪.‬‬\n\n\n\n\n‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":20,"source_page_end":33,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d87cae77e69dc68a971d5a50118af35ad1190a165866cdd142ac0c347e5a0173","normalized_text_hash":"0bde794bd790f136c76de40471a52a0410444067f6c36239eb33db4f41f46031","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p20-32203464"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c17ee6c8-91f0-5ac2-b635-718ec5504e89","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -إقامة حظيرة أغنام بجوار سكن املدعية -املطالبة بإزالة احلظيرة -إقرار املدعى عليه -ثبوت حتقق األذى -اإللزام بإزالة احلظيرة .","document_number":"34167752","case_number":"34100652","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"دعوى منع ضرر -إقامة حظيرة أغنام بجوار سكن املدعية -املطالبة بإزالة احلظيرة -إقرار املدعى عليه -ثبوت حتقق األذى -اإللزام بإزالة احلظيرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/22 :‬هـ‬\n                      ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34167752 :‬‬\n                          ‫َر ْق ُم الدعوى‪34100652 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34331237‬تاريخه‪1434/10/15 :‬هـ‬\n\n\n      ‫دعــوى منــع ضــرر ‪ -‬إقامــة حظيــرة أغنــام بجــوار ســكن املدعيــة‪ -‬املطالبة‬\n      ‫بإزالــة احلظيــرة‪ -‬إقــرار املدعــى عليــه‪ -‬ثبــوت حتقــق األذى‪ -‬اإللــزام‬\n                                                                ‫بإزالــة احلظيــرة ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار)‪.‬‬\n                                          ‫‪ -2‬القاعدة الشرعية‪« :‬الضرر يزال»‪.‬‬\n                                                             ‫‪ -3‬ال عذر ملقر ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أقــام زريبــة أغنــام بجــوار منــزل‬\n      ‫موكلتــه وقــد تســبب ذلــك باألذيــة لهــا مــن روائــح الغنــم وأصواتهــا‪،‬‬\n      ‫لــذا طلــب إزالــة هــذه الزريبــة‪ -‬أقــر املدعــي بأنــه شــريك يف الزريبــة وأن‬\n      ‫إقامــة الزريبــة جــاء الحق ـ ًا علــى ســكن املدعيــة‪ -‬ثبــوت حتقــق وقــوع‬\n      ‫األذيــة للمدعيــة مــن زريبــة احليوانــات التــي أقامهــا املدعــى عليــه ‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليــه بإزالــة حظيــرة احليوانــات التــي بجــوار‬\n      ‫منــزل املدعيــة وإبعادهــا مســافة كافيــة ال تقــل عــن ثالثمائــة متــر‪ -‬قنــع‬\n      ‫وكيــل املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة‬\n                                                  ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n‫‪353‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 34100652‬وتاريــخ ‪ 1434/03/01‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34524070‬وتاريــخ ‪ 1434/03/01‬ه ـ ففــي يــوم‬\n‫االثنــن املوافق‪1434/03/16‬ه ـ افتتحــت اجللســة الســاعة ‪08 :30‬‬\n‫وفيهــا حضــر وكيــل املدعيــة ‪ .....‬وكالــة بالســجل املدنــي رقــم ‪.....‬‬\n‫وكيــا عــن ‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل جنــران‬\n‫برقــم ‪ 370503013147‬يف ‪1430/03/18‬ه ـ ووكالــة احلاضــر تخولــه‬\n‫املرافعــة واملدافعــة وإقامــة الدعــاوى ضــد الغيــر وحضــور اجللســات‬\n‫وطلــب وتقــدمي البينــات وســماع الشــهود وطلــب حتليــف اليمــن وســماعها‬\n‫وردهــا وطلــب اســتئناف األحــكام والقناعــة بهــا واالعتــراض عليهــا‬\n‫واالســتالم والتوقيــع كمــا حضــر حلضــوره املدعــى عليــه ‪ ..... /‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ) .....‬فادعــى األول قائ ـاً‪ :‬أن‬\n‫هــذا احلاضــر قــد أقــام زريبــة أغنــام بجــوار منــزل موكلتــي وقــد تســبب‬\n‫ذلــك باألذيــة لهــا مــن روائــح الغنــم وأصواتهــا أطلــب إزالــة هــذه الزريبــة‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه أجــاب‬\n‫قائ ـاً‪ :‬مــا جــاء يف الدعــوى صحيــح ولكــن هــذه الغنــم ليســت لــي‬\n‫وإمنــا لوالدتــي وأخواتــي وأنــا القائــم بشــؤونهم وأنــا وكيــل عــن والدتــي‬\n‫واألرض التــي فيهــا زريبــة الغنــم هــي لنــا مــن اإلرث وأمــا املدعيــة فهــي‬\n‫قــد اشــترت املوقــع ويوجــد لــدى املدعيــة أغنــام يف موقــع آخــر مــن احلــي‬\n‫هكــذا أجــاب وبســؤال املدعــي وكالــة هــل كان ســكن موكلتــه‬\n\n                                                                                       ‫‪354‬‬\n\f      ‫قبــل وضــع الغنــم أم بعــده فقــال بــل قبلــه هكــذا قــال ووافــق علــى ذلــك‬\n      ‫املدعــى عليــه وبنــاء علــى مــا ســلف ضبطــه فقــد قــررت رفــع اجللســة ليــوم‬\n      ‫األحــد املوافــق ‪1434/03/22‬ه ـ كمــا أمــرت املدعــى عليــه أن يحضــر‬\n      ‫وكالتــه عــن والدتــه فاســتعد بذلــك ورفعــت اجللســة ويف يــوم األحــد‬\n      ‫املوافــق ‪1434/03/22‬ه ـ الســاعة ‪08:00‬وبســؤال املدعــى عليــه عــن‬\n      ‫الوكالــة التــي اســتعد بإحضارهــا يف اجللســة املاضيــة أجــاب بقولــه‪ :‬لــم‬\n      ‫أحضرهــا‪ .‬وبســؤاله هــل هــو شــريك يف األرض التــي وضعــت فيهــا زريبــة‬\n      ‫احليوانــات وهــل هــو مــن وضعهــا أجــاب بقولــه‪ :‬نعــم‪ .‬وبنــاء علــى مــا ســلف‬\n      ‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بوضعــه لزريبــة احليوانــات‬\n      ‫بجــوار منــزل املدعيــة أصالــة وال عــذر ملقــر وملــا هــو معلــوم مــا يصــدر عــن‬\n      ‫زرائــب احليوانــات مــن أذى فقــد ثبــت لــدي حتقــق وقــوع األذيــة للمدعيــة‬\n      ‫أصالــة مــن زريبــة احليوانــات التــي أقامهــا املدعــى عليــه ولقولــه عليــه‬\n      ‫الصــاة والســام‪ « :‬ال ضــرر وال ضــرار « وللقاعــدة الشــرعية «الضــرر‬\n      ‫يــزال» فقــد ألزمــت املدعــى عليــه بإزالــة حظيــرة احليوانــات التــي بجــوار‬\n      ‫منــزل املدعيــة أصالــة وإبعادهــا مســافة كافيــة ال تقــل عــن ثالثمائــة‬\n      ‫متــر وبــه حكمــت وبعــرض احلكــم علــى املدعــي وكالــة قــرر القناعــة‬\n      ‫كمــا قــرر املدعــى عليــه اعتراضــه بالئحــة فجــرى تســليمه نســخة مــن‬\n      ‫ـداء‬\n      ‫احلكــم وأفهمتــه بــأن عليــه تقــدمي اعتراضــه خــال ثالثــن يومـ ًا ابتـ ً‬\n      ‫مــن الغــد وإال ســقط حقــه يف طلــب التمييــز واكتســب احلكــم القطعيــة‬\n      ‫وختمــت اجللســة بذلــك وكان ختامهــا الســاعة ‪ 08 : 30‬وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n                                                                    ‫يف ‪1434/3/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n\n\n‫‪355‬‬\n\f‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪ 341171874‬يف‬\n‫‪1434/08/06‬ه ـ واملرفــق بهــا قــرار املالحظــة الصــادر مــن الدائــرة‬\n‫األولــى برقــم ‪ 34276941‬يف ‪1434/07/23‬ه ـ واملتضمــن مــا نــص‬\n‫احلاجــة منــه‪(( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة تقــرر إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‪ :‬أوال‪ :‬حكــم‬\n‫فضيلتــه بوجــود الضــرر مــن غيــر أن يتحقــق مــن ذلــك مــن جهــة مختصــة‬\n‫والبــد مــن ذلــك‪ .‬ثانيــا‪ :‬ذكــر املعتــرض يف الئحتــه أمــور ًا تلفــت النظــر‬\n‫منهــا أن فضيلتــه أصــدر حكمــن متناقضــن يف القضيــة نفســها وأنــه‬\n‫أرفــق صــورة مــن احلكــم اآلخــر إال أننــا لــم جنــده ملالحظــة ذلــك‪ .‬ثالثـاً‪:‬‬\n‫ذكــر املعتــرض أن املوقــع الــذي بــه زريبــة الغنــم يف مخطــط زراعــي‬\n‫وفضيلتــه خيــر مــن يعلــم الفــرق بــن املخطــط الزراعــي واملخطــط‬\n‫الســكني للتأكــد مــن ذلــك ومراجعــة حكمــه علــى ضــوء ذلــك‪ .‬واهلل‬\n‫املوفــق)) واملذيــل بتوقيــع أصحــاب الفضيلــة قضــاة الدائــرة فضيلــة‬\n‫الشــيخ ‪ .....‬وفضيلــة الشــيخ‪ .....‬وفضيلــة رئيــس الدائــرة ‪ .....‬اهــ‪ .‬فإجابــة‬\n‫علــى مــا ذكــره مشــايخي أصحــاب الفضيلــة أجــزل اهلل مثوبتهم ونفعني‬\n‫بتوجيهاتهــم وأدام توفيقهــم أجيــب مســتعين ًا بــاهلل ســائله ســبحانه‬\n‫التوفيــق والســداد‪ :‬فيمــا يخــص امللحوظــة األولــى فــإن الضــرر مــن‬\n‫مالحقــة أحــواش األغنــام للمســاكن معلــوم حس ـ ًا ممــا لهــا مــن روائــح‬\n‫وأعطانهــا ومــع هــذا فألصحــاب الفضيلــة االطــاع علــى الصــور املرفقــة‬\n‫علــى اللفــة رقــم (‪ )5‬ويتضــح فيهــا أن للمدعــى عليــه حــوش غنــم واســع ًا‬\n‫بعيــد ًا عــن ســكن املدعيــة أصالــة فلمــاذا يصــر علــى مالصقــة حــوش‬\n‫األغنــام موضــوع الدعــوى مبنــزل املدعيــة أصالــة إضافــة إلــى أن الدعــوى‬\n‫هــذه قــد رفــع فيهــا دعــوى بحــق عــام وقــد اطلعــت اجلهــة املختصــة علــى‬\n\n\n                                                                                      ‫‪356‬‬\n\f      ‫املوقــع وقــررت إزالتــه وقــد قمــت بإرفــاق صــورة مــن القــرار الشــرعي‬\n      ‫الطــاع أصحــاب الفضيلــة عليــه وأمــا مــا يخــص امللحــظ الثانــي وهــو‬\n      ‫دعــوى التناقــض فهــو غيــر صحيــح وقــد بنيــت ســبب ردي لدعــوى‬\n      ‫املدعــي باحلــق اخلــاص حيــث كان يدعــي عــن نفســه وبيتــه يبعــد عن بيت‬\n      ‫املدعــى عليــه قرابــة مائتــن وخمســن متــر ًا أمــا يف هــذه الدعــوى فهــو‬\n      ‫يدعــي وكالــة عــن والدتــه التــي بيتهــا مالصــق حلــوش األغنــام مباشــرة‪.‬‬\n      ‫وأمــا مــا يخــص املالحظــة الثالثــة فقــد جــرى منــي ســؤال الطرفــن أيهمــا‬\n      ‫املنشــأ أو ًال منــزل املدعيــة أصالــة أو حــوش األغنــام فأقــرا جميع ـ ًا بــأن‬\n      ‫املنشــأ أو ًال منــزل املدعيــة أصالــة وأمــا مســألة أن املخطــط زراعــي فــا‬\n      ‫أثــر لــه واحلــال مــا ذكــر حاصــل قبــل حــوش األغنــام محــل األذى‪ .‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n      ‫قالــه وأمــاه الفقيــر إلــى عفــو مــواله ‪ .....‬القاضــي باحملكمــة اجلزائيــة‬\n                                              ‫بنجــران حــرر يف ‪1434/08/28‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34331237‬وتاريــخ‬\n                                                    ‫‪1434/10/15‬هـ‬\n\n\n\n\n‫‪357‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":353,"source_page_end":357,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"80c60865ee785571d2a01dff2cc2f9e925bd59407203a4d58ad5d1ea1627d862","normalized_text_hash":"89fab013ce6d9a9b5cf4fac3d179803c3d825051bd6023a29220300b39844442","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p353-34167752"},{"id":"452c9e9b-3949-59c6-b1be-8111af404e0e","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -مطالبة مبنع إسكان عزاب يف حي خاص بالعوائل -إقرار -وقوف القاضي على محل النزاع ومعاينته -ثبوت الدعوى واحلكم بطلبات املدعي .","document_number":"33675732","case_number":"34200299","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"دعوى منع ضرر -مطالبة مبنع إسكان عزاب يف حي خاص بالعوائل -إقرار -وقوف القاضي على محل النزاع ومعاينته -ثبوت الدعوى واحلكم بطلبات املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/29‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33675732 :‬‬\n                   ‫َر ْق ُم الدعوى‪34200299 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34316096‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫دعــوى منــع ضــرر ‪ -‬مطالبــة مبنــع إســكان عــزاب يف حي خــاص بالعوائل‬\n‫‪ -‬إقــرار ‪ -‬وقــوف القاضــي علــى محــل النــزاع ومعاينتــه ‪ -‬ثبــوت الدعــوى‬\n                                                 ‫واحلكــم بطلبــات املدعي ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ وقواعــد العدالــة العامــة الــواردة‬\n                                                       ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان بــأن املدعــى عليــه ميلــك عمــارة مجــاورة لســكنهما يف‬\n‫حــي خــاص بالعوائــل وقــد أســكن فيهــا مجموعــة مــن العمــال العــزاب‬\n‫فتضــرروا مــن ذلــك مبــا هــو مذكــور يف دعواهمــا ‪ ،‬ولــذا طلبــا احلكــم‬\n‫علــى املدعــى عليــه بإخــراج العــزاب الذيــن أســكنهم يف العمــارة وعــدم‬\n‫إســكان أمثالهــم يف املســتقبل‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‬\n‫ودفــع بأنــه عــرض العمــارة إلســكان العوائــل فيهــا فلــم تســتأجر كمــا‬\n‫أن ال يوجــد ضــرر علــى املجاوريــن لوجــود عــزاب يســكنون يف عمــارة‬\n‫مالصقــة مللكــه ‪ -‬قــررت احملكمــة الوقــوف على محل النــزاع ومعاينته‬\n‫فاتضــح أن عمــارة املدعــى عليــه لهــا أبــواب تقابــل مباشــرة منــزل املدعــي‬\n‫وأنــه ال يوجــد ســوى تلــك العمــارة داخــل احلــي أســكن فيهــا املدعــى‬\n\n                                                                                    ‫‪358‬‬\n\f      ‫عليــه عمــاال عزابــا والضــرر متحقــق مــن ذلــك علــى ســكان احلــي مــن‬\n      ‫العوائــل‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بإخــاء العمــارة مــن‬\n      ‫العمــال العــزاب فــور ًا وعــدم إســكان أمثالهــم مســتقبال ‪ -‬قنــع املدعيــان‬\n      ‫باحلكــم وعــارض املدعــى عليــه ‪ -‬قــررت محكمة االســتئناف املصادقة‬\n                                                                      ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....‬و ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــو‬\n      ‫ضــد احلاضــر معهــم ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ .....‬بقولهمــا اننــا نســكن يف حــي ‪ .....‬داخــل ســكني خــاص بالعوائــل‬\n      ‫وجميــع مــن فيــه مــن الســكان مــن العوائــل وتوجــد عمــارة للمدعــى عليــه‬\n      ‫حتدنــي انــا ‪ .....‬مــن جهــة الشــمال مباشــرة وحتدنــي انــا ‪ .....‬مــن جهــة‬\n      ‫الشــرق قــد اســكن يف هــذه العمــارة مجموعــة مــن العمــال العــزاب مــن‬\n      ‫الباكســتانيني واملصريــن وابــواب العمــارة مــن جهــة اجلنــوب مفتوحــه‬\n      ‫وهــي مقابلــة بيوتنــا مباشــرة والعمــال يدخلــون ويخرجــون مــن هــذه‬\n      ‫األبــواب ويحضــر عندهــم زمــاء لهــم ويحصــل هنــاك اجتماعــات‬\n      ‫خصوص ـ ًا يف الليــل حيــث يشــربون الدخــان ويخرجــون الكراســي‬\n      ‫للجلــوس امــام بيوتنــا وقــد تضررنــا مــن ذلــك كثيــرا باإلضافــة الــى فتــح‬\n      ‫النوافــذ لهــذه العمــارة مــن جهــة اجلنــوب وقــد كلمناهــم وقــام بأغالقهــا‬\n      ‫نطلــب منكــم احلكــم علــى املدعــى عليــه بإخــراج هــؤالء العــزاب‬\n      ‫مــن هــذه العمــارة وعــدم اســكان امثالهــم يف املســتقبل هــذه دعوانــا‬\n\n‫‪359‬‬\n\f‫وبعــرض الدعــوى علــى املدعــى عليــه اجــاب بقولــه مــا ذكــره املدعيــان‬\n‫يف دعواهمــا أن هــذه العمــارة لــي واننــي قمــت بإســكان العمــال العــزاب‬\n‫صحيــح وذلــك ألننــي اردت اســكان العوائــل فيهــا وعرضتهــا لذلــك‬\n‫ولكنهــا لــم تســكن مــن العوائــل وهــؤالء العمــال بقــي لهــم فتــرة ســتة‬\n‫اشــهر الــى انتهــاء عقدهــم وال يوجــد ضــرر علــى املجاوريــن منهــم ويوجــد‬\n‫عمــارة عــزاب مالصقــة لعمارتــي مــن جهــة الشــمال هــذه اجابتــي بعــد‬\n‫ذلــك قــررت اخلــروج علــى موقــع النــزاع ويف هــذا اليــوم األثنــن املوافــق‬\n‫‪1434/4/22‬ه ـ جــرى خروجــي انــا القاضــي بهــذه احملكمــة برفقــة‬\n‫مديــر ادارة احملكمــة ‪ .....‬واملوظــف بــاإلدارة ‪ .....‬علــى موقــع النــزاع‬\n‫اخلــاص بدعــوى ‪ .....‬و ‪ .....‬ضــد ‪ .....‬حــي ‪ .....‬وبعــد مشــاهدة املوقــع اتضــح‬\n‫بحضــور األطــراف جميعــا وجــود عمــارة املدعــى عليــه وفيهــا مجموعــة‬\n‫مــن العمــال العــزاب مــن املصريــن والباكســتانيني حســب كالم‬\n‫املدعــى عليــه ولهــا ثالثــة ابــواب مــن جهــة اجلنــوب ويقابلهــا مباشــرة منــزل‬\n‫‪ .....‬وقــد ســألت املدعــى عليــه فقــال ان العمــال يدخلــون ويخرجــون مــن‬\n‫هــذه األبــواب باإلضافــة الــى النوافــذ املطلــة مــن جهــة اجلنــوب وهــي‬\n‫مغلقــة واملدعــي ‪ .....‬يحــد املدعــى عليــه مبنزلــه مــن جهــة الشــرق وقــد‬\n‫كان الشــارع خاليــا مــن العمالــة حــن الوقــوف الســاعة احلاديــة عشــر‬\n‫والنصــف ضحــى وقــد ذكــر املدعــى عليــه أنهــم يحضــرون الظهــر‬\n‫ويوجــد بيــوت حتــد ‪ .....‬مــن جهــة الشــرق كلهــا بيــوت عوائــل ل‪ .....‬و يليــه‬\n‫‪ .....‬ثــم ‪ .....‬وال يوجــد ســوى هــذه العمــارة داخــل احلــي بأبوابهــا املطلــة‬\n‫علــى املجاوريــن هــذا مــا جــرى االطــاع عليــه ولــذا أعــد هــذا احملضــر‬\n‫وعليــه حصــل التوقيــع فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى اقــرار املدعــى عليــه بكــون هــذه العمــارة لــه وأنــه اســكن فيهــا‬\n\n\n                                                                                        ‫‪360‬‬\n\f      ‫عمــال عــزاب وبنــاء علــى احملضــر املعــد مــن قبلنــا وبنــاء علــى حصــول‬\n      ‫الضــرر املتحقــق مــن هــذه العمــارة علــى ســكان احلــي مــن العوائــل وهــم‬\n      ‫عمــال مــن جنســيات مختلفــة ولهــذه العمــارة عــدة ابــواب مــن جهــة احلــي‬\n      ‫وســاكنيه وبنــاء علــى مــا نصــت عليــه االنظمــة والتعليمــات بخصــوص‬\n      ‫منــع العــزاب مــن الســكن داخــل األحيــاء التــي يقطنهــا عوائــل وبنــاء‬\n      ‫علــى مــا نــص عليــه اهــل العلــم مــن عــدم اســكان العــزاب عنــد العوائــل‬\n      ‫واخراجهــم بنــاء علــى ذلــك كلــه فقــد حكمــت علــى املدعــى عليــه‬\n      ‫بأخــاء هــذه العمــارة مــن العمــال العــزاب فــور ًا وعــدم اســكان امثالهــم‬\n      ‫مســتقال وبعــرض ذلــك علــى املدعــى عليــه قــرر عــدم قناعتــه وطلــب‬\n      ‫االســتئناف فأجبتــه لطلبــة وأفهمتــه باملراجعــة يــوم الثالثــاء املوافــق‬\n      ‫‪1434/04/23‬ه ـ الســتالم نســخة مــن صــك احلكــم لالعتــراض عليــه‬\n      ‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم حــرر يف ‪1434/04/22‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34316096‬وتاريــخ‬\n                                                        ‫‪ 1434/9/9‬هـ‬\n\n\n\n\n‫‪361‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":358,"source_page_end":361,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"92495015a94244b2f0c431c3aca671b9c2b4c5e1652fbea0077bf0d43c988699","normalized_text_hash":"002d4581180705091b4cacece14c5f0b70ccc103cfb35f186a55463525b32768","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p358-33675732"},{"id":"75ddbac8-19cd-5e28-a91d-082b62aff461","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -تضرر املدعي من إيقاف املدعى عليه لسياراته أمام منزله وورشته -إقرار املدعى عليه -إيجابية تقرير اخلبراء للمدعي -ثبوت الدعوى -احلكم مبنع املدعى عليه من إيقاف سياراته مبحاذاة منزل املدعي .","document_number":"34304332","case_number":"3427193","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"دعوى منع ضرر -تضرر املدعي من إيقاف املدعى عليه لسياراته أمام منزله وورشته -إقرار املدعى عليه -إيجابية تقرير اخلبراء للمدعي -ثبوت الدعوى -احلكم مبنع املدعى عليه من إيقاف سياراته مبحاذاة منزل املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/23 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34304332 :‬‬\n                    ‫َر ْق ُم الدعوى‪3427193 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34328819‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n‫دعــوى منــع ضــرر ‪ -‬تضــرر املدعــي مــن إيقــاف املدعــى عليــه لســياراته‬\n‫أمــام منزلــه وورشــته ‪ -‬إقــرار املدعــى عليــه ‪ -‬إيجابيــة تقريــر اخلبــراء‬\n‫للمدعــي ‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم مبنــع املدعــى عليــه مــن إيقــاف‬\n                                        ‫ســياراته مبحــاذاة منــزل املدعــي ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار)‪.‬‬\n                                   ‫‪ -2‬القاعدة الشرعية‪« :‬الضرر يزال»‪.‬‬\n\n\n\n‫ادعــى املدعــي بأنــه ميتلــك منــز ًال وورشــة ومغســلة ســيارات مالصقــن لــه‬\n‫وأن املدعــى عليــه لــه منــزل مجــاور ملنزلــه وقــد تضــرر مــن إيقــاف املدعــى‬\n‫عليــه لســياراته مبحــاذاة منزلــه باألضــرار املذكــورة يف دعــواه‪ ،‬ولــذا‬\n‫طلــب إلزامــه بعــدم إيقــاف ســياراته مبحــاذاة منزلــه‪ -‬أقــر املدعــى عليــه‬\n‫مبــا جــاء يف الدعــوى ودفــع بأنــه محتــاج إليقافهــا يف ذلــك املــكان وال‬\n‫يوجــد ضــرر علــى املدعــي مــن ذلــك‪ -‬قــررت احملكمــة تكليــف قســم‬\n‫اخلبــراء مبعاينــة محــل النــزاع فأفــادوا بــأن العــرف إيقــاف الســيارات‬\n‫محاذيــة للمنــزل دون جتــاوز حلــدوده بالوقــوف‪ -‬مــن املقــرر شــرع ًا أنــه‬\n‫ال ضــرر وال ضــرار وأن الضــرر يــزال‪ -‬قضــت احملكمــة مبنــع املدعــى‬\n\n                                                                                      ‫‪362‬‬\n\f      ‫عليــه مــن إيقــاف ســياراته مبحــاذاة منــزل املدعــي‪ -‬قنــع املدعــي باحلكــم‬\n      ‫وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                    ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل برقــم ‪ 3427193‬وتاريــخ ‪1434/01/17‬ه ـ املقيــدة‬          ‫ّ‬\n      ‫باحملكمــة برقــم ‪ 34129255‬وتاريــخ ‪ 1434/01/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1434/08/23‬ه ـ افتتحــت اجللســة الســاعة ‪01 :30‬‬\n      ‫وفيهــا حضــر املدعــي ‪ ..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬وحضــر حلضــوره املدعــى عليــه ‪ .......... /‬ســعودي اجلنســية‬\n      ‫ا إننــي أمتلــك‬‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬ثــم ادعــى املدعــي قائـ ً‬\n      ‫ورشــة ومغســلة ســيارات ومنــزل مالصــق لهــا بحــي العزيزيــة والورشــة‬\n      ‫تفتــح علــى شــارع غربــي ويحدهــا مــن الشــمال شــارع واملدعــى عليــه لــه‬\n      ‫منــزل يفتــح علــى الشــارع املذكــور وهــو الفاصــل بينــي وبينــه ويفتــح‬\n      ‫أيضـ ًا علــى شــارع غربــي وحيــث أن بــاب منزلــي يفتــح علــى هــذا الشــارع‬\n      ‫وتوجــد بيــارة املغســلة وطبلــون الكهربــاء علــى هــذا الشــارع فقــد‬\n      ‫تضــررت مــن إيقــاف املدعــى عليــه لســياراته مبحــاذاة ورشــتي واملنــزل‬\n      ‫ممــا يعيقنــي مــن ســحب البيــارة التــي تلزمنــي البلديــة بســحبها باســتمرار‬\n      ‫وقــد تقــدم املدعــى عليــه بشــكوى ضــدي للشــرطة والبلديــة يطالبنــي‬\n      ‫بهــا بســحب البيــارة وعنــد حضــور الوايــت لــم يتمكــن مــن ســحبها‬\n\n\n‫‪363‬‬\n\f‫لوقــوف ســيارته فــوق البيــارة وتضــررت أيض ـ ًا مــن عــدم وصــول فواتيــر‬\n‫الكهربــاء للعــداد لعــدم متكــن موظــف الكهربــاء مــن وضعهــا فيــه‬\n‫وتضــررت أيضـ ًا مــن إغالقــه لبــاب املنــزل بســياراته أطلــب إلزامــه بعــدم‬\n‫إيقــاف ســياراته مبحــاذاة ورشــتي ومنزلــي هــذه دعــواي وبســؤال املدعــى‬\n‫ا مــا ذكــره املدعــي مــن مــكان الورشــة واملنــزل وبابــه‬    ‫عليــه أجــاب قائـ ً‬\n‫املذكــور ومــكان البيــارة والطبلــون وأننــي قد اشــتكيته لدى الشــرطة‬\n‫وطلبــت منــه ســحب البيــارة وأن ســيارتي كانــت واقفــة علــى البيــارة‬\n‫حــن حضــور الشــرطة فهــذا كلــه صحيــح وال ضــرر عليــه مــن إيقــاف‬\n‫ســياراتي يف هــذا املــكان حيــث أن الشــارع الغربــي ملنزلــي توجــد فيــه‬\n‫ســياراتي األخــرى والشــارع ملــك للدولــة وأنــا محتــاج لوقــوف ســياراتي‬\n‫يف هــذا املــكان بهــذا أجــاب فبعــد الدعــوى واإلجابــة واالطــاع علــى‬\n‫أوراق املعاملــة ومنهــا قــرار هيئــة اخلبــراء باحملكمــة العامــة بحائــل رقــم‬\n‫(‪ )33194188‬وتاريــخ ‪1434/05/14‬ه ـ املتضمــن [نفيدكــم أنــه مت‬\n‫وقوفنــا نحــن عضــوي هيئــة اخلبــراء كل مــن ‪ .....‬و‪ .....‬ومعاينــة املوقــع‬\n‫علــى الطبيعــة وحاولنــا اإلصــاح بينهمــا ولــم يتيســر ذلــك وشــاهدنا‬\n‫ســيارات املدعــى عليــه مالصقــة لبنشــر املدعــي مــن اجلهــة الشــمالية‬\n‫والتــي بهــا بيــارة وطبلــون كهربــاء املدعــي والــذي نــرى أن يجعــل وقــوف‬\n‫ســياراته (نعنــي املدعــى عليــه) أن تكــون محاذيــة لبيتــه وال يتجــاوز‬\n‫بالوقــوف حــدود منزلــه حســب العــرف هــذا مــا نــراه واهلل املوفــق] ولقولــه‬\n‫صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) وملــا قــرره أهــل العلــم مــن أن‬\n‫الضــرر يــزال لذلــك كلــه فقــد حكمــت مبنــع املدعــى عليــه مــن إيقــاف‬\n‫ســياراته مبحــاذاة ورشــة ومغســلة ومنــزل املدعــي هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت واهلل أعلــم وأحكــم وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n\n\n                                                                                        ‫‪364‬‬\n\f      ‫االعتــراض وأنــه ســيتقدم بالئحــة اعتراضيــة فجــرى تســليمه صــورة مــن‬\n      ‫صــك احلكــم لتقــدمي اعتراضــه خــال ثالثــن يومـ ًا مــن هــذا اليــوم وإذا‬\n      ‫لــم يقــدم اعتراضــه خــال هــذه املهلــة فــإن حقــه يف االعتــراض يســقط‬\n      ‫ويكتســب احلكــم القطعيــة دون رفعــه حملكمــة االســتئناف ومت قفــل‬\n      ‫اجللســة الســاعة (‪ )02.00‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/8/23‬ه ـ ‪.‬‬\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34328819‬وتاريــخ‬\n                                                   ‫‪ 1434/10/12‬هـ‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":362,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0b252f52b604109215c1ae58e6e70a504579e00449834d48115863d9891f55f","normalized_text_hash":"63959757d4c03223eaa87490a55aec47942a7b69fc3797a8043d81a5503e65c7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p362-34304332"},{"id":"68720165-b687-57c8-998b-b31001733aae","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى منع ضرر -مطالبة املدعى عليه عدم تأجير العقار على عزاب للضرر -مصادقة املدعى عليه على الدعوى عدا الضرر -املدعى عليه وسيط بن املدعي (املؤجر) واملستأجرين -دعوى ضرر من املنتفع من العقار تسمع يف مواجهة املستأجر -حكم بصرف النظر لعدم االختصاص النوعي -إفهام بإقامة الدعوى على املستأجر - احلكم بصرف النظر لعدم االختصاص النوعي .","document_number":"34346127","case_number":"34463063","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة بقعاء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/2","year":"1434","subject":"دعوى منع ضرر -مطالبة املدعى عليه عدم تأجير العقار على عزاب للضرر -مصادقة املدعى عليه على الدعوى عدا الضرر -املدعى عليه وسيط بن املدعي (املؤجر) واملستأجرين -دعوى ضرر من املنتفع من العقار تسمع يف مواجهة املستأجر -حكم بصرف النظر لعدم االختصاص النوعي -إفهام بإقامة الدعوى على املستأجر - احلكم بصرف النظر لعدم االختصاص النوعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/2 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34346127 :‬‬\n                    ‫َر ْق ُم الدعوى‪34463063 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34356295‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n ‫دعــوى منــع ضــرر‪ -‬مطالبــة املدعــى عليــه عــدم تأجيــر العقــار على عزاب‬\n ‫للضــرر‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى عــدا الضــرر‪ -‬املدعــى‬\n ‫عليــه وســيط بــن املدعــي (املؤجــر) واملســتأجرين‪ -‬دعــوى ضــرر مــن‬\n ‫املنتفــع مــن العقــار تســمع يف مواجهــة املســتأجر ‪ -‬حكــم بصــرف النظــر‬\n ‫لعــدم االختصــاص النوعــي‪ -‬إفهــام بإقامــة الدعــوى علــى املســتأجر ‪-‬‬\n                    ‫احلكــم بصــرف النظــر لعــدم االختصــاص النوعــي ‪.‬‬\n\n\n\n\n ‫املــادة ‪ 13/31‬مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة والتــي‬\n ‫تنــص علــى أن دعــاوى الضــرر مــن املنتفعــن بالعقار ســواء كانــوا عزاب ًا‬\n ‫أو غيرهــم مــن اختصــاص احملاكــم اجلزائيــة وتســمع يف مواجهــة‬\n ‫ال علــى وحــدات ســكنية مؤجــرة‬    ‫املســتأجر إال إذا كان العقــار مشــتم ً‬\n ‫علــى عــزاب وتكــون الدعــوى علــى املالــك ملنعــه مــن تأجيــر العــزاب اهــ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه أن املدعــى عليــه قــام بتأجيــر الفيــا‬\n ‫الواقعــة يف حــي ‪ ....‬ملــدة ســنة علــى مجموعــة مــن العــزاب وهــي تقــع جــوار‬\n ‫فلــة املدعــي وملــا فيــه مــن الضــرر مــن وجودهــم ومضايقتهــم فقــد طلــب‬\n ‫املدعــي إلــزام املدعــى عليــه بعــدم تأجيــر هــذه الفيــا للمســتأجرين وقرر‬\n\n                                                                                       ‫‪366‬‬\n\f      ‫أن الفيــا ليســت وحــدات ســكنية ‪ -‬أجــاب املدعــى عليــه باملصادقــة‬\n      ‫علــى الدعــوى مــا عــدا الضــرر فذكــر عــدم علمــه بــه وانــه بإمــكان‬\n      ‫املدعــي إقامــة الدعــوى علــى املســتأجرين وقــرر أنــه ال ميلــك الفيــا‬\n      ‫املؤجــرة وإمنــا كان وســيط ًا يف تأجيرهــا ‪ -‬قــرر ناظــر القضيــة وبنــاء‬\n      ‫علــى املــادة ‪ 13/31‬مــن نظــام املرافعــات الشــرعية والتــي تنــص علــى أن‬\n      ‫دعــاوى الضــرر مــن املنتفعــن مــن العقــار تســمع يف مواجهــة املســتأجر‬\n      ‫إال إذا كان العقــار يحــوي علــى وحــدات ســكنية فتســمع يف مواجهــة‬\n      ‫املالــك ملنعــه مــن تأجيــر العــزاب لذلــك فقــد صــدر احلكم بصــرف النظر‬\n      ‫عــن الدعــوى ضــد املدعــى عليــه وافهمــه بــان لــه احلــق يف إقامــة الدعــوى‬\n      ‫ضــد املســتأجرين وقــرر ناظــر القضيــة انــه لــم يتــم طلــب أصــل التملــك‬\n      ‫وال االستفســار عــن ســجل الصــك ألن الدعــوى ليســت يف منازعــة يف‬\n      ‫متلــك يف عقــار وإمنــا يف عقــد إجــارة تصــادق طــريف القضيــة عليــه ‪ -‬صــدر‬\n      ‫قــرار محكمــة االســتئناف يف منطقــة حائــل باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف‬\n      ‫يــوم األحــد املوافــق ‪1434/11/2‬ه ـ لــدي أنــا رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة التاســعة صباحــا للنظــر‬\n      ‫يف الدعــوى املقدمــة مــن ضــد مكتــب ‪........‬العقــاري واملقيــدة بهــذه‬\n      ‫احملكمــة برقــم ‪ 342366602‬يف ‪1434/10/20‬ه ـ واحملالــة لــي برقــم‬\n      ‫‪ 34463063‬يف ‪1434/10/20‬ه ـ وقــد حضــر يف هــذه اجللســة ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى احلاضــر يف هــذه‬\n      ‫اجللســة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم قائــا يف حتريــر‬\n‫‪367‬‬\n\f‫دعــواه لقــد قــام املدعــى عليــه بتأجيــر الفلــة الواقعــة يف حــي ‪........‬يف‬\n‫بقعــاء مبوجــب عقــد اإليجــار رقــم ‪........‬يف ‪1434/10/18‬ه ـ ملــدة ســنة‬\n‫واحــدة علــى مجموعــة مــن العمالــة الغيــر ســعوديني وهــم عــزاب وألن‬\n‫هــذه الفلــة تقــع بجــوار فلتــي وملــا فيــه مــن الضــرر مــن وجودهــم بهــذه‬\n‫الفلــة ومضايقتهــم لــي أطلــب إلــزام املدعــى عليــه بعــدم تأجيــره هــذه‬\n‫الفلــة للمســتأجرين املذكوريــن هــذه دعــواي ثــم ســألت املدعــي هــل‬\n‫هــذه الفلــة تشــتمل علــى عــدة وحــدات ســكنية أم أنــه مت تأجيــر هــذه‬\n‫الفلــة مــن قبــل املدعــى عليــه علــى العمالــة املذكوريــن كاملــة فقــال إن‬\n‫املدعــى عليــه قــد قــام بتأجيرهــا كاملــة علــى العمالــة املذكوريــن وهــي‬\n‫ليســت وحــدات ســكنية هكــذا قــرر وبســؤال املدعــى عليــه عــن دعــوى‬\n‫ا مــا ذكــره املدعــي كلــه صحيــح مــا عــدا وجــود‬      ‫املدعــي أجــاب قائ ـ ً‬\n‫الضــرر مــن العمالــة املذكوريــن فهــذا ال أعلــم عنــه وبإمــكان املدعــي‬\n‫رفــع دعــواه ضــد املســتأجرين وأنــا ال أملــك هــذه الفلــة وال أســكنها وإمنــا‬\n‫أنــا كنــت وســيط يف اســتئجار العمالــة هذه الفلــة ألنني صاحب مكتب‬\n‫‪........‬العقــاري هكــذا أجــاب فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n‫وألن املدعــي قــرر أن هــذه الفلــة قــام املدعــى عليــه بتأجيرهــا كاملــة‬\n‫علــى العمالــة املذكوريــن وأنهــا ليســت وحــدات ســكنية ونظــر ًا ملــا جــاء‬\n‫يف املــادة (‪ )13/31‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‬\n‫والتــي تنــص علــى أن دعــاوى الضــرر مــن املنتفعــن بالعقار ســواء أكانوا‬\n‫عزابـ ًا أم غيرهــم مــن اختصــاص احملاكــم اجلزئيــة وتســمع يف مواجهــة‬\n‫املســتأجر إال إذا كان العقــار مشــتمال علــى عــدة وحــدات ســكنية‬\n‫مؤجــرة علــى عــزاب فتكــون الدعــوى علــى املالــك ملنعــه مــن تأجيــر‬\n‫العــزاب اهــ‪ .‬لذلــك كلــه فقــد رددت هــذه الدعــوى وأفهمــت املدعــي بــأن‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫عليــه تقــدمي دعــوى ضــد املســتأجرين وبذلــك حكمــت ولــم يتــم طلــب‬\n      ‫أصــل صــك التملــك وال االستفســار عــن ســريان مفعولــه ألن الدعــوى‬\n      ‫ليســت منازعــة يف متلــك هــذا العقــار وإمنــا يف تأجيــر تصــادق املدعيــن‬\n      ‫عليــه وبعــرض احلكــم علــى املدعــي قــرر عــدم القناعــة بــه وطلــب رفــع‬\n      ‫احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة وعليــه جــرى‬\n      ‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1434/11/2‬ه ـ‬\n      ‫احلمــد هلل وحده ـ والصــاة والســام علــى مــن ال نبــي بعــده فلــدي أنــا‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف يــوم‬\n      ‫األحــد املوافــق ‪1434/11/23‬ه ـ الســاعة الواحــدة ظهــرا بنــاء علــى‬\n      ‫ورود املعاملــة مــن محكمــة االســتئناف بحائــل برقــم ‪342366602‬‬\n      ‫يف ‪1434/11/11‬ه ـ ومرفقــا بهــا قــرار الدائــرة حلقوقيــة األولــى رقــم‬\n      ‫‪ 34356295‬يف ‪1434/11/10‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫مــا حكــم بــه فضيلتــه وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/11/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــه‬\n      ‫بقعــاء برقــم ‪ 342366602‬وتاريــخ ‪1434/11/2‬ه ـ واملقيــدة لدينا بتاريخ‬\n      ‫‪1434/11/6‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34346127‬يف ‪1434/11/2‬هـ‬\n      ‫الصــادر مــن فضيلــة القاضــي‪ ...... /‬اخلــاص بدعــوى ضــد بشــأن دعــوى‬\n      ‫إخــاء عقــار علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك‬\n\n\n‫‪369‬‬\n\f‫حكــم فضيلتــه كمــا هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه‬\n                         ‫واهلل املوفــق وصلــى وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                               ‫‪370‬‬\n\f371\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫املطالبة بنفقة الطفل من والدته وصرف النظر‬\n  ‫‪5‬‬                                                          ‫نفقة‬    ‫‪1‬‬\n         ‫عن ذلك كون األم لم تنو الرجوع بالنفقة عليه‬\n\n\n         ‫اشتراط نية الرجوع ملن قام بالنفقة الواجبة على‬\n  ‫‪11‬‬      ‫غيره واشتراط الوكالة للمطالبة عن األبناء‬           ‫نفقة‬    ‫‪2‬‬\n                            ‫البالغني‬\n\n\n         ‫مطالبة زوجة ناشز بالنفقة املاضية واملستقبلية‬\n  ‫‪20‬‬       ‫لها وألبنائها وتقدير النفقة من قسم اخلبراء‬        ‫نفقة‬    ‫‪3‬‬\n         ‫وحلفها اليمني بنية الرجوع على الزوج بالنفقة‬\n\n\n         ‫مطالبة الزوجة بنفقة ملدة محددة مع نفقة البنت‬\n  ‫‪30‬‬                                                         ‫نفقة‬    ‫‪4‬‬\n                      ‫املاضية واملستقبلية‬\n\n\n          ‫صرف النظر عن طلب الزوجة نفقتها املاضية‬\n         ‫كونها ناشز ًا وتقدير النفقة املاضية واملستقبلية‬\n  ‫‪38‬‬          ‫للبنت عن طريق قسم اخلبراء واحلكم‬               ‫نفقة‬    ‫‪5‬‬\n           ‫باستخراج تبليغ والدة وشهادة ميالد وإضافة‬\n                      ‫املولودة يف دفتر العائلة‬\n\n\n           ‫املطالبة بالنفقة املاضية واملستقبلية لألوالد‬\n          ‫وتسليم األم األوراق الثبوتية ألوالدها الذين يف‬\n  ‫‪45‬‬     ‫حضانتها واحلكم بالنفقة وإخراج شهادة امليالد‬         ‫نفقة‬    ‫‪6‬‬\n          ‫وإسقاط املدعية من سجل أسرة املدعى عليها‬\n                         ‫بالتنفيذ املعجل‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n           ‫مطالبة الزوجة بالنفقة املاضية واملستقبلية‬\n         ‫وعدم استحقاقها لنشوزها وعدم التمكني من‬\n  ‫‪58‬‬                                                        ‫نفقة‬    ‫‪7‬‬\n         ‫االستمتاع واحلكم بنفقة الولد وحتديدها عن‬\n                         ‫طريق اخلبراء‬\n\n\n           ‫احلكم بتسليم النفقة املاضية واملستقبلية‬\n  ‫‪66‬‬                                                        ‫نفقة‬    ‫‪8‬‬\n                         ‫للزوجة وابنها‬\n\n\n         ‫فسخ نكاح الزوجة لتضررها من غياب الزوج‬\n          ‫وعدم نفقته واألخذ بشهادة الشهود وإعالم‬\n  ‫‪71‬‬                                                        ‫نفقة‬    ‫‪9‬‬\n          ‫الزوج عن طريق اإلعالن يف اجلريدة واجلهات‬\n                           ‫الرسمية‬\n\n\n             ‫مطالبة الزوجة بنفقتها املاضية واملستقبلية‬\n  ‫‪78‬‬     ‫ونفقة العدة وعدم سقوط حقها وعدها ناشز ًا‬           ‫نفقة‬    ‫‪10‬‬\n                 ‫حيث لم يوفر الزوج البيت الشرعي‬\n\n\n         ‫احلكم على األب بدفع نفقة األوالد املستقبلية‬\n  ‫‪88‬‬       ‫وتسليم النفقة للحاضنة ‪ ،‬وعدم استحقاق‬             ‫نفقة‬    ‫‪11‬‬\n             ‫الزوج للنفقة المتناعها عن حلف اليمني‬\n\n\n           ‫احلكم بنفقة االبن املستقبلية وعدم األخذ‬\n ‫‪102‬‬                                                        ‫نفقة‬    ‫‪12‬‬\n                    ‫بتقدير قسم اخلبراء‬\n\n\n         ‫املطالبة بنفقة األوالد املاضية وميني االستظهار‬\n ‫‪107‬‬     ‫يف النفقة عن نية الرجوع واألخذ بقول األوالد‬        ‫نفقة‬    ‫‪13‬‬\n          ‫فيمن أنفق عليهم حال اخلالف بني الزوجني‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫احلكم بنفقة ماضية ومستقبلية لألوالد وتقدير‬\n ‫‪118‬‬     ‫النفقة عن طريق قسم اخلبراء واحلكم للمطلقة‬          ‫نفقة‬    ‫‪14‬‬\n                          ‫بنفقة عدتها‬\n\n\n           ‫احلكم على املدعى عليها بدفع نفقة احلمل‬\n ‫‪123‬‬     ‫والنفقة الشهرية املاضية واملستقبلية والكسوة‬        ‫نفقة‬    ‫‪15‬‬\n                          ‫املستقبلية‬\n\n\n         ‫احلكم بإلزام الزوج بنفقة االبن املاضية إلقراره‬\n ‫‪131‬‬      ‫بعدم النفقة وتقدير النفقة املاضية عن طريق‬         ‫نفقة‬    ‫‪16‬‬\n                          ‫قسم اخلبراء‬\n\n\n         ‫مطالبة الزوجة بنفقتها املاضية وشروع اليمني‬\n ‫‪137‬‬                                                        ‫نفقة‬    ‫‪17‬‬\n                  ‫يف جانب أقوى املتداعيني‬\n\n\n          ‫طلب زيادة النفقة لكبر األوالد وزيادة راتب‬\n ‫‪145‬‬     ‫األب وطلب تسديد رسوم الدراسة وتوفير سائق‬           ‫نفقة‬    ‫‪18‬‬\n                        ‫وسيارة لألوالد‬\n\n\n            ‫احلكم بالنفقة املاضية واملستقبلية لالبن‬\n ‫‪155‬‬        ‫واألخذ بيمني األم على ماأنفقته أنه بنية‬         ‫نفقة‬    ‫‪19‬‬\n                        ‫الرجوع على األب‬\n\n\n          ‫احلكم بنفقة الزوجة املاضية ونفقة األوالد‬\n ‫‪160‬‬      ‫املاضية واملستقبلية وتقدير النفقة عن طريق‬         ‫نفقة‬    ‫‪20‬‬\n                          ‫قسم اخلبراء‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫مطالبة الزوجة بالنفقة املاضية وقيمة الذهب‬\n ‫‪170‬‬       ‫وفاتورة الهاتف الثابت ودفع الزوج بنشوز‬          ‫نفقة‬    ‫‪21‬‬\n                          ‫الزوجة‬\n\n\n         ‫احلكم بنفقة الزوجة واألوالد القصر والبالغني‪،‬‬\n ‫‪175‬‬      ‫عد الزوجة ناشز ًا بعد قذف زوجها لها‬\n                                            ‫وعدم ٌ‬         ‫نفقة‬    ‫‪22‬‬\n                      ‫وخروجها من بيتها‬\n\n\n         ‫مطالبة أم بنفقة ابنتها وتقدير النفقة عن طريق‬\n ‫‪181‬‬                                                       ‫نفقة‬    ‫‪23‬‬\n                        ‫قسم اخلبراء‬\n\n\n          ‫مطالبة والد بنفقته من ابنته وهي يف ذمة زوج‬\n ‫‪186‬‬                                                       ‫نفقة‬    ‫‪24‬‬\n                   ‫وصرف النظر عن الدعوى‬\n\n\n          ‫إلزام األب بنفقة ولديه مع أجرة سكنهما‪،‬‬\n ‫‪190‬‬      ‫وتسليمهما للمدعية‪ ،‬عند إخالء شقة املدعى‬          ‫نفقة‬    ‫‪25‬‬\n                            ‫عليه‬\n\n\n ‫‪197‬‬        ‫إلزام األب بنفقة ابنته املاضية واملستقبلية‬     ‫نفقة‬    ‫‪26‬‬\n\n\n         ‫احلكم بنفقة شهرين لألوالد قبل تقديرها من‬\n ‫‪204‬‬                                                       ‫نفقة‬    ‫‪27‬‬\n             ‫قسم اخلبراء وشموله بالنفاذ املعجل‬\n\n\n          ‫مطالبة طليق مسجون بنفقة أوالدها السابقة‬\n ‫‪208‬‬                                                       ‫نفقة‬    ‫‪28‬‬\n            ‫واملستقبلية وبقية عملية الوالدة ونفقة لها‬\n\n\n         ‫صرف النظر عن مطالبة أم لنفقة ابنتها املاضية‬\n ‫‪212‬‬                                                       ‫نفقة‬    ‫‪29‬‬\n             ‫ألنها لم تنو الرجوع على األب بالنفقة‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫احلكم مبا اصطلح عليه الطرفان يف نفقة العدة‬\n ‫‪219‬‬      ‫واحلكم على األب بنفقة ابنته وتضمني احلكم‬          ‫نفقة‬    ‫‪30‬‬\n                         ‫بالنفاد املعجل‬\n\n\n         ‫للمرأة نظاما إقامة دعواها يف املسائل الزوجية‬\n ‫‪224‬‬       ‫مبقر إقامتها وامتناع الزوج عن احلضور يعد‬         ‫نفقة‬    ‫‪31‬‬\n                            ‫نكو ًال‬\n\n\n           ‫احلكم على األوالد بدفع نفقة شهرية لألم‬\n ‫‪230‬‬     ‫وأجرة املواصالت وخدمة والدهم بأنفسهم فإن‬           ‫نفقة‬    ‫‪32‬‬\n            ‫تعذر فعليهم أن يوفروا من يقوم بخدمتها‬\n\n\n         ‫احلكم بالنفقة املاضية واملستقبلية لالبن البالغ‬\n ‫‪237‬‬                                                        ‫نفقة‬    ‫‪33‬‬\n                    ‫وتقديرها من قسم اخلبراء‬\n\n\n          ‫إلزام املدعى عليه بدفع نفقة الطفل املاضية‬\n ‫‪245‬‬     ‫واملستقبلية ونفقة احلمل ‪ ،‬نفقة احلمل ال تسقط‬       ‫نفقة‬    ‫‪34‬‬\n                          ‫بالنشوز‬\n\n\n          ‫احلكم على األب بدفع نفقة األبناء املستقبلية‬\n ‫‪252‬‬                                                        ‫نفقة‬    ‫‪35‬‬\n                        ‫حيث تقدير اخلبراء‬\n\n\n          ‫احلكم على املدعى عليه بتسليم نفقة ماضية‬\n ‫‪259‬‬       ‫للزوجة ونفقة ماضية ومستقبلية لالبن ورد‬           ‫نفقة‬    ‫‪36‬‬\n             ‫دعوى املدعية مبطالبتها مبتعة الطالق‬\n\n\n          ‫احلكم على املدعى عليه بدفع النفقة املاضية‬\n ‫‪264‬‬     ‫واملستقبلية ودخول نفقة احلمل يف تقدير النفقة‬       ‫نفقة‬    ‫‪37‬‬\n                            ‫املاضية‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬       ‫م‬\n\n\n           ‫إلزام األوالد بالنفقة على والدتهم وإحضار‬\n ‫‪272‬‬      ‫سائق وخادمة وتقدير النفقة عن طريق قسم‬              ‫نفقة‬       ‫‪38‬‬\n                          ‫اخلبراء‬\n\n\n          ‫احلكم على الزوج بدفع نفقة الزوجة املاضية‬\n ‫‪280‬‬                                                         ‫نفقة‬       ‫‪39‬‬\n             ‫وتقدير النفقة عن طريق قسم اخلبراء‬\n\n\n         ‫إلزام املدعى عليه بدفع نفقة فترة احلمل ونفقة‬\n ‫‪287‬‬                                                         ‫نفقة‬       ‫‪40‬‬\n         ‫الطفل املاضية وحتديد نفقة مستقبلية للطفل‬\n\n\n         ‫املطالبة مبصاريف الدراسة والعالج ودفع فرق‬\n         ‫النفقة بني ما دفعه وبني ما مت تقديره من قسم‬\n ‫‪293‬‬                                                         ‫نفقة‬       ‫‪41‬‬\n          ‫اخلبراء‪ ،‬واحلكم بدفع فرق النفقة املاضية‬\n                    ‫ودفع النفقة املستقبلية‬\n\n\n            ‫احلكم بدفع نفقة احلمل والنفقة املاضية‬\n ‫‪299‬‬                                                         ‫نفقة‬       ‫‪42‬‬\n                            ‫للمولود‬\n\n\n            ‫املطالبة بقيمة إيجار السكن ومصاريف‬\n ‫‪312‬‬        ‫الدراسة وإعالة وتقديرها عن طريق قسم‬              ‫نفقة‬       ‫‪43‬‬\n          ‫اخلبراء والصلح بني الطرفني على مبالغ معينة‬\n\n\n          ‫مطالبة األم بنفقة أوالدها املاضية واملستقبلية‬\n ‫‪320‬‬        ‫واحلكم بالنفقة املستقبلية مشمول بالنفاذ‬          ‫نفقة‬       ‫‪44‬‬\n                             ‫املعجل‬\n\n\n         ‫مطالبة زوج والد زوجته بكف تدخله بينه وبني‬\n                                                          ‫كف تدخل‬\n ‫‪329‬‬     ‫زوجته وإلزام والد الزوجة (املدعى عليه) بكف‬                     ‫‪45‬‬\n                                                          ‫والد الزوجة‬\n                      ‫يده عن زوجة املدعي‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬       ‫م‬\n\n\n         ‫إلزام املدعى عليه برد اخلادمة‪ ،‬حيث إن تخلفه‬\n                                                          ‫طلب‬\n ‫‪337‬‬     ‫عن احلضور يعد نكو ًال ورد اليمني إلى املدعي‬                 ‫‪46‬‬\n                                                       ‫إعادة خادمة‬\n                        ‫بصحة دعواه‬\n\n\n         ‫إلزام املدعى عليه بإزالة حظيرة أغنامه لتضرر‬      ‫دعوى‬\n ‫‪345‬‬                                                                 ‫‪47‬‬\n                       ‫املدعية من ذلك‬                   ‫منع ضرر‬\n\n\n         ‫احلكم مبنع سكن العزاب يف خاص بالعوائل‬           ‫دعوى‬\n ‫‪353‬‬                                                                 ‫‪48‬‬\n           ‫ووقوف القاضي على محل النزاع ومعاينته‬         ‫منع ضرر‬\n\n\n           ‫احلكم على املدعى عليها باملنع من إيقاف‬        ‫دعوى‬\n ‫‪358‬‬                                                                 ‫‪49‬‬\n                ‫سيارته مبحاذاة منزل املدعي‬              ‫منع ضرر‬\n\n\n         ‫احلكم بصرف النظر عن دعوى املدعي لعدم‬\n                                                         ‫دعوى‬\n ‫‪362‬‬      ‫االختصاص النوعي ‪ ،‬وإفهام املدعي بإقامة‬                     ‫‪50‬‬\n                                                        ‫منع ضرر‬\n                   ‫الدعوى على املستأجر‬\n\n\n ‫‪366‬‬                                                                 ‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":366,"source_page_end":378,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"69a2ef9267232818d1086aa2b9508a37e65dcd3617e59d13a5277aa6a17167fe","normalized_text_hash":"f9bb67b2ebdefbcd82f9280a05fe883b28583d1330e1c80ec7c97f448fb7ce6f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p366-34346127"},{"id":"c0a09f50-c8ca-5654-8f78-faee20f30d09","document_type":"judgment","category":"judicial","subcategory":"general","title":"وإقامة حد الغيلة عليه -حيث تلقت الشرطة بالغا عن قيام املدعى عليه بطعن أحد الساكنني معه يف سكن العمال عدة طعنات تويف على إثرها يف املستشفى -وقد جرى استجواب بقية العمال فأفاد مجموعة منهم مبشاهدتهم له وهو يطعن املجني عليه ،قرر املدعى عليه يف بداية المحاكمة بأنه مريض ويعاني من ضعف يف الذاكرة وال يذكر ما حصل معه وتنتابه حاالت جنون وأن املجني","document_number":"33280585","case_number":"4944","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/3","year":"1434","subject":"وإقامة حد الغيلة عليه -حيث تلقت الشرطة بالغا عن قيام املدعى عليه بطعن أحد الساكنني معه يف سكن العمال عدة طعنات تويف على إثرها يف املستشفى -وقد جرى استجواب بقية العمال فأفاد مجموعة منهم مبشاهدتهم له وهو يطعن املجني عليه ،قرر املدعى عليه يف بداية المحاكمة بأنه مريض ويعاني من ضعف يف الذاكرة وال يذكر ما حصل معه وتنتابه حاالت جنون وأن املجني","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪ 33280585 :‬تاريخه‪1433/6/3 :‬هـ‬\n                            ‫رقم الدعوى‪4944:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34188914‬تاريخه‪1434/4/15 :‬هـ‬\n\n\n    ‫قتــل ‪ ،‬قتــل عمــد ‪ ،‬قتــل بإســتخدام ســكني ‪ ،‬طلــب االدعــاء العــام إقامــة‬\n    ‫حــد الغيلــة ‪ ،‬دفــع املدعــى عليــه باملــرض النفســي (فصــام) ‪ ،‬تقريــر طبــي‬\n    ‫نفســي ‪ ،‬عــدم مراجعــة احلــق اخلــاص ‪ ،‬القاتــل واملقتــول مــن جنســية‬\n    ‫واحــدة ‪ ،‬درء حــد احلرابــة لعــدم اكتمــال أهليــة ‪ ،‬التعزيــر بالســجن‬\n    ‫واجللــد وتســليم املدعــى عليــه لســلطات بــاده لتمكــن أوليــاء الــدم مــن‬\n                                                                        ‫مطالبتــه‪.‬‬\n\n\n\n                                        ‫ما أشارت له احملكمة يف تسبيب احلكم‪.‬‬\n\n\n\n\n    ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بقتــل آخــر غيلــة‬\n    ‫بطعنــه بســكني عــدة طعنــات وهــو نائــم وطلــب إثبــات مــا أســند إليــه‬\n    ‫وإقامــة حــد الغيلــة عليــه ‪ -‬حيــث تلقــت الشــرطة بالغــا عــن قيــام املدعــى‬\n    ‫عليــه بطعــن أحــد الســاكنني معــه يف ســكن العمــال عــدة طعنــات‬\n    ‫تــويف علــى إثرهــا يف املستشــفى ‪ -‬وقــد جــرى اســتجواب بقيــة العمــال‬\n    ‫فأفــاد مجموعــة منهــم مبشــاهدتهم لــه وهــو يطعــن املجنــي عليــه ‪ ،‬قــرر‬\n    ‫املدعــى عليــه يف بدايــة احملاكمــة بأنــه مريــض ويعانــي مــن ضعــف يف‬\n    ‫الذاكــرة وال يذكــر مــا حصــل معــه وتنتابــه حــاالت جنــون وأن املجنــي‬\n\n‫‪5‬‬\n\f‫عليــه صديقــه وليــس بينهمــا عــداوة وال يعلــم لــم قبضــت عليــه الشــرطة‬\n‫وإمنــا أخبــر بأنــه متهــم يف قتــل شــخص وأفــادت التقاريــر الطبيــة إصابــة‬\n‫املدعــى عليــه مبــرض عقلــي هــو الفصــام مــع أعــراض جانبيــة وأنــه يعاني‬\n‫مــن مرضــه قبــل وقــوع اجلرميــة كمــا أوصــت اللجنــة الطبيــة تخفيــف‬\n‫املســؤولية اجلنائيــة عنــه ولتعلــق املطالبــة باحلــق العــام ‪ ،‬وألن القاتــل‬\n‫واملقتــول مــن جنســية واحــدة وافــدة مــن بلــدة واحــد ولعدم مراجعــة أولياء‬\n‫الــدم طيلــة الفتــرة املاضيــة ولئــا يتأخــر نظــر هــذه القضيــة وأطرافهــا‬\n‫مــن غيــر الســعوديني ومراعــاة حلــال املدعــى عليــه الصحيــة ومــا ينتــج عــن‬\n‫طــول ســجنه مــن أضــرار بالغــه وفيــه تأخيــر للحقــوق اخلاصــة ال ســيما‬\n‫وأن أوليــاء الــدم أجانــب ويقيمــون خــارج البــاد ‪ ،‬وألن املدعــى عليــه‬\n‫ناقــص األهليــة وفقــا ملــا جــاء يف التقاريــر الطبيــة قــررت احملكمــة مــا‬\n‫يلــي ‪ :‬أوال ‪ :‬درء حــد احلرابــة عــن املدعــى عليــه لعــدم كمــال أهليتــه ‪.‬‬\n‫ثانيــا ‪ :‬تعزيــره لقــاء مــا نســب إليــه للحــق العــام بســجنه خمــس ســنوات‬\n‫وجلــده أربعمئــة وخمســن جلــدة مفرقــة علــى ســت دفعــات متســاوية قــدر‬\n‫كل دفعــة خمســة وســبعون جلــدة وبــن كل دفعــة والتــي تليهــا خمســة‬\n‫عشــر يومــا ‪ .‬ثالثــا ‪ :‬تســليم املدعــى عليــه بعــد إنفــاذ احلكــم الســابق‬\n‫لســلطات بــاده يف باكســتان لتمكــن أوليــاء الــدم مــن مخاصمتــه يف‬\n‫احلــق اخلــاص ومبــا ذكــر كلــه حكمنــا وبعــرض احلكــم علــى الطرفني‬\n‫أعتــرض عليــه املدعــي العــام وطلــب عــرض احلكــم علــى محكمــة‬\n‫اإلســتئناف لتدقيــق احلكــم مكتفيــا مبــا يف أوراق املعاملــة أمــا املدعــى‬\n‫عليــه فهــز رأســه وابتســم فكــرر املترجــم الســؤال عــن رأيــه يف احلكــم‬\n         ‫فقــال موافــق عليــه ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                     ‫‪6‬‬\n\f    ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن ‪1429/11/26‬ه ـ لدينــا نحــن‬\n    ‫القضــاة يف احملكمــة العامــة بالدمــام ‪...........‬و ‪........... ...........‬و ‪...........‬‬\n    ‫بنــاء علــى مــا وردنــا مــن فضيلــة الرئيــس برقــم وتاريــخ ‪1429/7/25‬ه ـ‬\n    ‫بخصــوص دعــوى املدعــي العــام ضــد ‪ ...........‬وهــذا نصهــا بصفتــي‬\n    ‫مدعيــا عامــا يف دائــرة اإلدعــاء العــام مبدينــة الدمام أدعي علــى ‪........... :‬‬\n    ‫البالــغ مــن العمــر ( ‪ ) 26‬عامــا مســلم الديانــه غيــر محصــن باكســتاني‬\n    ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ( ‪ )...........‬قبــض عليــه بتاريــخ‬\n    ‫‪1428/9/20‬ه ـ وأحيــل إلــى شــعبة إصالحيــة الدمــام مبوجــب مذكــرة‬\n    ‫التوقيــف رقــم ( ‪ )...........‬وتاريــخ ‪1428/10/16‬ه ـ وباإلطــاع علــى‬\n    ‫احملضــر املعــد مــن قبــل رجــال الضبــط اجلنائــي بشــرطة محافظــة‬\n    ‫اخلفجــي تبــن أنــه يف يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ يف متــام‬\n    ‫الســاعة الثالثــة والثلــث عصــرا تبلغــت غرفــة العمليــات بشــرطة محافظــة‬\n    ‫اخلفجي عن قيام املدعى عليه بطعن زميله املدعو ‪........... /‬باكســتاني‬\n    ‫اجلنســية عــدة طعنــات بســكني كانــت بحوزتــه وذلــك أثنــاء تواجدهمــا‬\n    ‫مبقــر ســكنهما الواقــع بحــي ‪...........‬وأن املصــاب مت نقلــه ملستشــفى‬\n    ‫‪......................‬لعالجــه وباإلنتقــال ملســرح اجلرميــة واملعاينــة اتضــح أنــه يقــع‬\n    ‫بحــي ‪...........‬وبالتحديــد خلــف مجمــع ‪...........‬للمــواد الغذائيــة مــن اجلهــة‬\n    ‫الشــرقية وهــو عبــارة عــن كامــب ســكني لعمــال شــركة ‪...........‬وهــذا‬\n    ‫الكامــب مكــون مــن مجموعــة مــن الغــرف واتضــح أن مســرح احلــادث‬\n    ‫يقــع بالغرفــة رقــم ‪...........‬وهــذه الغرفــة يســكن بهــا ثمانيــة أشــخاص‬\n    ‫جميعهــم مــن اجلنســية الباكســتانية ومــن ضمنهــم اجلانــي واملجنــي عليــه‬\n\n‫‪7‬‬\n\f‫وبالدخــول داخــل الغرفــة اتضــح أن مســاحتها ( ‪ ) 4 , 5‬متــر وحتتــوي‬\n‫علــى عــدد أربعــة أســره ( ذات الدوريــن ) واتضــح أن الســرير اخلــاص‬\n‫باجلانــي هــو الســرير الثانــي باجلهــة الشــمالية بالســرير األســفل وســرير‬\n‫املجنــي عليــه هــو باجلهــة الغربيــة بالســرير األســفل وقــد شــوهد علــى‬\n‫أرضيــة الغرفــة املفروشــة بقــع دمويــة كبيــرة متناثــرة مــن ســرير املجنــي‬\n‫عليــه حتــى بــاب الغرفــة مــن الداخــل كمــا شــوهد آثــار دم علــى املرتبــه‬\n‫اخلاصــة بســرير املجنــي عليــه وبإجــراء التفتيــش الدقيــق للغرفــة كاملــة‬\n‫عثرنــا علــى ســكني حتمــل نفــس الشــعار ( ‪ ( ) Solinqen‬جــرى‬\n‫حتريزهــا ) وباإلنتقــال ملستشــفى ‪...........‬ملعاينــة اجلثــة شــوهدت جثــة‬\n‫لرجــل يف العقــد الرابــع مــن العمــر يدعــى ‪.........../‬باكســتاني اجلنســية‬\n‫وتبــن مــن خــال املعاينــة وجــود إحــدى عشــرة طعنــة يف أماكــن متفرقــة‬\n‫مــن محيــط الصــدر مــن األمــام واخللــف والذراعــن أحجامهــا مختلفــة‬\n‫ومنهــا مــا هــو نافــذ ومنهــا مــا هــو ســطحي كمــا شــوهد طعنــة أســفل‬\n‫القفــص الصــدري مــن األمــام وبالتحديــد يف اجلهــة اليمنــى أســفل الثــدي‬\n‫األميــن نافــذة وطولهــا حوالــي ‪13‬ســم وعــرض ‪ 5‬ســم كمــا متــت معاينــة‬\n‫املالبــس التــي كان يرتديهــا املجنــي عليــه وشــوهد عليهــا آثــار دمــاء‬\n‫وقــد جــرى تعميــم البحــث والتحــري عــن اجلانــي ‪........... /‬بنــاء علــى‬\n‫األوصــاف التــي أدلــى بهــا زمــاؤه وشــهود الواقعــة وبعــون اهلل مت القبــض‬\n‫علــى املذكــور مــن قبــل دوريــات البحــث اجلنائــي أثنــاء محاولتــه اخلــروج‬\n‫مــن حي‪...........‬حلــي ‪ ...........‬وكان يرتــدي نفــس املالبــس التــي كان‬\n‫يرتديهــا أثنــاء تنفيــذ اجلرميــة حيــث شــوهد آثــار دم علــى قميصــه وكان‬\n‫يف حالــة ارتبــاك وبضبــط إفــادات املشــمولني بالتحقيــق ‪ -1 :‬بضبــط‬\n‫أقــوال املبلــغ ‪........... /‬باكســتاني اجلنســية أفــاد أنــه بحوالــي الســاعة‬\n\n\n                                                                                    ‫‪8‬‬\n\f    ‫الثالثــة مــن عصــر يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وأثنــاء وجــوده‬\n    ‫داخــل غرفتــه اخلاصــة ســمع صــوت صيــاح داخــل إحــدى الغــرف‬\n    ‫بالكامــب الــذي يوجــد فيــه أكثــر مــن غرفــة فخــرج وشــاهد زميلــه‬\n    ‫املدعــو ‪........... /‬يطلــب منــه املســاعدة وذلــك لكــون املدعــو ‪........... /‬‬\n    ‫قــام باإلعتــداء علــى زميلهــم املدعــو ‪........... /‬وبالفعــل ذهــب معــه وشــاهد‬\n    ‫املتهــم ‪........... /‬داخــل الغرفــة ويقــوم بطعــن املجنــي عليــه بســكني‬\n    ‫كانــت بحوزتــه حيــث طعنــه مرتــن أمامــه وبعــد أن شــاهده املتهــم حاول‬\n    ‫طعنــه فقــام بالهــروب إلــى كامــب تابــع لشــركة ‪...........‬يقــع بنفــس‬\n    ‫احلــي وأبلــغ رجــال الدوريــات األمنيــة املوجوديــن هنــاك حلراســة املوقــع‬\n    ‫وبعــد حضــوره مــع الدوريــة اتضــح أن زميلــه املتهــم هــرب مــن املوقــع وقــد‬\n    ‫قــام بإســعاف زميلــه ‪ ...........‬ملستشــفى ‪ -2 ............‬بضبــط أقــوال ‪/‬‬\n    ‫‪......................‬باكســتاني اجلنســية أفــاد أنــه يف يــوم الواقعــة حضــر بعــد‬\n    ‫خــروج املتهــم خــارج الغرفــة وكانــت الســكني بيــده وقــد قــام مجموعــة‬\n    ‫مــن زمالئــه بالقبــض علــى املتهــم مــن اخللــف وقــام هــو بــدوره بطلــب‬\n    ‫الســكني منــه فأعطــاه إياهــا حيــث قــام بلمســها بيــده وحذفهــا وحــاول‬\n    ‫القبض عليه إال أنه هرب ‪ -3 .‬بضبط إفادة املقيم ‪........... /‬باكستاني‬\n    ‫اجلنســية أفــاد أنــه عنــد عودتــه مــن عملــه هو وزمــاؤه كل مــن ‪........... :‬و‬\n    ‫‪...........‬و ‪...........‬و ‪...........‬وكانــت الســاعة الثانيــة والنصــف بعــد الظهــر‬\n    ‫وقــد خلــد إلــى النــوم هــو وجميــع زمالئــه عــدا ‪...........‬الــذي لــم ينم وكان‬\n    ‫جالســا علــى ســريره وبعــد نومهــم بدقائــق ســمع صــوت صيــاح داخــل‬\n    ‫الغرفــة وعندمــا اســتيقظ اتضــح لــه بــأن الــذي يصيــح زميلــه ‪...........‬‬\n    ‫حيــث شــاهد ‪...........‬وبيــده ســكني ويقــوم بطعــن ‪...........‬وهــو مســتلق‬\n    ‫علــى ســريره وقــد شــاهد املتهــم يقــوم بطعنــه أربــع طعنــات جميعهــا يف‬\n\n\n‫‪9‬‬\n\f‫صــدره وذراعيــه ‪ -4 .‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية‬\n‫أفــاد بأنــه يف يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وبعــد عودتــه مــن‬\n‫عملــه هــو وزمــاؤه كل مــن ‪...........‬و ‪...........‬و ‪...........‬و ‪...........‬وبعــد‬\n‫دخولهــم لغرفتهــم التــي يســكنون بهــا خلــدوا جميعــا للنــوم على أســرتهم‬\n‫عــدا ‪...........‬الــذي كان جالســا علــى ســريره وبعــد دقائــق مــن نومــه‬\n‫اســتيقظ علــى صــوت صيــاح وشــاهد ‪...........‬يقــوم بطعــن زميلهــم ‪...........‬‬\n‫وهــو مســتلق علــى ســريره عــدة طعنــات بصــدره وعلــى ذراعــه األيســر‬\n‫وقــد هــرب خــارج الغرفــة خوفــا علــى حياتــه ثــم بعــد ذلــك خــرج ‪...........‬‬\n‫والســكني بيــده ومت القبــض عليــه مــن قبــل زمالئهــم بالكامــب الذيــن‬\n‫قامــوا بأخــذ الســكني مــن يــده ‪ -5 .‬بضبــط إفــادة املقيــم ‪........... /‬‬\n‫باكســتاني اجلنســية أفــاد بأنــه حوالــي الســاعة الثانيــة والنصــف مــن‬\n‫يــوم الثالثــاء املوافــق ‪1428/9/20‬ه ـ وعنــد عودته مــن عمله هو وزمالئه‬\n‫كل مــن ‪........... :‬و ‪ ...........‬و ‪...........‬و ‪...........‬وعنــد دخولهــم الغرفــة‬\n‫خلــدوا للنــوم جميعــا عــدا ‪...........‬حيــث كان جالســا وبعــد أن اســتغرق‬\n‫يف النــوم ســمع صــوت صيــاح داخــل الغرفــة واســتيقظ وشــاهد ‪...........‬‬\n‫يقــوم بطعــن ‪...........‬وهــو مســتلق علــى ســريره حيــث شــاهده وهــو يقــوم‬\n‫بطعنــه عــدة طعنــات متفرقــة جميعهــا بصــدره وبطنــه وقــد خــرج مــن‬\n‫الغرفــة خوفــا علــى حياتــه ‪ -6 .‬بضبــط إفادة املقيم ‪........... /‬باكســتاني‬\n‫اجلنســية أفــاد بأنــه أثنــاء وجــوده بغرفتــه ســمع صــوت زمالئــه بالكامــب‬\n‫وخــرج وشــاهد مجموعــة كبيــرة مــن العمــال أمــام غرفــة ‪...........‬وكان‬\n‫‪...........‬أمــام الغرفــة وبيــده ســكينا وقــد قــام مبســكه مــن اخللــف‬\n‫وتثبيتــه ثــم حضــر أحــد العمــال وســحب الســكني مــن يــده ورماهــا‬\n‫داخــل الغرفــة وبعــد ذلــك شــاهد ‪...........‬ســاقطا داخــل الغرفــة وينــزف‬\n\n\n                                                                                        ‫‪10‬‬\n\f     ‫دمــا ‪ -7 .‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية أفــاد بأنــه‬\n     ‫يســكن بالغرفــة التــي يســكن بهــا املتهــم واملجنــي عليــه وخمســة مــن‬\n     ‫زمالئــه جميعهــم مــن نفــس اجلنســية وإجمالــي عددهــم ثمانيــة وانــه عنــد‬\n     ‫عودتــه مــن عملــه ذلــك اليــوم كانــت الســاعة الثانيــة وخمســا وأربعــن‬\n     ‫دقيقــة مســاء وعنــد دخولــه للغرفــة شــاهد زمالئــه كال مــن ‪...........‬و‬\n     ‫‪...........‬و ‪...........‬و ‪...........‬جميعهــم نائمــن علــى أســرتهم أمــا ‪...........‬‬\n     ‫فــكان مســتلقيا علــى ســريره ولكنــه ليــس نائمــا فقــام بالذهاب لقصد‬\n     ‫اإلســتحمام وبعــد عودتــه شــاهد جميــع زمالئــه خــارج الغرفــة و‪...........‬‬\n     ‫ســاقط داخــل الغرفــة وينــزف دمــا وأنــه ســألهم عــن املتســبب يف ذلــك‬\n     ‫فأفــادوه بــأن ‪...........‬هــو مــن قــام بطعنــه وأنــه الذ بالفــرار ‪ -8‬بضبــط‬\n     ‫إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية أفــاد بأنــه حضــر مــن دوامــه‬\n     ‫ذلــك اليــوم حوالــي الســاعة الثالثــة إال عشــر دقائــق مســاء ووجــد زمــاءه‬\n     ‫ال مــن ‪...........‬و ‪...........‬و ‪...........‬و‪.............‬و ‪...........‬داخــل الغرفــة‬\n                                                                                          ‫ك َ‬\n     ‫وكانــوا جميع ـ َا نائمــن عــدا ‪...........‬الــذي كان مســتلقي َا علــى ســريره‬\n     ‫ويقــوم بشــرب الدخــان كونــه غيــر صائــم وقــام بنــزع مالبســه والذهــاب‬\n     ‫لــدورات امليــاه لقصــد اإلســتحمام وبعــد عودتــه شــاهد زميلــه ‪...........‬‬\n     ‫ســاقط َا داخــل الغرفــة وينــزف دم ـ َا وشــاهد املتهــم وهــو يهــرب خــارج‬\n     ‫الكامــب وقــد أخبــره زمــاؤه املوجوديــن بــأن ‪...........‬هــو مــن قــام‬\n     ‫باإلعتــداء عليــه ‪ -9‬بضبــط إفــادة املقيــم ‪........... /‬باكســتاني اجلنســية‬\n     ‫أفــاد أنــه يف يــوم احلادثــة رجــع مــن عملــه قرابــة الســاعة الثانيــة والنصــف‬\n     ‫ال مــن ‪...........‬و‪...........‬و‪...........‬وقــد‬\n                                                   ‫مســاء ًا ووجــد بالغرفــة زمــاءه ك َ‬\n     ‫قــام بتبديــل مالبســه ثــم خــرج فــور َا إلــى املســجد وعنــد عودتــه مــن‬\n     ‫الصــاة شــاهد مجموعــة كبيــرة مــن العمــال أمــام الغرفــة التي يســكن‬\n\n\n‫‪11‬‬\n\f‫بهــا هــو وزمــاؤه وهنــاك دم داخــل الغرفــة وقــد أخبــره زمــاؤه بــأن‬\n‫‪...........‬قــام بطعــن ‪...........‬وأنهــم قامــوا بإســعافه قبــل حضــوره وأن‬\n‫‪...........‬هــرب مــن املوقــع وأضــاف بــأن ‪...........‬خــال شــهر رمضــان ال‬\n‫يصــوم ويقــوم بشــرب الدخــان بشــكل مســتمر وبإســتجواب املتهــم ‪/‬‬\n‫‪ .....‬أقــر بأنــه يســكن مــع ‪...........‬يف غرفــة واحــدة ومعــه ســتة آخــرون‬\n‫وأنــه بعــد عودتــه مــن عملــه حوالــي الســاعة الثانيــة والنصــف ظهــر َا برفق‬\n‫زمالئــه كل مــن ‪........... /‬و‪...........‬و‪...........‬و‪...........‬وبعــد دخولهــم‬\n‫لغرفهــم التــي يســكنون بهــا خلــد جميــع زمالئــه للنــوم علــى أســرتهم‬\n‫وهــو لــم ينــم حيــث كان جالس ـ َا علــى ســريره وقــد فكــر أن يقــوم‬\n‫باإلعتــداء علــى ‪...........‬كــون املذكــور دائمـ َا يســتهتر بــه ويتلفــظ عليــه‬\n‫بألفــاظ بذيئــة منهــا ‪ :‬يتهمــه بأنــه (‪ )......‬وأنــه شــخص مجنــون ولذلــك‬\n‫قــام بفتــح شــنطته اخلاصــة بــه والتــي كانــت حتــت ســريره ثــم أخــرج منهــا‬\n‫ســكين ًا كانــت بحوزتــه وبعــد ذلــك قــام باإلعتــداء علــى ‪...........‬أثنــاء‬\n‫نومــه حيــث قــام بطعنــه عــدة طعنــات جميعهــا يف منطقــة الصــدر والبطن‬\n‫والذراعــن حتــى ســقط علــى األرض وأن جميــع زمالئــه اســتيقظوا مــن‬\n‫نومهــم ثــم هربــوا خــارج الغرفــة وبعــد تنفيــذ جرميتــه قــام باخلــروج خــارج‬\n‫الغرفــة والســكني بيــده وقــد قــام زمــاؤه املوجودون بالســكن بالقبض‬\n‫عليــه وســحب الســكني منــه وأن مــن قــام بأخذهــا منه هو زميلــه ‪...........‬‬\n‫الــذي يســكن بالغرفــة رقــم ‪...........‬بنفــس الكامــب ثــم بعــد ذلــك هــرب‬\n‫مــن املوقــع خوفـ ًا مــن العقوبــة حتــى مت القبــض عليــه داخــل حــي ‪...........‬‬\n‫وأنــه معتــرف بقتــل املذكــور والتســبب يف وفاتــه ويتحمــل مســئولية‬\n‫جميــع مــا حــدث وأنــه ليــس لــه شــريك مــن قريــب أو بعيــد يف تنفيــذ‬\n‫اجلرميــة ولــم يحرضــه أحــد علــى ذلــك وأن الســبب الــذي أدلــى بــه هــو مــا‬\n\n\n                                                                                       ‫‪12‬‬\n\f     ‫دفعــه لقتــل املذكــور وال يوجــد أي ســبب آخــر كمــا أنــه ال يعانــي مــن‬\n     ‫أي مــرض نفســي أو صحــي ولــم يكــن حتــت تأثيــر أي ممنوعــات بــل‬\n     ‫كان بكامــل قــواه العقليــة وأنــه نــادم كل النــدم علــى ما فعله ومســتعد‬\n     ‫لتمثيــل اجلرميــة وصــادق علــى أقوالــه شــرع ًا وانتهــى التحقيــق علــى اتهــام‬\n     ‫املقيــم ‪........... /‬بقتــل املدعــو ‪...................... /‬قتــل غيلــة وذلــك بطعنــه‬\n     ‫بســكني عــدة طعنــات وهــو نائــم وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬‬\n     ‫إقــراره املصــدق شــرع ًا واملــدون علــى الصفحــة رقــم (‪ )3-2‬مــن ملــف‬\n     ‫التحقيــق رقــم (‪ )3‬علــى اللفــة رقــم (‪ -2 )3‬مــا ورد يف أقــوال الشــهود‬\n     ‫املدونــة علــى الصفحــات رقــم (‪ )4-2‬مــن ملــف التحقيــق رقــم (‪-3 )4‬‬\n     ‫محضــر االنتقــال والقبــض املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪-2‬‬\n     ‫‪ )6‬مــن ملــف التحقيــق رقــم (‪ )5‬واملرفــق علــى اللفــة رقــم (‪ -4 )5‬التقريــر‬\n     ‫الطبــي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )65‬و (‪ )66‬و (‪-69‬‬\n     ‫‪ -5 )75‬تقريــر األدلــة اجلنائيــة املنــوه عنهــا واملرفقــة علــى اللفــة رقــم‬\n     ‫(‪ -6 )6( )59( )57( )54-53‬محضــر متثيــل اجلرميــة مــن قبــل املتهــم مــع‬\n     ‫شــريط الفيديــو واملــدون علــى الصفحــة رقــم (‪ )8‬مــن ملــف التحقيــق رقــم‬\n     ‫(‪ )5‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه على ســوابق مســجلة‬\n     ‫وحيــث أن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫مــن قتــل نفــس معصومــة غيلــة فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد الغيلــة وفقـ ًا للمــادة األولــى مــن‬\n     ‫قــرار هيئــة كبــار العلمــاء رقــم (‪ )38‬وتاريــخ ‪1395/8/11‬ه ـ الــوارد‬\n     ‫باألمــر الســامي رقــم (‪ )27467‬يف ‪1395/9/20‬ه ـ ( احلــق اخلــاص ما زال‬\n     ‫قائم ـ ًا ) ثــم يف جلســة أخــرى حضــر املدعــى عليــه وتليــت عليــه الدعــوى‬\n     ‫عــن طريــق مترجــم احملكمــة ‪...........‬فقــال أنــا مريــض ومتعــب وقــد‬\n\n\n‫‪13‬‬\n\f‫حضــرت للتــو مــن املستشــفى فرفعــت اجللســة ثــم يف جلســة أخــرى وردت‬\n‫إفــادة أن املدعــى عليــه منــوم يف املستشــفى ثــم يف جلســة أخــرى حضــر‬\n‫املدعــى عليــه ومت ســؤاله عــن الدعــوى فأجــاب عــن طريــق املترجــم‬\n‫املذكــور إننــي أعمــل يف شــركة يف محافظــة اخلفجــي وأســكن يف‬\n‫غرفــة فيهــا ثمانيــة أشــخاص ومــن ضمنهــم ‪ ...........‬الباكســتاني وهــو‬\n‫صديــق لــي وليــس بينــي وبينــه إال اخليــر وال أذكــر أي شــيء عمــا ورد يف‬\n‫الدعــوى بخصــوص قتــل ‪...........‬حيــث أننــي مصــاب مبــرض عقلــي‬\n‫وكنــت أراجــع املستشــفى واســتخدم العــاج وعنــدي ضعــف يف‬\n‫الذاكــرة وحتصــل لــي فتــرات جنــون ال أعلــم مــاذا أعمــل فيهــا وأن‬\n‫الشــرطة قبضــت علـ ّـي وأخبرونــي بأنــي متهــم يف قضيــة قتــل وال أعلــم‬\n‫مــاذا يقصــدون ثــم حصــل بعــد ذلــك حتقيــق معــي وال أذكــر مــاذا حصــل‬\n‫يف التحقيــق هــذا مــا ذكــره املدعــى عليــه ولــذا رأينــا إحالــة املدعــى‬\n‫عليــه إلــى مستشــفى نفســي للكشــف عليــه وتزويدنــا بتقريــر طبــي عــن‬\n‫حالتــه العقليــة ورفعــت اجللســة حتــى رجــوع اجلــواب ثــم وردنــا التقريــر‬\n‫الطبــي الصــادر مــن مستشــفى الصحــة النفســية بالطائــف رقــم‪...........‬يف‬\n‫‪1431/4/27‬ه ـ ونــص املقصــود منــه أمــا مــا يخــص املســؤولية اجلنائيــة‬\n‫وبعــد اإلطــاع علــى ملــف التحقيــق وتفاصيــل القضيــة فتــرى اللجنــة‬\n‫الطبيــة النفســية اجلنائيــة أنــه نظــر ًا لوجــود املــرض العقلــي الفصــام ومــا‬\n‫يصاحبــه مــن أفــكار ومعتقــدات مرضيــة خاطئــة والتــي تؤثــر يف‬\n‫الســلوك واحلكــم علــى األمــور بشــكل ســليم وعــدم تقديــر النتائــج‬\n‫وعواقــب األفعــال ونتيجــة إلضطــراب حالــة املذكــور العقليــة قبــل وأثناء‬\n‫ارتكابــه اجلرميــة فــإن ذلــك يخفــف مــن املســؤولية اجلنائيــة حيــال مــا‬\n‫أقــدم عليــه يف القضيــة احلاليــة ويجعلهــا مســؤولية جزئيــة أي يتحــول‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫القتــل العمــد إلــى القتــل اخلطــأ أعضــاء اللجنــة الطبيــة النفســية اجلنائيــة‬\n     ‫ثــم يف جلســة أخــرى حضــر املدعــى عليــه وأفــاد عــن طريــق مترجــم‬\n     ‫ا احلمــد هلل حتســنت حالتــي وقــد قمــت بقتــل املجنــي‬       ‫احملكمــة قائ ـ ً‬\n     ‫عليــه ‪...........‬وال أذكــر بــأي شــيء قتلتــه بســكني أو عصــا ال أذكــر‬\n     ‫وكان املجنــي عليــه يســكن معــي وصديقــي وكان ميــزح معــي وميــد‬\n     ‫يــده علــى مؤخرتــي وأنــا أقــول إننــي رجــل وال يصلــح هــذا العمــل وتأثــرت‬\n     ‫بســبب هــذا الفعــل منــه وأصبحــت أفكــر فيــه ثــم تكــرر منــه هــذا‬\n     ‫الفعــل وكذلــك الســب والشــتم ملــدة تقــارب ســتة أشــهر وقــد صبــرت‬\n     ‫عليــه لكونــه ســاعدني عنــد قدومــي مــن باكســتان وقبــل حادثــة القتــل‬\n     ‫حضــر إلـ ّـي املجنــي عليــه يف غرفتــي وملــس مؤخرتــي وغضبــت غضب ـ ًا‬\n     ‫شــديد ًا وكان الوقــت قبيــل العصــر يف نهــار رمضــان وأنــا لــدي مــرض‬\n     ‫احتــاج إلــى شــرب املــاء ولــم أكــن صائم ـ ًا أمــا هــو فــا أعلــم وقمــت‬\n     ‫باإلعتــداء عليــه ال أذكــر بــأي آلــة وبعدهــا علمــت أنــه تــويف وتأســفت‬\n     ‫علــى موتــه وقــد نصحنــي أحــد العمــال وقــت اجلرميــة بالهــروب فهربــت‬\n     ‫داخــل مدينــة اخلفجــي يف إحــدى العمائــر حتــت اإلنشــاء ثــم احتجــت إلــى‬\n     ‫املــاء وخرجــت ويف أثنــاء شــربي حضــرت الهيئــة فقبضــت علـ ّـي ثــم حولــت‬\n     ‫إلــى الشــرطة وحقــق معــي وقــد ســمعت أن ورثــة املجنــي عليــه قــد تنازلــوا‬\n     ‫هــذه إجابتــي فجــرى ســؤال املدعــي العــام البينــة علــى الدعــوى فقــال مــا‬\n     ‫جــاء يف الئحــة الدعــوى ومــن ذلــك اعتــراف املدعــى عليــه والشــهود‬\n     ‫ورفعــت اجللســة لإلطــاع علــى املعاملــة ثــم يف جلســة أخــرى فتحــت يــوم‬\n     ‫اإلثنــن ‪1433/5/24‬ه ـ لدينــا نحــن القضــاة يف احملكمــة العامــة‬\n     ‫بالدمــام ‪...........‬خلــف القاضــي ‪......................‬و ‪...........‬خلــف القاضــي‬\n     ‫‪...........‬و ‪......................‬خلــف القاضــي‪ ...........‬حضــر املدعــي العــام‬\n\n\n‫‪15‬‬\n\f‫‪......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬‬\n‫وحضــر حلضــوره املدعــى عليــه ‪...........‬وقــد مت دراســة مــا ســبق ضبطــه‬\n‫وبعرضــه علــى املدعــى عليــه عــن طريــق مترجــم احملكمــة ‪...........‬‬\n‫باكســتاني اجلنســية ومصــرح لــه باإلقامــة رقــم ‪...........‬وســؤاله عمــا‬\n‫ســبق ضبطــه عــن طريــق املترجــم ضحــك ولــم يجــب بشــيء ســوى بذكــر‬\n‫اســمه وكان قــد طلــب إعــادة فحــص املدعــى عليــه عن طريق مستشــفى‬\n‫الصحــة النفســية بالطائــف مــن قبــل جلنــه مختصــه واإلفــادة عمــا يلــي ‪( :‬‬\n‫أوال ‪ :‬هــل ميكــن معرفــة حالــة الســجني العقليــة وقــت وقــوع اجلرميــة‬\n‫ومبعنــى آخــر هــل كان وقــت اجلرميــة حتــت تأثيــر املــرض املذكــور ‪.‬‬\n‫ثانيــا ‪ :‬هــل يعتبــر الســجني املذكــور واحلــال مــا ذكــر مســؤول عــن‬\n‫تصرفاتــه ‪ .‬ثالثــا ‪ :‬هــل املــرض املذكــور وقتــي بحيــث يتــردد علــى‬\n‫صاحبــه مــن وقــت آلخــر أو هــو دائــم ‪ .‬رابعــا ‪ :‬متــى تاريــخ هــذا املــرض‬\n‫كمــا قررنــا أن نظــر هــذه الدعــوى واحلكــم فيهــا متوقــف علــى اإلجابــة‬\n‫علــى تلــك األســئلة بــراءة للذمــة ) فوردنــا التقريــر الطبــي الصــادر مــن‬\n‫مستشــفى الصحــة النفســية بالطائــف برقــم‪...........‬يف ‪1432/2/2‬ه ـ‬\n‫ونــص احلاجــة منــه مــا يلــي ‪ ( :‬إحلاقــا لتقريرنــا الطبــي النفســي اجلنائــي‬\n‫رقم‪...........‬بتاريــخ ‪1431/4/27‬ه ـ والــذي أوضحنــا فيــه التالــي ‪ -1 :‬مت‬\n‫دخولــه اجلنــاح اجلنائــي لدينــا بتاريــخ ‪1430/5/17‬ه ـ يف قضيــة قتــل وقــد‬\n‫شــخصت حالتــه ( فصــام مــع أعــراض مزاجيــه ) وقــد بوشــر بالعــاج‬\n‫واســتقرت حالتــه وخــرج بتاريــخ ‪1430/7/26‬ه ـ ‪ -2 .‬عــرض املذكــور‬\n‫علــى اللجنــة الطبيــة النفســية اجلنائيــة لدينــا بتاريــخ ‪1432/2/11‬ه ـ‬\n‫وكانــت حالتــه مســتقرة علــى العــاج وشــخصت حالتــه ( فصــام مــع‬\n‫أعــراض مزاجيــه ) ‪ .‬القــرار والتوصيــات ‪ -1 .‬يعــود ملرجعــه مــع عــاج‬\n\n\n                                                                                     ‫‪16‬‬\n\f     ‫نفســي ملــدة أســبوعني عبــارة عــن ( ســيرنيز ‪ 5‬ملغ أقــراص بواقع قرصان‬\n     ‫صباحــا وقرصــان مســاء ‪ +‬ديباكــن ‪ 200‬ملــغ قــرص ثــاث مــرات‬\n     ‫يوميــا ‪ +‬كوجنتــن ‪ 2‬ملــغ قــرص صباحــا وقــرص مســاء ) علــى أن‬\n     ‫يراجــع أقــرب عيــادة نفســية ملرجعــه قبــل انتهــاء العــاج ‪ -2 .‬ردا علــى‬\n     ‫استفســار ناظــر القضيــة عــن إمكانيــة معرفــة حالــة الســجني وقــت‬\n     ‫وقــوع اجلرميــة يفيدكــم أن املذكــور عــرض علــى اللجنــة يف‬\n     ‫‪1430/5/17‬ه ـ وكانــت القضيــة حدثــت يف ‪1428/9/20‬ه ـ وقد رأت‬\n     ‫اللجنــة أن املذكــور عنــد عرضــه كان يعانــي مــن أعــراض واضحــة‬\n     ‫للمــرض العقلــي الذهانــي ( الفصــام ) وأعطــي العــاج الــازم وحتســنت‬\n     ‫حالتــه ‪ ،‬وذكــر الدوافــع وراء جرميتــه واألعــراض التــي كان يعانــي‬\n     ‫منهــا وقــت ارتــكاب اجلرميــة ‪ .‬وعنــد إطــاع اللجنــة علــى أقوالــه يف‬\n     ‫التحقيــق كانــت أقوالــه مطابقــة ألقوالــه احلاليــة ومبنيــة علــى توهمــات‬\n     ‫مرضيــة ال أســاس لهــا مــن الصحــة ( حســب مــا يتضــح مــن أقــوال زمالئــه‬\n     ‫يف الغرفــة ) حيــث كان يعتقــد أن املجنــي عليــه يفعــل الفاحشــة بــه وهــو‬\n     ‫نائــم وذكــر يف التحقيــق أن املجنــي عليــه يســبه أنــه ( ‪ ) .....‬وقــد حــذره‬\n     ‫أكثــر مــن مــره ثــم قــام بقتلــه ‪ ،‬وأفــاد أنــه يف تلــك الفتــرة كان يســمع‬\n     ‫أصــوات ال وجــود لهــا يف الواقــع تســبه وتشــتمه ( أي أنــه كان يعانــي مــن‬\n     ‫أعــراض مرضيــة قبــل وأثنــاء وبعــد جرميتــه وكان لتلــك األعــراض دورا‬\n     ‫فاعــا يف حــدوث اجلرميــة ) ممــا جعــل اللجنــة توصــي بتخفيــف املســئولية‬\n     ‫اجلنائيــة عنــه ‪ -3 .‬أمــا عــن مــرض الفصــام الــذي يعانــي منــه فهــو مــرض‬\n     ‫مزمــن ومســتمر يتحســن مــع العــاج وهــو قابــل لإلنتكاســه يف أي وقــت‬\n     ‫‪ ،‬وال تســتطيع اللجنــة الطبيــة النفســية اجلنائيــة حتديــد تاريــخ إصابتــه‬\n     ‫باملــرض العقلــي ولكــن يتضــح لهــا أن املذكــور كان يعانــي مــن مرضه‬\n\n\n‫‪17‬‬\n\f‫قبــل وقــوع اجلرميــة بنــاء علــى مــا رأتــه اللجنــة عنــد الكشــف احلالــي علــى‬\n‫املذكــور مــن أعــراض واضحــة للمــرض ومــا مت اإلطــاع عليــه مــن‬\n‫أقوالــه أثنــاء التحقيــق معــه يف قضيتــه احلاليــة ) وبتأمــل مــا ســبق ضبطــه‬\n‫تبــن أن اإلدعــاء العــام يطالــب بإقامــة حــد الغيلــه علــى املدعــى عليــه‬\n‫‪ ...........‬لقاء قتله ‪...........‬باكســتاني اجلنســية وأن املدعى عليه مســجون‬\n‫بســبب هــذه القضيــة منــذ تاريــخ ‪1428/10/16‬ه ـ وألن التقاريــر الطبية‬\n‫أثبتــت إصابــة املدعــى عليــه مبــرض عقلــي هــو الفصــام مــع أعــراض‬\n‫جانبيــة كمــا جــاء يف التقاريــر الطبيــة أن املدعــى عليــه كان يعانــي مــن‬\n‫مرضــه قبــل وقــوع اجلرميــة كمــا أوصــت اللجنــة الطبيــة تخفيــف‬\n‫املســؤولية اجلنائيــة عنــه وألن مــا يطالــب بــه املدعــي العــام إمنــا هــو للحــق‬\n‫العــام وألن القاتــل واملقتــول مــن جنســية واحــده وافــدة وألنــه لــم يراجــع‬\n‫طــوال املــدة الســابقة والتــي بلغــت نحــو خمــس ســنني مــن يطالــب باحلــق‬\n‫اخلــاص ولئــا يتأخــر نظــر هــذه القضيــة وأطرافهــا مــن غيــر الســعوديني‬\n‫ومراعــاة حلــال املدعــى عليــه الصحيــة ومــا ينتــج عــن طــول ســجنه مــن‬\n‫أضــرار بالغــه وفيــه تأخيــر للحقــوق اخلاصــة ال ســيما وأن أوليــاء الــدم‬\n‫أجانــب ويقيمــون خــارج البــاد لــكل ذلــك وألن املدعــى عليــه ناقــص‬\n‫األهليــة وفقــا ملــا جــاء يف التقاريــر الطبيــة قررنــا مــا يلــي ‪ :‬أوال ‪ :‬درأنــا‬\n‫حــد احلرابــة عــن املدعــى عليــه لعــدم كمــال أهليتــه ‪ .‬ثانيــا ‪ :‬تعزيــره لقــاء‬\n‫مــا نســب إليــه للحــق العــام بســجنه مــدة خمــس ســنوات وجلــده أربعمائــه‬\n‫وخمســن جلــده مفرقــه علــى ســت دفعــات متســاوية قــدر كل دفعــه‬\n‫خمســه وســبعون جلــده وبــن كل دفعــه والتــي تليهــا خمســة عشــر يومــا‬\n‫‪ .‬ثالثــا ‪ :‬تســليم املدعــى عليــه بعــد انفــاذ احلكــم الســابق لســلطات بــاده‬\n‫يف باكســتان لتمكــن أوليــاء الــدم مــن مخاصمتــه يف احلــق اخلــاص‬\n\n\n                                                                                          ‫‪18‬‬\n\f     ‫ومبــا ذكــر كلــه حكمنــا وبعــرض احلكــم علــى الطرفــن أعتــرض‬\n     ‫عليــه املدعــي العــام وطلــب عــرض احلكــم علــى محكمــة اإلســتئناف‬\n     ‫لتدقيــق احلكــم مكتفيــا مبــا يف أوراق املعاملــة أمــا املدعــى عليــه فهــز‬\n     ‫رأســه وابتســم فكــرر املترجــم الســؤال عــن رأيــه يف احلكــم فقــال‬\n     ‫موافــق عليــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبه وسلم ‪ .‬حرر يف ‪1433/5/24‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد ثــم انــه يف هــذا اليــوم الثالثــاء املوافــق ‪/14‬‬\n     ‫‪1434/5‬ه ـ وبعــد ورود املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n     ‫الشــرقية ومشــفوعها القــرار رقــم ‪ 34188914‬وتاريــخ ‪/1434 /4 /15‬‬\n     ‫ه ـ ومضمونــه املصادقــة علــى احلكــم وعليــه توقيــع اصحــاب الفضيلــة‬\n     ‫قضــاة االســتئناف ‪......................‬التوقيــع قاضــي اســتئناف ‪...........‬‬\n     ‫التوقيــع قاضــي اســتئناف ‪...........‬التوقيــع رئيس اســتئناف ‪......................‬‬\n     ‫التوقيــع رئيــس الدائــرة ‪...........‬التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434 /5 /14‬ه ـ‬\n\n\n\n\n‫‪19‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":5,"source_page_end":19,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"905df45af7ba73749b191c12fd4c6602a58a468e4e5bffbcddbce165de024106","normalized_text_hash":"d0b2b81a13fb054fd487083181f8e149ab764300652ac87b207c8f740fc6a592","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p5-33280585"},{"id":"d864f2a3-665d-5654-8d8d-cffc19e9e60c","document_type":"judgment","category":"judicial","subcategory":"general","title":"-املدعى عليه -خلاف بينهما وتهديده السابق ،أنكر املدعى عليه الدعوى ودفع بأنه كان حينها خارج مدينة الرياض ،بفحص الساح الذي ضبط مع املدعى عليه ومقارنته مع أظرف الطلقات الفارغة املرفوعة من موقع اجلرمية وقد ظهر بأن األظرف األربعة مطلقة من","document_number":"32203464","case_number":"36881","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/8/12","year":"1434","subject":"-املدعى عليه -خلاف بينهما وتهديده السابق ،أنكر املدعى عليه الدعوى ودفع بأنه كان حينها خارج مدينة الرياض ،بفحص الساح الذي ضبط مع املدعى عليه ومقارنته مع أظرف الطلقات الفارغة املرفوعة من موقع اجلرمية وقد ظهر بأن األظرف األربعة مطلقة من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 32203464 :‬تاريخه‪1432/8/12 :‬هـ‬\n                       ‫رقم الدعوى‪36881:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 349716‬تاريخه‪1433/1/12 :‬هـ‬\n\n\n‫قتــل ‪ ،‬شــروع يف قتــل ‪ ،‬حيــازة ســاح بــدون ترخيــص ‪ ،‬اســتخدام ســاح‬\n‫نــاري ‪ ،‬دعــوى عامــة وخاصــة ‪ ،‬حكــم بــرد الدعــوى ثــم الرجــوع عنــه ‪،‬‬\n‫مشــروعية االعتمــاد علــى قــرار أهــل اخلبــرة ‪ ،‬مشــروعية التعزيــر يف‬\n‫احلــق اخلــاص ‪ ،‬وجــود ســوابق قضائيــة‪ ،‬ثبــوت إدانــة ‪ ،‬تعزيــر بالســجن‬\n                                                                   ‫وجلــد‪.‬‬\n\n\n\n                                     ‫ما أشار له القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العام بقيــام املدعى عليه بالشــروع‬\n‫يف قتــل أخيــه بإطــاق عــدة طلقــات ناريــة عليــه وطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة حيــث تلقــت الشــرطة بالغــا مــن‬\n‫أحــد املواطنــن بســماعه ثــاث طلقــات ناريــة وباســتطالعه وجــد املجنــي‬\n‫عليــه علــى الرصيــف وباســتجواب املجنــي عليــه ألقــى التهمــة علــى أخيــه‬\n‫‪ -‬املدعــى عليــه ‪ -‬خلــاف بينهمــا وتهديــده الســابق‪ ،‬أنكــر املدعــى عليــه‬\n‫الدعــوى ودفــع بأنــه كان حينهــا خــارج مدينة الرياض‪ ،‬بفحص الســاح‬\n‫الــذي ضبــط مــع املدعــى عليــه ومقارنتــه مــع أظــرف الطلقــات الفارغــة‬\n‫املرفوعــة مــن موقــع اجلرميــة وقــد ظهــر بــأن األظــرف األربعــة مطلقــة مــن‬\n\n                                                                                     ‫‪20‬‬\n\f     ‫املســدس احملــرز املضبــوط بحــوزة املدعــى عليــه أمــا الظرفــان الفارغــان‬\n     ‫فهــي مطلقــة مــن ســاح نــاري واحــد ويطلــق عــادة مــن األســلحة مــن ذات‬\n     ‫العيــار‪ ،‬مت القبــض علــى املدعــى عليــه ومعــه ســيارة مســتأجرة والعثــور‬\n     ‫معــه يف ســيارته علــى املســدس املشــار لــه يف تقريــر األدلــة اجلنائيــة ‪،‬‬\n     ‫أنكــر املدعــى عليــه بــأن املســدس يعــود لــه ‪ ،‬وإلنــكار املدعــى عليــه‬\n     ‫دعــوى املدعــي العــام واخلــاص وملــا تضمنتــه شــهادة الشــاهدين ومحضــر‬\n     ‫االنتقــال مــن العثــور علــى ظــروف فارغــة ومــا تضمنــه خطــاب مديــر‬\n     ‫شــرطة احلــدود الشــمالية مــن العثــور علــى املســدس الــذي انطلقــت منــه‬\n     ‫األظــرف الفارغــة حســب قــرار األدلــة اجلنائيــة وكل مــا تقــدم يــورث‬\n     ‫الشــبهة القويــة نحــو املدعــى عليــه يف احلــق العــام إال أنــه ال ميكــن معهــا‬\n     ‫إثبــات احلــق اخلــاص ‪ ،‬لــذا فقــد قــررت احملكمــة مــا يلــي‪:‬أوال‪ /‬رد دعــوى‬\n     ‫املدعــي اخلــاص لعــدم كفايــة األدلــة‪ .‬ثانيــا‪ /‬توجيــه الشــبهة القويــة علــى‬\n     ‫قيــام املدعــى عليــه بإطــاق النــار علــى املجنــي عليــه وتعزيــره ألجلــه‬\n     ‫بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده ثالثمئــة جلــدة مفرفــة‬\n     ‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا‬\n     ‫عشــرة أيــام ‪ ،‬بعــرض احلكــم علــى املدعــي العــام قــرر عــدم القناعــة‬\n     ‫مكتفيــا بالئحــة الدعــوى كمــا قــرر املدعــي اخلــاص واملدعــى عليــه‬\n     ‫عــدم القناعــة وطلبــا متكينهمــا مــن تقــدمي الئحــة فأفهمــا بالتعليمــات ‪،‬‬\n     ‫عــادت القضيــة مــن محكمــة االســتئناف بــأن رد دعــوى املدعــي اخلــاص‬\n     ‫محــل نظــر لقــوة الشــبهة وطلبــت إمــا تقريــر عقوبــة يف احلــق اخلــاص أو‬\n     ‫زيــادة العقوبــة الصــادرة يف احلــق العــام وإيضــاح مــا للحــق العــام واخلــاص‪،‬‬\n     ‫لــم يحضــر املجنــي عليــه لعالجــه خــارج اململكــة ‪ ،‬وملــا جــاء يف أســباب‬\n     ‫احلكــم يقــوي جانــب املدعــي اخلــاص واليمــن تشــرع يف جانــب األقــوى‬\n\n\n‫‪21‬‬\n\f‫مــن املتداعيــن وألن املدعــي اخلــاص خــارج اململكــة ممــا يتعــذر معــه‬\n‫احلضــور ألداء اليمــن وألن احلــق اخلــاص ال يثبــت مبجــرد الشــبهة لــذا‬\n‫فقــد قــررت احملكمــة عــدم عدولهــا عمــا حكمــت بــه ســلفا ‪ ،‬عــادت‬\n‫القضيــة مــرة أخــرى مــن محكمــة االســتئناف بطلــب إعــادة النظــر مــرة‬\n‫أخــرى يف احلكــم ‪ ،‬قــرر القاضــي رجوعــه عــن الفقــرة األولــى والثانيــة‬\n‫مــن احلكــم ‪ ،‬وقــررت احملكمــة ثبــوت قيــام املدعــى عليــه بإطــاق النــار‬\n‫علــى املدعــي اخلــاص عــدة طلقــات أدت إلــى إصابتــه باإلصابــات املشــار‬\n‫لهــا يف التقريــر الطبــي املرفــق بــاألوراق وقــررت تعزيــره ألجلــه مبــا يلــي‪:‬‬\n‫أوال‪ /‬ســجن املدعــى عليــه ثــاث ســنوات وجلــده ثالثمئــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــرة أيــام وذلــك‬\n‫للحــق اخلــاص ‪ .‬ثاني ـاً‪ :‬ســجن املدعــى عليــه ســنتني مــن تاريــخ إيقافــه‬\n‫وجلــده مئتــي جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة‬\n‫بــن كل دفعــة واألخــرى عشــرة أيــام وبــن هــذا اجللــد واجللــد الــذي يف‬\n‫كمــت ‪ ،‬وعرضــه علــى‬       ‫األولــى مــن احلكــم عشــرة أيــام وبجميــع ذلــك َح َ‬\n‫املدعــى العــام قــرر بأنــه ال زال معترضـ ًا ‪ ،‬أمــا املدعــي اخلــاص واملدعــى‬\n‫عليــه فقــد قــررا عــدم القناعــة ورغبــا رفــع املعاملــة حملكمــة االســتئناف‬\n   ‫بــدون الئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزئيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالريــاض برقــم وتاريــخ ‪ 1431/12/22‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪ 1431/12/22‬هـ ففي يوم الثالثاء املوافق‪1432/03/12‬‬\n\n                                                                                       ‫‪22‬‬\n\f     ‫ه ـ أفتتحــت اجللســة الســاعة ‪ 1 : 30‬وفيهــا قــدم املدعــي العــام ‪.....‬دعــواه‬\n     ‫ضــد ‪..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقـ ـ ــم (‪ ).....‬قائــا‬\n     ‫يف دعــواه عليــه إنــه بتاريــخ ‪1431/9/29‬ه ـ تســلم مركــز شــرطة‬\n     ‫‪.....‬و‪ .....‬تقريــر إحــدى فــرق الدوريــات األمنيــة رقــم (‪ ).....‬املتضمــن أنــه‬\n     ‫أثنــاء قيــام الفرقــة بعملهــا تلقــت بالغــا عــن شــخص مصــاب بحــي ‪.....‬‬\n     ‫علــى شــارع ‪.....‬وعنــد انتقــال الفرقــة للموقــع افــاد املبلــغ ‪.....‬أنــه ســمع‬\n     ‫صــوت ثــاث طلقــات ناريــة وهــو بداخــل املســجد وبعــد خروجــه شــاهد‬\n     ‫الشــخص املصــاب علــى الرصيــف الــذي نقــل ملستشــفى امللــك فهــد‬\n     ‫للحــرس الوطنــي وعنــد انتقــال فرقــة األدلــة اجلنائيــة للموقــع وجــدت آثــار‬\n     ‫دمــاء وعــدد اربعــة مقذوفــات فارغــة ملســدس مــن نــوع ربــع وعــدد طلقتني‬\n     ‫فارغــة لســاح مــن نــوع رشــاش ‪.‬وبضبــط إفــادة املجنــى عليــه ‪..... /‬أفــاد‬\n     ‫بوجــود خــاف مــع أخيــه املتهــم منــذ فتــرة طويلــه ممــا دعــاه إلــى منــع‬\n     ‫اخــاه مــن دخــول منزلــه فقــام املتهــم باالتصــال عليه مرات عــدة وتهديده‬\n     ‫بقولــه لعبــارة( واهلل الفــري بطنــك والفقــع راســك ) وانقطــع عنــه منــذ‬\n     ‫ســنوات ولــم يشــاهده ويف مســاء يــوم ‪1431/9/29‬ه ـ وأثنــاء توجهــه مــن‬\n     ‫املنــزل إلــى املســجد إلداء صــاة العشــاء تفاجــأ بطلقــة فــوق راســه ومــن‬\n     ‫ثــم طلقــة أخــرى أصابتــه يف الفخــذ وســقط علــى األرض ثــم توالــت‬\n     ‫الطلقــات وهــو يتحاشــاها بيــده فأصابتــه عــدة طلقــات وشــاهد ســيارة‬\n     ‫صغيــرة ال يعــرف نوعهــا ولونهــا ســماوي ولــم يشــاهد مــن بداخلهــا‬\n     ‫ولكنــه ســمع مــن النســاء حولــه أن الســيارة بهــا اثنــان وصــدر بحقــه‬\n     ‫التقريــر الطبــي رقــم (‪ ).....‬وتاريــخ ‪1431/9/29‬ه ـ الصــادر مــن الشــئون‬\n     ‫الصحيــة باحلــرس الوطنــي املتضمــن إصابتــه بعشــرة جــروح قطعيــة اثنــان‬\n     ‫منهــا يف العضــد األميــن وأثنــان يف الصــدر مــن االمــام واخللــف وأثنــان يف‬\n\n\n‫‪23‬‬\n\f‫الفخــذ مــن األمــام واخللــف وإصابتــه بكســر يف منتصــف عظمــة الفخــذ‬\n‫وجــروح متعــددة يف األطــراف العلويــة والطــرف األميــن الســفلي واليــد‬\n‫اليســرى والصــدر ومــدة الشــفاء أكثــر مــن خمســة عشــريوما ‪.‬ويف متــام‬\n‫الســاعة السادســة وعشــرون دقيقــه مــن مســاء يــوم اخلميــس‬\n‫‪1431/9/30‬ه ـ قبــض علــى املتهــم مــن قبــل دوريــات حــرس احلــدود‬\n‫مبنطقــة احلــدود الشــمالية مبوقــع خفــي عــن األنظــار وبقيادتــه ســيارة‬\n‫مــن نــوع ‪ ....‬لونهــا فضــي وبتفتيــش الســيارة وجــد بهــا مســدس بــدون‬\n‫ترخيــص ملفــوف بعقــد اســتئجار الســيارة ومخبــأ أســفل مقــود الســيارة‬\n‫ومخــزن ســاح مســدس فــارغ وجــواز سفر‪.‬وبســماع شــهادة ‪..... /‬أفــاد‬\n‫أن عمــه املتهــم اتصــل عليــه يف مغــرب يــوم احلادثــة وســأله عــن منــزل عمــه‬\n‫املجنــى عليــه لكونــه انتقــل مــن بيتــه حديثــا وعندمــا ســأله عــن ســبب‬\n‫ذلــك قــال إن هنــاك رجــا يســأل عنــه وعنــد ســؤاله عــن هــذا الرجــل لــم‬\n‫يجبــه ثــم اتصــل عليــه بعــد ثلــث ســاعة وســأله هــل امــام منزلهــم ســيارة‬\n‫‪ ....‬وهــل لــون منزلهــم احمــر فقــال لــه ال ادري النــه يعلــم أنــه صاحــب‬\n‫ســوابق فقــال هــل هــم موجوديــن فأجابــه بأنــه ال يعلــم واغلــق اجلــوال ثــم‬\n‫ســمع بحادثــة اإلطــاق يف الســاعة الواحــدة ليــا ‪ .‬ومبضاهــاة األظــرف‬\n‫الفارغــة املضبوطــة يف مســرح اجلرميــة مــع الســاح املســدس املضبــوط‬\n‫مــع املتهــم تبــن مطابقــة ظرفــن فارغــن للســاح‪ .‬وبإســتجواب املتهــم ‪/‬‬\n‫أفــاد بعــدم وجــود خــاف مــع اخيــه املجنــى عليــه وأنــه لــم يشــاهده منــذ‬\n‫ســنتني وأنــه يف وقــت اإلطــاق كان يف القصيــم لكونــه خــرج مــن‬\n‫مدينــة الريــاض عصــر ذلــك اليــوم وانــه ذهــب بالقــرب مــن احلــدود‬\n‫العراقيــة لكــون هنــاك رجــل يريــد منــه مبلــغ مــن املــال ونفــى قيامــه‬\n‫بإطــاق النــار علــى أخيــه املجنــى عليــه وانــه ال يعلــم عــن احلادثــة شــيئا‬\n\n\n                                                                                      ‫‪24‬‬\n\f     ‫ونفــى عائديــه الســاح الــذي عثــر بســيارته لــه ‪.‬ومبواجهتــه بشــهادة ‪..... /‬‬\n     ‫أفــاد أنــه ال يعلــم هــل اتصــل عليــه يف ذلــك الوقــت ام ال ولكنــه لــم‬\n     ‫يتذكــر أنــه ســأله عــن منــزل أخيــه املجنــى عليــه لكونــه يعرفــه مــن‬\n     ‫قبــل وبالبحــث عــن ســوابقه ‪ /‬عثــر لــه علــى ســابقتني االولــى ســرقة‬\n     ‫حيوانــات واالخــرى مخالفــة لنظــام حــرس احلــدود ‪.‬ملــا أشــير إليــه أقــرر‬\n     ‫توجيــه اإل تهــام ل ـ ‪.....‬بالشــروع يف قتــل اخيــه املجنــى عليــه‪..... /‬وذلــك‬\n     ‫بإطــاق النــار عليــه عــدة طلقــات ممــا أدى إلــى إصابتــه باإلصابــات‬\n     ‫املوصوفــة بالتقريــر الطبــي املرفــق وحيازتــه للســاح املســدس املضبــوط‬\n     ‫الــذي يحمــل الرقــم‪ ) .....‬والســاح الرشــاش بــدون ترخيــص اجلهــة‬\n     ‫املختصــة وإخفائه‪.‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬ماجــاء يف أقــوال‬\n     ‫املجنــى عليــه املدونــة علــى الصفحــة رقم(‪)9-8-7‬مــن دفتــر التحقيــق‬\n     ‫رقم(‪-2)6‬مــا جــاء يف شــهادة الشــاهد املدونــة علــى الصفحــة رقــم (‬\n     ‫‪ )11-10‬مــن دفتــر التحقيــق رقــم (‪-3)6‬ماجــاء يف محضــر االنتقــال‬\n     ‫واملعاينــة املــدون علــى الصفحــة رقــم (‪ . )1‬مــن دفتــر التحقيــق رقــم‬\n     ‫(‪-4)2‬ماجــاء يف محضــر القبــض املتهــم لفــة رقــم (‪-5. )19‬ماجــاء يف‬\n     ‫التقريــر الطبــي املرفــق رقــم (‪-6 )14‬ماجــاء يف تقريــر األدلــة احلنائيــة‬\n     ‫لفــه رقــم(‪ )52‬وحيــث أن مــا أقــدم عليــه املذكــور فعــل معاقــب عليــه‬\n     ‫شــرع ًا ونظامــا ‪ .‬ممــا يتعــن معــه إحالتــه إلــى احملكمــة اجلزئيــة اســتنادا‬\n     ‫لنــص املــادة (‪ )126‬مــن نظــام اإلجــراءات اجلزائيــة للحكــم عليــه بعقوبــة‬\n     ‫تعزيريــة لقــاء ماأســند إليــه‪ ,‬وإحالــة مايتعلــق بحيــازة الســاح بــدون‬\n     ‫ترخيــص للمحكمــة اإلداريــة وفقــا للمادتــن(‪ )50-40‬مــن نظــام‬\n     ‫األســلحة والذخائــر الصــادر باملرســوم امللكــي رقــم م‪ 45/‬وتاريــخ‬\n     ‫‪1426/7/25‬ه ـ علمــا بــأن احلــق اخلاص مازال قائمــا هذه دعواي وبتالوة‬\n\n\n‫‪25‬‬\n\f‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف دعــوى‬\n‫املدعــي العــام كلــه غيــر صحيــح فأنــا لــم أطلــق النــار علــى أخــي ‪.....‬‬\n‫مطلقــا وأنــا ال يوجــد بينــي وبــن أخــي ‪.....‬أي عــداوة مطلقـ ًا وأنــا ال يوجــد‬\n‫لــدي أي ســاح وأنــا وقــت احلادثــة كنــت خــارج مدينــة الريــاض هــذا‬\n‫أجــاب ورفعــت اجللســة النتهــاء وقــت الــدوام الرســمي ولطلــب صاحــب‬\n‫احلــق اخلــاص وذلــك يــوم الثالثــاء املوافــق ‪1432/3/19‬ه ـ الســاعة احلادية‬\n‫عشــر واهلل املوفــق ‪ .‬ويف يــوم الثالثــاء ‪1432/3/19‬ه ـ أفتتحــت اجللســة‬\n‫الثانيــة الســاعة الثانيــة عشــر وفيهــا حضــر املدعي العــام وحضر حلضوره‬\n‫املدعــى عليــه ولــم يحضــر املدعــي باحلــق اخلــاص لــذا طلبــت مــن املدعــي‬\n‫العــام البينــة فطلــب مهلــة إلحضارهــا ورفعــت اجللســة لذلــك واهلل املوفــق‬\n‫‪ .‬ويف يــوم االثنــن املوافــق ‪1432/4/9‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 11‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد طلبــت مــن املدعــي‬\n‫العــام بينتــه فأجــاب بأنــه ولــم يتمكــن مــن إحضارهــا يف هــذا اليــوم لــذا‬\n‫فقــد رفعــت اجللســة إلحضارهــا وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫ويف يــوم الثالثــاء ‪1432/7/26‬ه ـ أفتتحــت اجللســة الســاعة العاشــرة‬\n‫والنصــف وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه‬\n‫الســجني وبســؤال املدعــي العــام عــن بينتــه أجــاب بقولــه أحضــرت أحــد‬\n‫الشــهود وأطلــب ســماع مــا لديــه حيــث حضــر ‪.....‬ســعودي بالبطاقــة رقــم‬\n‫‪.....‬مــن مواليــد ‪1403/12/21‬ه ـ يعمــل مبهنــة عســكري يف القــوات‬\n‫البريــة وبســؤاله أجــاب بقولــه أشــهد بــاهلل إن املدعــى عليــه عمــي أخ‬\n‫لوالــدي مــن األب وقــد اتصــل بــي يف يــوم حادثــة أطــاق النــار بعــد املغــرب‬\n‫يف شــهر رمضــان املاضــي وطلــب وصــف منــزل عمــي املجنــي عليــه ‪....‬‬\n‫فقلــت لــه مــاذا تريــد بالوصــف فقــال لــي يريــده رجــال ثــم وصــف لــي‬\n\n\n                                                                                        ‫‪26‬‬\n\f     ‫طريــق البيــت فقلــت لــه أنــت اآلن تعــرف طريــق بيتــه فلمــاذا تتصــل بــي‬\n     ‫فقــام بإنهــاء االتصــال ثــم اتصــل بــي بعــد خمــس دقائــق فقــال لــي أنــا اآلن‬\n     ‫عنــد البيــت ولونــه بيــج وعنــده ‪ .....‬بيضــاء ثــم قــال لــي هــل اجلماعــة‬\n     ‫ا اتصلــت بــي‬   ‫موجوديــن أم ال فقلــت ال أدري ويف الســاعة الواحــدة لي ـ ً‬\n     ‫الشــرطة وأخبرتنــي بالواقعــة وأن آخــر اتصــال يف جــوال املدعــى عليــه‬\n     ‫كان لــي وحضــرت للشــرطة وأدليــت مبثــل هــذه الشــهادة واهلل علــى مــا‬\n     ‫أقــول شــهيد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه أجــاب بقولــه‬\n     ‫ال صحــة ملــا جــاء يف شــهادة الشــاهد فأنــا لــم اتصــل بالشــاهد ألخــذ‬\n     ‫وصــف منــزل املجنــي عليــه وأنــا أعــرف وصــف منــزل املجنــي عليــه حيــث‬\n     ‫ســبق وأن ذهبــت أنــا والشــاهد وأخــي ‪ ...‬ملنــزل أخــي ‪ ....‬ولــم جنــده فأنــا‬\n     ‫ال أحتــاج ملعرفــة وصــف منزلــه أمــا مــا يتعلــق باالتصــال بــه فأنــا أتصــل‬\n     ‫علــى الشــاهد باســتمرار لكونــه مــن أقاربــي والشــاهد أبــن أخــي وليــس‬\n     ‫بينــي وبينــه أي عــداوة مســبقه إال إن كان يضمــر لــي احلقــد والبغضــاء‬\n     ‫فهــذا ال أعلمــه هكــذا أجــاب ثــم حضــر املدعــي باحلــق اخلــاص‪.....‬‬\n     ‫ســعودي بالبطاقــة رقــم ‪.....‬وبســؤاله أجــاب بقولــه إننــي أدعــي علــى‬\n     ‫املدعــى عليــه حيــث قــام بإطــاق عــدد عشــر طلقــات ناريــه مــن مســدس‬\n     ‫أصابتنــي يف الركبــه ويف الظهــر ويف الصــدر ويف اليــد اليمنــى ويف اليــد‬\n     ‫اليســرى ومواضــع أخــرى وقــد نتــج عــن ذلــك إصابتــي بشــلل يف رجلــي‬\n     ‫اليمنــى وبعــض اإلصابــات وقــد شــاهدته بنفســي أثنــاء إطالقــه النــار‬\n     ‫علــي وأطلــب تعزيــره لقــاء ذلــك تعزيــرا بليغــا هــذه دعــواي وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف دعــوى املدعــي‬\n     ‫باحلــق اخلــاص فأنــا لــم أطلــق النــار عليــه مطلقــا هكــذا أجــاب وبعــرض‬\n     ‫ذلــك علــى املدعــي باحلــق اخلــاص أجــاب بقولــه الصحيــح مــا جــاء يف‬\n\n\n‫‪27‬‬\n\f‫دعــواي واملدعــى عليــه ســبق أن هددنــي ولــدي البينــة علــى ذلــك ثــم‬\n‫أحضــر ‪.....‬ســعودي بالبطاقــة رقــم ‪.....‬مــن مواليــد ‪1404/4/15‬هـ ويعمل‬\n‫عســكري يف وزارة الدفــاع وبســؤاله أجــاب بقولــه إن املدعــي باحلــق‬\n‫اخلــاص واملدعــى عليــه همــا أعمامــي وأشــهد بــاهلل إنــي ســمعت بــأن‬\n‫املدعــى عليــه هــدد عمــي ‪.....‬فذهبــت إليــه فقــال لــي إنــي ال أريــده وليــس‬\n‫بينــي وبينــه أي عــداوه إال إننــي كنــت ســكرانا فاتصلــت وهــددت أخــي‬\n‫‪.....‬واهلل علــى مــا ٌأقــول شــهيد وبعــرض الشــاهد وشــهادته علــى املدعــى‬\n‫عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف شــهادة الشــاهد والشــاهد أبــن‬\n‫أخــي وليــس بينــي وبينــه أي عــداوة هكــذا أجــاب فســألت املدعــي باحلــق‬\n‫اخلــاص ألديــك زيــادة بينــه فأجــاب بقولــه ال بينــة لــدي ســوى مــا أحضــرت‬\n‫هكــذا أجــاب ثــم ســألت املدعــي العــام هــل لديــه زيــادة بينــه بخصــوص‬\n‫الدعــوى العامــة فأجــاب بقولــه أطلــب الرجــوع للمعاملــة واالطــاع علــى‬\n‫مــا فيهــا مــن أدلــة وقرائــن هكــذا أجــاب ورفعــت اجللســة لتزكيــة‬\n‫الشــاهدين ‪ .‬ويف يــوم الثالثــاء ‪1432/8/4‬ه ـ افتتحــت اجللســة اخلامســة‬\n‫الســاعة الواحــدة ظهــرا وقــد حضــر لتزكيــة الشــاهدين ‪..........‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪..........‬و‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n‫وبســؤالهما أجابــا بقولهمــا نشــهد بــاهلل إن الشــاهدين ‪ ..........‬و‪..........‬‬\n‫ثقتــان ذوا عــدل مرضيــا الشــهادة لنــا وعلينــا هكــذا شــهدا ورفعــت‬\n‫اجللســة إلــى يــوم الســبت ‪1432/8/8‬ه ـ واهلل املوفــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد ‪ .‬ويف يــوم الســبت ‪1432/8/8‬ه ـ أفتتحــت اجللســة‬\n‫السادســة الســاعة احلاديــة عشــرة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه وقــد حضــر عــن املدعــي باحلــق اخلــاص ‪..........‬‬\n‫ســعودي بالبطاقــة رقــم ‪..........‬بالوكالــة عــن أبيــه مبوجــب الوكالــة‬\n\n\n                                                                                      ‫‪28‬‬\n\f     ‫الصــادرة مــن كتابــة عــدل الثانيــة يف شــرق الريــاض برقــم ‪..........‬يف‬\n     ‫‪1432/1/5‬ه ـ اجللــد ‪..........‬والتــي تخولــه حــق املرافعــة واملدافعــة‬\n     ‫والقناعــة واالعتــراض وبالرجــوع للمعاملــة وجــد فيهــا لفــة رقــم ‪51-50‬‬\n     ‫تقريــر األدلــة اجلنائيــة حيــال األظــرف الفارغــة برقــم ‪..........‬ونــوع الســاح‬\n     ‫‪ ....‬الصنــع عيــار ‪ ....‬ملــم رقــم ‪..........‬مــع مخــزن ‪4 +‬ظــروف فارغــه عيــار‬\n     ‫‪ ....‬ملــم ‪2+‬ظــرف فــارغ والنتيجــة أن الظــروف الفارغــة والتــي عددهــا‬\n     ‫اربعــة ظــروف مطلقــه مــن املســدس املذكــور وهــو نــوع ‪ ....‬عيــار ‪.....‬أمــا‬\n     ‫الظرفــان الفارغــان املشــار عنهمــا عيــار‪.... ....‬ملــم مطلقــه مــن ســاح‬\n     ‫نــاري واحــد وتطلــق عــادة مــن األســلحة ذات العيــار نفســه ا ه ـ ‪ .‬وكــذا‬\n     ‫وجــد فيهــا خطــاب مديــر شــرطة منطقــة احلــدود الشــمالية رقــم ‪..........‬يف‬\n     ‫‪1431/10/3‬ه ـ املوجــه ملديــر شــرطة منطقــة الريــاض واملتضمن القبض‬\n     ‫علــى املدعــى عليــه وبرفقتــه ســيارة مســتأجرة ووجــد يف أســفل مقــود‬\n     ‫الســيارة وملفــوف بورقــة عقــد الســيارة مســدس ‪ .....‬الصنــع يحمــل الرقــم‬\n     ‫‪..........‬كمــا وجــد يف دفتــر التحقيــق لفــة رقــم ‪ 2‬محضــر االنتقــال‬\n     ‫واملعاينــه واملتضمــن العثــور علــى عــدد أربــع مقذوفــات مســدس ربــع‬\n     ‫وطلقــات رشــاش عــدد اثنــن فــوارغ ا ه ـ ‪ .‬وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه أجــاب بقولــه ال صحــة ملــا جــاء يف خطــاب مديــر شــرطة منطقــة‬\n     ‫احلدود الشــمالية من العثور معي على ســاح مســدس ‪ .....‬وهذا الســاح‬\n     ‫ال يعــود لــي وال يخصنــي هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعوى‬\n     ‫واإلجابــة وحيــث أنكــر املدعــى عليــه دعــوى املدعــي العــام واملدعــي‬\n     ‫باحلــق اخلــاص وحيــث إن مــا جــاء يف شــهادة الشــاهدين املعدلــن طبــق‬\n     ‫األصــول الشــرعية ومــا جــاء يف محضــر االنتقــال مــن العثــور علــى‬\n     ‫األظــرف الفارغــة وكــذا مــا جــاء يف خطــاب مديــر شــرطة احلــدود‬\n\n\n‫‪29‬‬\n\f‫الشــمالية مــن العثــور علــى املســدس الــذي انطلقــت منــه أربعــة مقذوفــا‬\n‫حســب قــرار األدلــة اجلنائيــة تــورث الشــبهة القويــة جتــاه املدعــى عليــه يف‬\n‫احلــق العــام وحيــث إن هــذه األمــور ال يثبــت بهــا احلــق اخلــاص فعليــه فقــد‬\n‫تقــرر مــا يلــي أوال ‪ :‬رددت دعــوى املدعــي باحلــق اخلــاص لعــدم كفايــة‬\n‫األدلــة يف إثباتــه ‪ .‬ثانيـ ًا ‪ :‬توجــه الشــبهة القويــة علــى قيــام املدعــى عليــه‬\n‫بإطــاق النــار علــى املجنــي عليــه وقــررت تعزيــره لقــاء ذلــك وذلــك‬\n‫بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده ثالثمائــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى‬\n‫عشــرة أيــام وبعرضــه علــى املدعــي العــام قــرر االعتــراض مكتفي ـ ًا‬\n‫بالئحــة الدعــوى أمــا املدعــي باحلــق اخلــاص فقــد قــرر عــدم القناعــة‬\n‫ويطلــب التمييــز بالئحــة أعتراضيــة وكــذا قــرر املدعــى عليــه عــدم‬\n‫القناعــة ويطلــب التمييــز بالئحــة اعتراضيــة وأفهمــا بــأن عليهمــا‬\n‫املراجعــة يــوم الســبت ‪1432/8/15‬ه ـ الســتالم نســخة مــن احلكــم‬\n‫لالعتــراض عليــه ملــدة ثالثــن يوم ـ ًا وإال ســقط حقهمــا يف االعتــراض‬\n‫ففهمــا ذلــك واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬ويف يــوم‬\n‫الثالثــاء ‪1433/3/8‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة مــن‬\n‫محكمة االستئناف وبرفقها القرار رقم ‪3337778‬يف ‪1433/1/22‬هـ‬\n‫ونص احلاجة منه وبدراســة القرار وصورة ضبطه والالئحة االعتراضية‬\n‫وأوراق املعاملــة لوحــظ أن رد دعــوى املدعــي باحلــق اخلــاص علــى هــذه‬\n‫الصفــة محــل نظــر واملتعــن تقريــر عقوبــة تعزيريــة للحــق اخلــاص ملــا حلــق‬\n‫باملدعــى عليــه مــن شــبهة قويــة فيمــا نســب لــه أو زيــادة العقوبــة الصــادرة‬\n‫يف احلــق العــام وإيضــاح مــا هــو حــق عــام ومــا هــو حــق خــاص منهمــا واهلل‬\n‫املوفــق ‪.‬أه ـ ‪ .‬فعليــه أجيــب أصحــاب الفضيلــة بأنــه يف هــذه اجللســة وفيهــا‬\n\n\n                                                                                          ‫‪30‬‬\n\f     ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه الســجني كمــا‬\n     ‫حضــر وكيــل املدعــي باحلــق اخلــاص ‪..........‬وجــرى ســؤال املدعــي باحلــق‬\n     ‫اخلــاص وكالــة عــن موكلــه فأجــاب بأنــه يتعالــج خــارج اململكــة ولــن‬\n     ‫يحضــر إال بعــد شــهرين هكــذا أجــاب فعليــه وألن مــا جــاء يف حيثيــات‬\n     ‫احلكــم يقــوي جانــب املدعــي باحلــق اخلــاص واليمــن تشــرع يف جانــب‬\n     ‫أقــوى املتداعــن وحيــث إن املدعــي باحلــق اخلــاص يف خــارج اململكــة ممــا‬\n     ‫يتعــذر معــه حضــوره وأداء اليمــن فعليــه وألن احلــق اخلــاص ال يثبــت‬\n     ‫بالشــبهة فإنــي الزلــت علــى مــا حكمــت بــه مــن رد دعــوى املدعــي باحلــق‬\n     ‫اخلــاص فأمــرت بإحلــاق ذلــك يف القــرار وإعــادة املعاملــة حملكمــة‬\n     ‫االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬ويف يــوم الثالثــاء‬\n     ‫‪1433/6/17‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n     ‫حلضــوره املدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫وبرفقها القرار رقم يف ‪1433/3/26‬هـ ونص احلاجة منه « وباالطالع‬\n     ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n     ‫علــى قرارنــا رقــم ‪/3337778‬ج‪/3‬ب وتاريــخ ‪1433/1/22‬ه ـ لوحــظ أن‬\n     ‫مــا اجــاب بــه فضيلتــه غيــر مقنــع إلعــادة النظــر وإجــراء مــا يلــزم علــى‬\n     ‫ضــوء قرارنــا املشــار إليــه أعــاه» أ‪.‬ه ـ فعليــه أجيــب أصحــاب الفضيلــة‬\n     ‫أنــه بتأمــل القضيــة وبعــد االســتخارة واستشــارة بعض أصحــاب الفضيلة‬\n     ‫القضــاة فقــد رجعــت عــن حكمــي الســابق يف الفقرتــن أو ًال وثاني ـ ًا‬\n     ‫وحيث إن ما جاء يف شــهادة الشــاهدين املعدليه طبق األصول الشــرعية‬\n     ‫وكــذا مــا جــاء يف محضــر االنتقــال مــن العثــور علــى األظــرف الفارعــة‬\n     ‫وخطــاب مديــر شــرطة احلــدود الشــمالية مــن العثــور علــى املســدس الــذي‬\n\n\n‫‪31‬‬\n\f‫انطلقــت منــه املقذوفــات يف الســيارة التــي يســتعملها املدعــى عليــه‬\n‫ومطابقــة ظرفــن فارغــن للســاح وحيــث إن هذيــن األمريــن كافيــان‬\n‫يف إثبــات دعــوى املدعــي اخلــاص والعــام فعليــه فقــد ثبــت لــدي قيــام‬\n‫املدعــى عليــه بإطــاق النــار علــى املدعــي باحلــق اخلــاص عــدة طلقــات‬\n‫ممــا أدى إلــى إصابتــه باإلصابــات املوصوفــة بالتقاريــر الطبيــة املرفقــة‬\n‫باملعاملــة وقــررت مايلــي ‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ثــاث ســنوات‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون‬\n‫جلــدة بينهمــا عشــرة وذلــك للحــق اخلــاص ‪ .‬ثانياً‪:‬ســجن املدعــى عليــه‬\n‫ســنتان مــن تاريــخ إيقافــه وجلــده مائتــي جلــده مفرقــه علــى أربــع دفعــات‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وبــن هــذا‬\n‫اجللــد واجللــد الــذي يف أو ًال عشــرة أيــام وبجميــع ذلــك حكمــت ‪ .‬وبعرضه‬\n‫علــى املدعــى العــام قــرر بأنــه ال زال معترضـ ًا أمــا املدعــى عليــه فقــد قــرر‬\n‫عــدم القناعــة ويرغــب رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة‬\n‫اعتراضيــة أمــا املدعــى باحلــق اخلــاص فلــم يحضــر وســيتم عــرض احلكــم‬\n‫عليــه حــال حضــوره واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه أجمعــن ‪ .‬ويف يــوم الســبت ‪1433/7/12‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضر‪..........‬ســعودي اجلنســية بالهويــة رقــم (‪)..........‬‬\n‫بالوكالــة عــن والــده مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫الثانيــة بشــرق الريــاض برقــم ‪..........‬يف ‪1432/1/5‬ه ـ اجللــد ‪..........‬والتي‬\n‫تخولــه حــق اإلقــرار واملرافعــة واملدافعــة وطلــب اســتئناف األحــكام‬\n‫ومتييزهــا والقناعــة بهــا واالعتــراض عليهــا وقــرر قائــا إن موكلــي‬\n‫والــدي غيــر مقتنــع باحلكــم األخيــر ونطلــب رفــع املعاملــة حملكمــة‬\n‫االســتئناف مكتفــن بالئحتنــا الســابقة هكــذا قــرر فعليــه فقــد أمــرت‬\n\n\n                                                                                         ‫‪32‬‬\n\f     ‫بضبطــه وإحلــاق ذلــك يف القــرار ورفــع املعاملــة حملكمــة االســتئناف‬\n     ‫لتدقيــق اإلجــراء حســب املتبــع واهلل املوفــق ‪ .‬احلمــد هلل وحــده وبعــد فقــد‬\n     ‫اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة لتمييــز القضايــا اجلزائيــة‬\n     ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n     ‫احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1433/12/1‬ه ـ املرفــق‬\n     ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.......... /‬‬\n     ‫املســجل برقــم وتاريــخ ‪1433/8/12‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n     ‫ضــد ‪.......... /‬يف قضيــة إطــاق نــار علــى النحو املوضــح بالقرار املتضمن‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه و بدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n     ‫وأحلقــه بالقــرار وصــورة ضبطــه وبنــاء علــى القــرار رقــم ‪331527704 /‬‬\n     ‫وتاريــخ ‪ 1433/3/26‬ه ـ لــم يظهــر لألكثريــة مــا يوجــب نقــض احلكــم‬\n     ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫اله وصحبه وسلم‪.‬‬\n\n\n\n\n‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":20,"source_page_end":33,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d87cae77e69dc68a971d5a50118af35ad1190a165866cdd142ac0c347e5a0173","normalized_text_hash":"0bde794bd790f136c76de40471a52a0410444067f6c36239eb33db4f41f46031","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p20-32203464"}]$archive_payload$::jsonb) AS x LIMIT 25
